// test/setup.js
const request = require('supertest');
const app = require('../src/app');
const db = require('../src/db');
const { createTestUser, generateProduct } = require('./helpers');

beforeAll(async () => {
    // Run migrations
    await db.migrate.latest();
});

afterAll(async () => {
