describe('Complete Order Workflow', () => {
    let user, product, orderId;

    beforeEach(async () => {
        user = await createTestUser();
        product = await createTestProduct({ stock: 10, price: 50 });
    });

    it('completes full order lifecycle', async () => {
        const token = await getAuthToken(user);
        const authedRequest = request(app).set('Authorization', `Bearer ${token}`);

        // 1. Create order
        const createResponse = await authedRequest
            .post('/api/orders')
            .send({
                items: [{ productId: product.id, quantity: 2 }],
                shippingAddress: {
                    street: '123 Main St',
                    city: 'Boston',
                    zip: '02101'
                }
            });

        expect(createResponse.status).toBe(201);
        orderId = createResponse.body.id;
        expect(createResponse.body.status).toBe('pending');
        expect(createResponse.body.total).toBe(100); // 50 * 2

        // 2. Verify stock reduced
        const productCheck = await request(app).get(`/api/products/${product.id}`);
        expect(productCheck.body.stock).toBe(8); // 10 - 2

        // 3. Process payment
        const paymentResponse = await authedRequest
            .post(`/api/orders/${orderId}/payment`)
            .send({
                cardToken: 'tok_visa',
                amount: 100
            });

        expect(paymentResponse.status).toBe(200);
        expect(paymentResponse.body.paymentStatus).toBe('success');

        // 4. Check order status updated
        const orderCheck = await authedRequest.get(`/api/orders/${orderId}`);
        expect(orderCheck.body.status).toBe('paid');

        // 5. Admin processes order
        const adminToken = await getAuthToken(await createTestUser({ role: 'admin' }));
        const processResponse = await request(app)
            .post(`/api/orders/${orderId}/process`)
            .set('Authorization', `Bearer ${adminToken}`);

        expect(processResponse.status).toBe(200);
        expect(processResponse.body.status).toBe('processing');

        // 6. Ship order
        const shipResponse = await request(app)
            .post(`/api/orders/${orderId}/ship`)
            .set('Authorization', `Bearer ${adminToken}`)
            .send({ trackingNumber: '1Z999AA10123456784' });

        expect(shipResponse.status).toBe(200);
        expect(shipResponse.body.status).toBe('shipped');
        expect(shipResponse.body.trackingNumber).toBeDefined();

        // 7. User marks as delivered
        const deliverResponse = await authedRequest
            .post(`/api/orders/${orderId}/deliver`);

        expect(deliverResponse.status).toBe(200);
        expect(deliverResponse.body.status).toBe('delivered');

        // 8. Verify final state
        const finalOrder = await authedRequest.get(`/api/orders/${orderId}`);
        expect(finalOrder.body.status).toBe('delivered');
        expect(finalOrder.body.deliveredAt).toBeDefined();
    });
});
