describe('Dynamic Schema Validation', () => {
    // Schema that depends on query parameters
    const getProductSchema = (includeDetails = false) => ({
        type: 'object',
        required: ['id', 'name', 'price'],
        properties: {
            id: { type: 'integer' },
            name: { type: 'string' },
            price: { type: 'number' },
            ...(includeDetails ? {
                description: { type: 'string' },
                specifications: { type: 'object' },
                reviews: {
                    type: 'array',
                    items: { type: 'object' }
                }
            } : {})
        }
    });

    it('returns minimal schema when details not requested', async () => {
        const response = await request(app)
            .get('/api/products/1');

        const schema = getProductSchema(false);
        const validate = ajv.compile(schema);

        expect(validate(response.body)).toBe(true);
        expect(response.body.description).toBeUndefined();
    });

    it('returns full schema when details requested', async () => {
        const response = await request(app)
            .get('/api/products/1?include=details');

        const schema = getProductSchema(true);
        const validate = ajv.compile(schema);

        expect(validate(response.body)).toBe(true);
        expect(response.body.description).toBeDefined();
    });
});
