// test/banking/errors.test.js
describe('Error Handling', () => {
    it('returns consistent error format for all 4xx errors', async () => {
        const errorScenarios = [
            { endpoint: '/api/accounts/999999', method: 'get', status: 404 },
            { endpoint: '/api/accounts', method: 'post', data: {}, status: 400 },
            { endpoint: '/api/accounts/1/withdraw', method: 'post', data: { amount: -100 }, status: 400 },
        ];

        for (const scenario of errorScenarios) {
            let response;
            if (scenario.method === 'get') {
                response = await request(app).get(scenario.endpoint);
            } else if (scenario.method === 'post') {
                response = await request(app).post(scenario.endpoint).send(scenario.data);
