```javascript
// test/payments/negative/process.test.js
const { request, app, getAuthToken, assertErrorResponse } = require('./setup');

describe('Payment Processing - Negative Tests', () => {
    let userToken;

    beforeEach(async () => {
        const user = await createTestUser();
        userToken = await getAuthToken(user);
    });

    describe('Input Validation', () => {
        // Missing fields tests
        const requiredFields = ['amount', 'currency', 'paymentMethod', 'customerId'];

        requiredFields.forEach(field => {
            it(`returns 400 when ${field} is missing`, async () => {
                const paymentData = {
                    amount: 1000,
                    currency: 'USD',
                    paymentMethod: 'card',
                    customerId: 'cust_123'
                };
                delete paymentData[field];

                const response = await request(app)
                    .post('/api/payments/process')
                    .set('Authorization', `Bearer ${userToken}`)
                    .send(paymentData);

                const error = await assertErrorResponse(response, 400);
                expect(error.details[field]).toBeDefined();
            });
        });

        // Data type tests
        const typeTests = [
            { field: 'amount', value: 'one thousand', expectedType: 'number' },
            { field: 'amount', value: true, expectedType: 'number' },
            { field: 'currency', value: 123, expectedType: 'string' },
            { field: 'currency', value: { code: 'USD' }, expectedType: 'string' },
            { field: 'paymentMethod', value: ['card'], expectedType: 'string' },
            { field: 'customerId', value: null, expectedType: 'string' }
        ];

        typeTests.forEach(({ field, value, expectedType }) => {
            it(`returns 400 when ${field} is ${typeof value} (expected ${expectedType})`, async () => {
                const paymentData = {
                    amount: 1000,
                    currency: 'USD',
                    paymentMethod: 'card',
                    customerId: 'cust_123',
                    [field]: value
                };

                const response = await request(app)
                    .post('/api/payments/process')
                    .set('Authorization', `Bearer ${userToken}`)
                    .send(paymentData);

                const error = await assertErrorResponse(response, 400);
                expect(error.details[field]).toBeDefined();
                expect(error.details[field].toLowerCase()).toContain(expectedType);
            });
        });

        // Boundary tests
        const boundaryTests = [
            { field: 'amount', value: 0, valid: false, reason: 'minimum' },
            { field: 'amount', value: 0.01, valid: true, reason: 'just above min' },
            { field: 'amount', value: 1000000, valid: true, reason: 'max' },
            { field: 'amount', value: 1000000.01, valid: false, reason: 'above max' },
            { field: 'amount', value: 10.001, valid: false, reason: 'too many decimals' }
        ];

        boundaryTests.forEach(({ field, value, valid, reason }) => {
            it(`${valid ? 'accepts' : 'rejects'} ${field}=${value} (${reason})`, async () => {
                const paymentData = {
                    amount: 1000,
                    currency: 'USD',
                    paymentMethod: 'card',
                    customerId: 'cust_123',
                    [field]: value
                };

                const response = await request(app)
                    .post('/api/payments/process')
                    .set('Authorization', `Bearer ${userToken}`)
                    .send(paymentData);

                if (valid) {
                    expect([200, 201, 202]).toContain(response.status);
                } else {
                    const error = await assertErrorResponse(response, 400);
                    expect(error.details[field]).toBeDefined();
                }
            });
        });

        // Currency validation
        it('rejects invalid currency codes', async () => {
            const invalidCurrencies = ['US', 'USA', 'dollar', '123', 'USSD'];

            for (const currency of invalidCurrencies) {
                const response = await request(app)
                    .post('/api/payments/process')
                    .set('Authorization', `Bearer ${userToken}`)
                    .send({
                        amount: 1000,
                        currency,
                        paymentMethod: 'card',
                        customerId: 'cust_123'
                    });

                const error = await assertErrorResponse(response, 400);
                expect(error.details.currency).toBeDefined();
            }
        });

        // Payment method validation
        it('rejects invalid payment methods', async () => {
            const invalidMethods = ['bitcoin', 'cash', 'check', 'crypto'];

            for (const method of invalidMethods) {
                const response = await request(app)
                    .post('/api/payments/process')
                    .set('Authorization', `Bearer ${userToken}`)
                    .send({
                        amount: 1000,
                        currency: 'USD',
                        paymentMethod: method,
                        customerId: 'cust_123'
                    });

                const error = await assertErrorResponse(response, 400);
                expect(error.details.paymentMethod).toBeDefined();
            }
        });
    });

    describe('Malformed Requests', () => {
        it('returns 400 for invalid JSON', async () => {
            const response = await request(app)
                .post('/api/payments/process')
                .set('Authorization', `Bearer ${userToken}`)
                .set('Content-Type', 'application/json')
                .send('{amount: 1000, currency: "USD"}'); // Invalid JSON

            await assertErrorResponse(response, 400);
        });

        it('returns 415 for wrong content type', async () => {
            const response = await request(app)
                .post('/api/payments/process')
                .set('Authorization', `Bearer ${userToken}`)
                .set('Content-Type', 'application/xml')
                .send('<payment><amount>1000</amount></payment>');

            expect(response.status).toBe(415);
        });

        it('rejects extremely large payloads', async () => {
            const largeData = {
                amount: 1000,
                currency: 'USD',
                paymentMethod: 'card',
                customerId: 'cust_123',
                metadata: {}
            };

            // Add 10MB of metadata
            largeData.metadata.largeField = 'x'.repeat(10 * 1024 * 1024);

            const response = await request(app)
                .post('/api/payments/process')
                .set('Authorization', `Bearer ${userToken}`)
                .send(largeData);

            expect([400, 413]).toContain(response.status);
        });
    });

    describe('Business Logic Validation', () => {
        it('prevents processing payment with insufficient balance', async () => {
            const response = await request(app)
                .post('/api/payments/process')
                .set('Authorization', `Bearer ${userToken}`)
                .send({
                    amount: 1000000, // More than balance
                    currency: 'USD',
                    paymentMethod: 'balance',
                    customerId: 'cust_123'
                });

            const error = await assertErrorResponse(response, 400);
