            const response = await request(app)
                .post('/api/checkout')
                .set('Authorization', `Bearer ${authToken}`)
                .send({
                    amount: 100,
                    paymentMethod: 'card',
                    cardToken: 'tok_visa'
                });

            expect(response.status).toBe(500);
        }

        // Next request should fail fast with circuit open
        const start = Date.now();

        const response = await request(app)
            .post('/api/checkout')
            .set('Authorization', `Bearer ${authToken}`)
            .send({
                amount: 100,
                paymentMethod: 'card',
                cardToken: 'tok_visa'
            });

