```javascript
describe('Concurrent Database Integration', () => {
    let db;

    beforeAll(() => {
        db = getTestDatabase();
    });

    it('handles concurrent inventory updates correctly', async () => {
        // Set initial stock
        await db.query('UPDATE products SET stock = 10 WHERE id = $1', [123]);

        // Simulate 5 concurrent orders
        const promises = [];
        for (let i = 0; i < 5; i++) {
            promises.push(
                (async () => {
                    const client = await db.connect();
                    try {
                        await client.query('BEGIN');

                        // Check stock
                        const stockResult = await client.query(
                            'SELECT stock FROM products WHERE id = $1 FOR UPDATE',
                            [123]
                        );

                        const currentStock = stockResult.rows[0].stock;

                        if (currentStock >= 2) {
                            // Update inventory
                            await client.query(
                                'UPDATE products SET stock = stock - 2 WHERE id = $1',
                                [123]
                            );

                            // Create order
                            await client.query(
                                'INSERT INTO orders (user_id, total, status) VALUES ($1, $2, $3)',
                                [1, 200, 'completed']
                            );

                            await client.query('COMMIT');
                            return { success: true };
                        } else {
                            await client.query('ROLLBACK');
                            return { success: false };
                        }
                    } finally {
                        client.release();
                    }
                })()
            );
        }

        const results = await Promise.all(promises);

        // Count successful orders
        const successfulOrders = results.filter(r => r.success).length;

        // With 10 stock and each order takes 2, max 5 orders
        expect(successfulOrders).toBe(5);

        // Verify final stock is 0
        const finalStock = await db.query('SELECT stock FROM products WHERE id = $1', [123]);
        expect(finalStock.rows[0].stock).toBe(0);
    });
});
