Message queues enable asynchronous communication between services. Testing them requires verifying that messages are published, consumed, and processed correctly.

**Message Queue Testing Challenges**:

| Challenge | Description | Solution |
|-----------|-------------|----------|
| **Asynchronicity** | Messages processed later | Polling, event listeners |
| **Ordering** | Messages may arrive out of order | Sequence IDs, timestamps |
| **Duplicates** | At-least-once delivery may duplicate | Idempotent consumers |
| **Failures** | Processing may fail | Retry queues, dead letters |
| **Timing** | Variable processing times | Timeouts, eventual assertions |

**Setting Up Message Queue for Testing**:

```javascript
// test/queue/setup.js
const { Kafka } = require('kafkajs');
const { RabbitMQ } = require('amqplib');

class TestMessageQueue {
    constructor() {
        this.messages = [];
        this.subscribers = new Map();
    }

    async publish(topic, message) {
        const msg = {
            id: `msg-${Date.now()}-${Math.random()}`,
            topic,
            message,
            timestamp: new Date().toISOString()
        };

        this.messages.push(msg);

        // Notify subscribers
        const subscribers = this.subscribers.get(topic) || [];
        subscribers.forEach(cb => cb(msg));

        return msg.id;
    }

    async subscribe(topic, callback) {
        if (!this.subscribers.has(topic)) {
            this.subscribers.set(topic, []);
        }
        this.subscribers.get(topic).push(callback);
    }

    async waitForMessage(topic, predicate, timeout = 5000) {
        const start = Date.now();

        return new Promise((resolve, reject) => {
            const checkMessages = () => {
                const messages = this.messages.filter(m => 
                    m.topic === topic && predicate(m.message)
                );

                if (messages.length > 0) {
                    resolve(messages[0]);
                } else if (Date.now() - start > timeout) {
                    reject(new Error(`Timeout waiting for message on ${topic}`));
                } else {
                    setTimeout(checkMessages, 100);
                }
            };

            checkMessages();
        });
    }

    clear() {
        this.messages = [];
        this.subscribers.clear();
    }
}

// Use test double in tests
const testQueue = new TestMessageQueue();

// Inject into services
app.set('messageQueue', testQueue);
```

