**Dependency Graph-Based Selection**:

```javascript
// test/regression/dependency-graph.js
class DependencyGraph {
    constructor() {
        this.nodes = new Map(); // file -> { tests, dependents }
        this.buildGraph();
    }

    buildGraph() {
        // Parse import/require statements in codebase
        // Build graph of file dependencies
        const files = this.getAllSourceFiles();

        for (const file of files) {
            const dependencies = this.extractDependencies(file);
            this.nodes.set(file, {
                dependencies,
                tests: this.findTestsForFile(file),
                dependents: new Set()
            });
        }

        // Build reverse dependencies
        for (const [file, node] of this.nodes) {
            for (const dep of node.dependencies) {
                if (this.nodes.has(dep)) {
                    this.nodes.get(dep).dependents.add(file);
                }
            }
        }
    }

    findAffectedFiles(changedFiles) {
        const affected = new Set(changedFiles);
        const queue = [...changedFiles];

        // BFS to find all files that depend on changed files
        while (queue.length > 0) {
            const file = queue.shift();
            const node = this.nodes.get(file);

            if (node) {
                for (const dependent of node.dependents) {
                    if (!affected.has(dependent)) {
                        affected.add(dependent);
                        queue.push(dependent);
                    }
                }
            }
        }

        return Array.from(affected);
    }

    selectTests(changedFiles) {
        const affectedFiles = this.findAffectedFiles(changedFiles);
        const tests = new Set();

        for (const file of affectedFiles) {
            const node = this.nodes.get(file);
            if (node && node.tests) {
                node.tests.forEach(test => tests.add(test));
            }
        }

        return Array.from(tests);
    }
}
