**Historical Data-Based Selection**:

```javascript
// test/regression/historical-selector.js
class HistoricalTestSelector {
    constructor() {
        this.history = this.loadTestHistory();
        this.failurePatterns = this.analyzeFailurePatterns();
    }

    loadTestHistory() {
        // Load test history from CI database
        // Format: {
        //   testName: {
        //     failures: [
        //       { commit: 'abc123', files: ['file1.js', 'file2.js'], timestamp }
        //     ]
        //   }
        // }
        return JSON.parse(fs.readFileSync('./test-history.json', 'utf8'));
    }

    analyzeFailurePatterns() {
        const patterns = {};

        for (const [testName, data] of Object.entries(this.history)) {
            const fileFrequency = {};

            for (const failure of data.failures) {
                for (const file of failure.files) {
                    fileFrequency[file] = (fileFrequency[file] || 0) + 1;
                }
            }

            // Calculate probability that changing a file will cause test to fail
            patterns[testName] = fileFrequency;
        }

        return patterns;
    }

    selectTests(changedFiles, threshold = 0.3) {
        const selectedTests = new Set();

        for (const file of changedFiles) {
            for (const [testName, patterns] of Object.entries(this.failurePatterns)) {
                const probability = patterns[file] || 0;
                if (probability > threshold) {
                    selectedTests.add(testName);
                }
            }
        }

        return Array.from(selectedTests);
    }
}
