# .github/workflows/regression.yml
name: Regression Tests
on:
  pull_request:
    types: [opened, synchronize]

jobs:
  select-tests:
    runs-on: ubuntu-latest
    outputs:
      test-command: ${{ steps.select.outputs.test-command }}
    steps:
      - uses: actions/checkout@v3
        with:
          fetch-depth: 0  # Get full history for git diff

      - name: Select tests
        id: select
        run: |
          CHANGED_FILES=$(git diff --name-only origin/main HEAD)

          # If critical files changed, run all tests
          if echo "$CHANGED_FILES" | grep -qE "package.json|jest.config.js"; then
            echo "test-command=npm run test:all" >> $GITHUB_OUTPUT
          else
            # Run selective tests
            SELECTED=$(node scripts/select-tests.js "$CHANGED_FILES")
            echo "test-command=npm run test -- $SELECTED" >> $GITHUB_OUTPUT
          fi

  run-tests:
    needs: select-tests
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
      - uses: actions/setup-node@v3
      - run: npm ci
      - run: ${{ needs.select-tests.outputs.test-command }}
