**Regression Test Runner with Smart Selection**:

```javascript
// scripts/run-regression.js
const { execSync } = require('child_process');
const fs = require('fs');

class RegressionRunner {
    constructor(options = {}) {
        this.testLevel = options.level || process.env.TEST_LEVEL || 'full';
        this.changedFiles = this.getChangedFiles();
        this.impactAnalysis = this.analyzeImpact();
    }

    getChangedFiles() {
        if (process.env.CHANGED_FILES) {
            return JSON.parse(process.env.CHANGED_FILES);
        }

        try {
            const output = execSync('git diff --name-only origin/main HEAD', { encoding: 'utf8' });
            return output.split('\n').filter(Boolean);
        } catch (error) {
            console.warn('Could not determine changed files, running all tests');
            return [];
        }
    }

    analyzeImpact() {
        const impact = {
            critical: false,
            database: false,
            api: false,
            services: new Set()
        };

        for (const file of this.changedFiles) {
            if (file.includes('database/') || file.includes('migrations/')) {
                impact.database = true;
                impact.critical = true;
            }
            if (file.includes('api/') || file.includes('controllers/')) {
                impact.api = true;
            }
            if (file.includes('services/')) {
                const service = file.split('/')[1];
                impact.services.add(service);
            }
        }

        return impact;
    }

    selectTests() {
        if (this.testLevel === 'smoke') {
            return this.selectSmokeTests();
        }

        if (this.impactAnalysis.critical) {
            return 'Run all tests';
        }

        const testPatterns = [];

        if (this.impactAnalysis.database) {
            testPatterns.push('database|migrations');
        }

        if (this.impactAnalysis.api) {
            testPatterns.push('api|controllers');
        }

        for (const service of this.impactAnalysis.services) {
            testPatterns.push(service);
        }

        if (testPatterns.length === 0) {
            return 'Run minimal smoke tests';
        }

        return `Run tests matching: ${testPatterns.join('|')}`;
    }

    async run() {
        console.log('🔍 Regression Test Runner');
        console.log('Level:', this.testLevel);
        console.log('Changed files:', this.changedFiles.length);
        console.log('Impact analysis:', this.impactAnalysis);
        console.log('Test selection:', this.selectTests());

        // Execute tests based on selection
        const startTime = Date.now();

        try {
            if (this.testLevel === 'smoke') {
                execSync('npm run test:smoke', { stdio: 'inherit' });
            } else if (this.impactAnalysis.critical) {
                execSync('npm run test:all', { stdio: 'inherit' });
            } else {
                // Run selected tests
                // ...
            }

            const duration = Date.now() - startTime;
            console.log(`✅ Regression tests passed in ${duration}ms`);
        } catch (error) {
            console.error('❌ Regression tests failed');
            process.exit(1);
        }
    }
}

if (require.main === module) {
    const runner = new RegressionRunner();
    runner.run();
}
