**Session Management Tool**:

```javascript
// session-manager.js
class SessionManager {
    constructor() {
        this.activeSession = null;
        this.sessions = [];
        this.debriefQuestions = [
            'What did you test?',
            'What did you find?',
            'What worked well?',
            'What unexpected behavior did you see?',
            'What assumptions were wrong?',
            'What was harder than expected?',
            'What questions do you have?',
            'What needs more investigation?',
            'What would you do differently next time?',
            'What should we test next?',
            'What areas need deeper exploration?',
            'What tools would help?'
        ];
    }

    startSession(charter) {
        this.activeSession = {
            id: `session-${Date.now()}`,
            charter,
            startTime: new Date().toISOString(),
            activities: [],
            findings: [],
            questions: [],
            notes: '',
            metrics: {
                testIdeas: 0,
                bugsFound: 0,
                coverage: 0
            }
        };

        console.log(`🚀 Session started: ${charter.title}`);
        console.log(`Mission: ${charter.mission}`);
        console.log(`Timebox: ${charter.timebox} minutes`);

        return this.activeSession;
    }

    logActivity(activity) {
        if (!this.activeSession) {
            console.warn('No active session to log activity');
            return;
        }

        const activityEntry = {
            timestamp: new Date().toISOString(),
            ...activity
        };

        this.activeSession.activities.push(activityEntry);
        this.activeSession.metrics.testIdeas++;

        return activityEntry;
    }

    addFinding(finding) {
        if (!this.activeSession) {
            console.warn('No active session to add finding');
            return;
        }

        const findingEntry = {
            id: `finding-${Date.now()}-${this.activeSession.findings.length}`,
            timestamp: new Date().toISOString(),
            ...finding
        };

        this.activeSession.findings.push(findingEntry);
        this.activeSession.metrics.bugsFound++;

        // Log based on severity
        const severityIcon = {
            critical: '🔴',
            high: '🟠',
            medium: '🟡',
            low: '🔵',
            info: '⚪'
        }[finding.severity] || '⚪';

        console.log(`${severityIcon} Finding: ${finding.title} (${finding.severity})`);

        return findingEntry;
    }

    addQuestion(question) {
        if (!this.activeSession) {
            console.warn('No active session to add question');
            return;
        }

        const questionEntry = {
            timestamp: new Date().toISOString(),
            question
        };

        this.activeSession.questions.push(questionEntry);
        console.log(`❓ Question: ${question}`);

        return questionEntry;
    }

    addNote(note) {
        if (!this.activeSession) return;
        this.activeSession.notes += `\n${new Date().toLocaleTimeString()}: ${note}`;
    }

    updateCoverage(percentage) {
        if (!this.activeSession) return;
        this.activeSession.metrics.coverage = percentage;
    }

    endSession() {
        if (!this.activeSession) {
            console.warn('No active session to end');
            return null;
        }

        this.activeSession.endTime = new Date().toISOString();
        this.activeSession.duration = this.calculateDuration(
            this.activeSession.startTime,
            this.activeSession.endTime
        );

        this.sessions.push(this.activeSession);

        console.log(`\n✅ Session ended: ${this.activeSession.charter.title}`);
        console.log(`Duration: ${this.activeSession.duration.toFixed(1)} minutes`);
        console.log(`Findings: ${this.activeSession.findings.length}`);
        console.log(`Questions: ${this.activeSession.questions.length}`);

        const completed = this.activeSession;
        this.activeSession = null;

        return completed;
    }

    calculateDuration(startTime, endTime) {
        const start = new Date(startTime);
        const end = new Date(endTime);
        return (end - start) / 60000; // Duration in minutes
    }

    getActiveSession() {
        return this.activeSession;
    }

    getAllSessions() {
        return this.sessions;
    }

    generateReport(sessionId) {
        const session = this.sessions.find(s => s.id === sessionId) || this.activeSession;
        if (!session) return null;

        const findingsBySeverity = session.findings.reduce((acc, finding) => {
            acc[finding.severity] = (acc[finding.severity] || 0) + 1;
            return acc;
        }, {});

        return {
            summary: {
                id: session.id,
                charter: session.charter.title,
                mission: session.charter.mission,
                duration: session.duration,
                activities: session.activities.length,
                findings: session.findings.length,
                questions: session.questions.length,
                findingsBySeverity
            },
            findings: session.findings.map(f => ({
                title: f.title,
                severity: f.severity,
                description: f.description,
                steps: f.steps
            })),
            questions: session.questions.map(q => q.question),
            timeline: session.activities.map(a => ({
                time: new Date(a.timestamp).toLocaleTimeString(),
                action: a.action,
                details: a.details
            })),
            metrics: this.calculateMetrics(session),
            notes: session.notes,
            debriefQuestions: this.generateDebriefQuestions(session)
        };
    }

    calculateMetrics(session) {
        const findingsPerHour = (session.findings.length / session.duration) * 60;

        return {
            findingsPerHour: findingsPerHour.toFixed(1),
            coverage: session.metrics.coverage,
            criticalFindings: session.findings.filter(f => f.severity === 'critical').length,
            highFindings: session.findings.filter(f => f.severity === 'high').length,
            mediumFindings: session.findings.filter(f => f.severity === 'medium').length,
            lowFindings: session.findings.filter(f => f.severity === 'low').length,
            followUpNeeded: session.questions.length,
            testIdeas: session.metrics.testIdeas
        };
    }

    generateDebriefQuestions(session) {
        const questions = [];

        if (session.findings.length > 0) {
            questions.push('What was the most interesting finding?');
        }

        if (session.questions.length > 0) {
            questions.push('Which question should we prioritize?');
        }

        if (session.metrics.coverage < 50) {
            questions.push('Why was coverage low? Time constraints? Technical issues?');
        }

        if (session.findings.some(f => f.severity === 'critical')) {
            questions.push('Should we stop and fix critical issues before continuing?');
        }

        return questions;
    }

    async conductDebrief(sessionId) {
        const session = this.sessions.find(s => s.id === sessionId);
        if (!session) return null;

        console.log('\n📋 Session Debrief');
        console.log('==================');

        const debrief = {
            session: session.charter.title,
            questions: [],
            actionItems: []
        };

        // What happened?
        console.log('\n🔍 What did you test?');
        const areasTested = [...new Set(session.activities.map(a => a.area))];
        areasTested.forEach(area => console.log(`  • ${area}`));
        debrief.areasTested = areasTested;

        // What did you find?
        console.log('\n🐛 What did you find?');
        session.findings.forEach(f => {
            const icon = { critical: '🔴', high: '🟠', medium: '🟡', low: '🔵' }[f.severity] || '⚪';
            console.log(`  ${icon} ${f.title} (${f.severity})`);
        });

        // What was surprising?
        console.log('\n😲 What unexpected behavior did you see?');
        const unexpected = session.findings.filter(f => f.unexpected);
        unexpected.forEach(f => console.log(`  • ${f.description}`));

        // What questions remain?
        console.log('\n❓ What questions do you have?');
        session.questions.forEach(q => console.log(`  • ${q.question}`));

        // Action items
        console.log('\n📝 Action Items:');
        const actions = this.generateActionItems(session);
        actions.forEach((action, i) => console.log(`  ${i+1}. ${action}`));
        debrief.actionItems = actions;

        return debrief;
    }

    generateActionItems(session) {
        const actions = [];

        // Create tickets for findings
        session.findings.forEach(finding => {
            if (finding.severity === 'critical' || finding.severity === 'high') {
                actions.push(`Create bug ticket for: ${finding.title}`);
            }
        });

        // Schedule follow-up sessions
        if (session.questions.length > 3) {
            actions.push('Schedule follow-up session to explore unanswered questions');
        }

        // Update documentation
        if (session.findings.some(f => f.type === 'documentation')) {
            actions.push('Update API documentation based on findings');
        }

        // Share findings
        actions.push('Share session findings with the team');

        return actions;
    }

    exportSessionsToMarkdown() {
        let markdown = '# Exploratory Testing Sessions\n\n';

        this.sessions.forEach((session, index) => {
            markdown += `## Session ${index + 1}: ${session.charter.title}\n`;
            markdown += `- **Date**: ${new Date(session.startTime).toLocaleDateString()}\n`;
            markdown += `- **Duration**: ${session.duration.toFixed(1)} minutes\n`;
            markdown += `- **Findings**: ${session.findings.length}\n`;
            markdown += `- **Questions**: ${session.questions.length}\n\n`;
        });

        return markdown;
    }
}

// Example usage
async function runExampleSession() {
    const manager = new SessionManager();

    // Start session
    const session = manager.startSession({
        title: 'Payment API Error Handling',
        mission: 'Explore how the payment API handles invalid inputs',
        timebox: 60,
        areas: ['invalid cards', 'expired cards', 'insufficient funds']
    });

    // Log activities
    manager.logActivity({
        action: 'Test invalid card number',
        area: 'invalid cards',
        details: 'Used card 1234-5678-9012-3456',
        result: '400 Bad Request - Good'
    });

    // Add finding
    manager.addFinding({
        title: 'SQL error exposed',
        severity: 'critical',
        description: 'Error message leaked database table name',
        steps: 'Send malformed request that causes DB error',
        unexpected: true
    });

    // Add question
    manager.addQuestion('Should we use idempotency keys by default?');

    // Update coverage
    manager.updateCoverage(65);

    // End session
    const completed = manager.endSession();

    // Generate report
    const report = manager.generateReport(completed.id);
    console.log(JSON.stringify(report, null, 2));

    // Conduct debrief
    await manager.conductDebrief(completed.id);

    return report;
}
