    console.log('==================');

    for (const [category, questions] of Object.entries(debriefQuestions)) {
        console.log(`\n${category.toUpperCase()}:`);
        questions.forEach(question => {
            const answer = answers[question] || '(not answered)';
            console.log(`  Q: ${question}`);
            console.log(`  A: ${answer}\n`);
        });
    }

    // Generate action items
    const actions = generateActionItems(session, answers);
    console.log('\n📝 Action Items:');
    actions.forEach((action, i) => console.log(`  ${i+1}. ${action}`));

    return actions;
}

function generateActionItems(session, answers) {
    const actions = [];

    // Create tickets for bugs
    session.findings.forEach(finding => {
        if (finding.severity === 'critical' || finding.severity === 'high') {
            actions.push(`Create bug ticket: ${finding.title}`);
        }
    });

    // Schedule follow-up
    if (session.questions.length > 3 || answers['What needs more investigation?']) {
        actions.push('Schedule follow-up exploratory session');
    }

    // Update documentation
    if (answers['What was surprising?'] || session.findings.some(f => f.type === 'documentation')) {
        actions.push('Update API documentation with clarifications');
    }

    // Share knowledge
    actions.push('Share findings in team meeting');

    return actions;
}
