**Exploratory Testing Toolkit**:

```javascript
// exploratory-toolkit.js
class ExploratoryToolkit {
    constructor(baseURL) {
        this.baseURL = baseURL;
        this.history = [];
        this.variables = {};
    }

    // Quick request builder
    async request(method, path, options = {}) {
        const url = new URL(path, this.baseURL);

        // Add query params
        if (options.query) {
            Object.entries(options.query).forEach(([key, value]) => {
                url.searchParams.append(key, value);
            });
        }

        const request = {
            method,
            url: url.toString(),
            headers: options.headers || {},
            body: options.body
        };

        const start = Date.now();
        let response;

        try {
            response = await fetch(url, {
                method,
                headers: request.headers,
                body: options.body ? JSON.stringify(options.body) : undefined
            });

            const responseBody = await response.text();

            const result = {
                request,
                response: {
                    status: response.status,
                    headers: Object.fromEntries(response.headers),
                    body: this.tryParseJSON(responseBody),
                    raw: responseBody
                },
                duration: Date.now() - start,
                timestamp: new Date().toISOString()
            };

            this.history.push(result);

            // Auto-save interesting responses
            if (response.status >= 400) {
                this.saveInteresting(result);
            }

            return result;
        } catch (error) {
            const result = {
                request,
                error: error.message,
                duration: Date.now() - start,
                timestamp: new Date().toISOString()
            };

            this.history.push(result);
            this.saveInteresting(result);

            return result;
        }
    }

    // Quick shortcuts
    get(path, query) {
        return this.request('GET', path, { query });
    }

    post(path, body) {
        return this.request('POST', path, { 
            body,
            headers: { 'Content-Type': 'application/json' }
        });
    }

    put(path, body) {
        return this.request('PUT', path, { 
            body,
            headers: { 'Content-Type': 'application/json' }
        });
    }

    delete(path) {
        return this.request('DELETE', path);
    }

    // Parameter variation
    async vary(endpoint, param, values) {
        const results = [];

        for (const value of values) {
            const result = await this.get(endpoint, { [param]: value });
            results.push({
                value,
                status: result.response?.status,
                duration: result.duration
            });
        }

        return results;
    }

    // Sequential testing
    async sequence(operations) {
        const results = [];

        for (const op of operations) {
            const result = await this[op.method](op.path, op.data);
            results.push(result);

            // Store returned data for next requests
            if (op.saveAs && result.response?.body) {
                this.variables[op.saveAs] = result.response.body;
            }
        }

        return results;
    }

    // Parallel testing
    async parallel(operations) {
        return Promise.all(
            operations.map(op => this[op.method](op.path, op.data))
        );
    }

    // Save interesting findings
    saveInteresting(result) {
        const findings = this.loadFindings();

        findings.push({
            ...result,
            savedAt: new Date().toISOString(),
            notes: ''
        });

        localStorage.setItem('exploratory-findings', JSON.stringify(findings));
    }

    // Generate report
    generateReport() {
        const findings = this.loadFindings();

        return {
            totalRequests: this.history.length,
            interestingFindings: findings.length,
            byStatus: this.groupByStatus(),
            slowRequests: this.history.filter(r => r.duration > 1000),
            errorRequests: this.history.filter(r => r.response?.status >= 400),
            timeline: this.history
        };
    }

    // Helpers
    tryParseJSON(text) {
        try {
            return JSON.parse(text);
        } catch {
            return text;
        }
    }

    groupByStatus() {
        const groups = {};

        for (const req of this.history) {
            const status = req.response?.status || 'error';
            groups[status] = (groups[status] || 0) + 1;
        }

        return groups;
    }
}
```

