        newClient = {
            // Client expects new fields that don't exist in old API
            parseResponse: (response) => ({
                id: response.id,
                name: response.name,
                email: response.email,
                // New field that old API doesn't have
                profile: response.profile || {},
                // New enum values
                status: response.status || 'unknown'
            }),

            // Client sends new fields that old API should ignore
            buildRequest: (data) => ({
                name: data.name,
                email: data.email,
                // New fields that old API should ignore
                preferences: data.preferences || {},
                source: data.source || 'mobile-app'
            })
        };

        oldAPI = request('https://api-v1.example.com');
    });

    it('new client can parse old responses (ignores missing fields)', async () => {
        const response = await oldAPI.get('/users/123');

        // New client should still work with old response
        const parsed = newClient.parseResponse(response.body);

        expect(parsed.id).toBeDefined();
        expect(parsed.name).toBeDefined();
        expect(parsed.email).toBeDefined();
        expect(parsed.profile).toBeDefined(); // Should default to {}
        expect(parsed.status).toBe('unknown'); // Should default to 'unknown'
    });

    it('new client can send new fields (old API ignores them)', async () => {
        const requestData = newClient.buildRequest({
            name: 'John Doe',
            email: 'john@example.com',
            preferences: { theme: 'dark' },
            source: 'mobile-app'
        });

        const response = await oldAPI
            .post('/users')
            .send(requestData);

        // Should succeed even though old API doesn't know about new fields
        expect(response.status).toBe(201);

        // Verify the new fields weren't stored (or were ignored)
        const user = await oldAPI.get(`/users/${response.body.id}`);
        expect(user.body.preferences).toBeUndefined();
    });

    it('handles unknown enum values gracefully', async () => {
        // Old API might return enum values that new client doesn't know about
        // or new client might send enum values old API doesn't know about

        // Test 1: Old API returns unknown enum to new client
        const oldResponse = await oldAPI.get('/orders/123');
        // Assume old API returns status: 'shipped' (exists in v1)
        // New client knows about 'shipped', 'delivered', 'cancelled', but also 'processing'

        const newClientParse = (status) => {
            // New client should handle unknown values gracefully
            const validStatuses = ['pending', 'paid', 'shipped', 'delivered', 'cancelled'];
            return validStatuses.includes(status) ? status : 'unknown';
        };

        expect(newClientParse('shipped')).toBe('shipped');
        expect(newClientParse('processing')).toBe('unknown'); // Unknown value handled

        // Test 2: New client sends unknown enum to old API
        const response = await oldAPI
            .post('/orders')
            .send({
                productId: 123,
                status: 'processing' // New status not in old API
            });

        // Old API should either:
        // - Accept it (if it ignores unknown values)
        // - Reject with clear error (if validation is strict)
        expect([201, 400]).toContain(response.status);

        if (response.status === 400) {
            expect(response.body.error.message).toContain('status');
        }
    });

    it('supports content negotiation for versioning', async () => {
        // New client can request specific version via Accept header
        const response = await oldAPI
            .get('/users/123')
            .set('Accept', 'application/vnd.api.v2+json');

        // Old API might:
        // - Return v1 format (if it ignores Accept)
        // - Return 406 Not Acceptable
        // - Return v2 format if it supports multiple versions

        expect([200, 406]).toContain(response.status);

        if (response.status === 200) {
            // Should still be parseable by new client
            const parsed = newClient.parseResponse(response.body);
            expect(parsed.id).toBeDefined();
        }
    });
});
