**Monitoring Deprecated Usage**:

```javascript
// deprecation/usage-monitoring.js
class DeprecationMonitor {
    constructor() {
        this.usage = new Map();
    }

    trackRequest(req, res) {
        const endpoint = req.path;
        const version = req.headers['accept-version'] || 'v1';
        const userAgent = req.headers['user-agent'];

        const key = `${version}:${endpoint}`;

        if (!this.usage.has(key)) {
            this.usage.set(key, {
                count: 0,
                userAgents: new Set(),
                firstSeen: new Date(),
                lastSeen: new Date()
            });
        }

        const stats = this.usage.get(key);
        stats.count++;
        stats.userAgents.add(userAgent);
        stats.lastSeen = new Date();

        // Check if this is a deprecated endpoint
        if (this.isDeprecated(endpoint, version)) {
            this.notifyDeprecatedUsage(endpoint, version, stats);
        }
    }

    isDeprecated(endpoint, version) {
        // Check deprecation database
        return true; // Simplified
    }

    notifyDeprecatedUsage(endpoint, version, stats) {
        if (stats.count === 1) {
            // First usage - log
            console.log(`⚠️ Deprecated endpoint used: ${version}${endpoint}`);
        } else if (stats.count % 100 === 0) {
            // Periodic reminder
            console.log(`⚠️ Deprecated endpoint ${version}${endpoint} used ${stats.count} times`);
        }
    }

    getDeprecationReport() {
        const report = [];

        for (const [key, stats] of this.usage.entries()) {
            const [version, endpoint] = key.split(':');
            if (this.isDeprecated(endpoint, version)) {
                report.push({
                    endpoint,
                    version,
                    usage: stats.count,
                    uniqueClients: stats.userAgents.size,
                    lastSeen: stats.lastSeen
                });
            }
        }

        return report.sort((a, b) => b.usage - a.usage);
    }
}
```

**Key Insight**: Deprecation is about communication. Test not just that deprecated features stop working, but that clients receive clear, timely warnings and migration guidance.

A comprehensive compatibility testing framework combines all the elements we've discussed into an automated pipeline that runs on every change.

**Compatibility Testing Pipeline**:

```yaml
# .github/workflows/compatibility.yml
name: Compatibility Tests
on:
  pull_request:
    paths:
      - 'openapi/**'
      - 'src/**'

jobs:
  breaking-change-detection:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
        with:
          fetch-depth: 0

      - name: Get base OpenAPI spec
        run: |
          git show origin/main:openapi/spec.yaml > base-spec.yaml

      - name: Detect breaking changes
        run: |
          node scripts/detect-breaking-changes.js \
            --old base-spec.yaml \
            --new openapi/spec.yaml

  backward-compatibility:
    runs-on: ubuntu-latest
    services:
      postgres:
        image: postgres:14
    steps:
      - uses: actions/checkout@v3
      - name: Run backward compatibility tests
        run: npm run test:backward-compat

  forward-compatibility:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
      - name: Run forward compatibility tests
        run: npm run test:forward-compat

  versioning-tests:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
      - name: Test versioning strategies
        run: npm run test:versioning

  deprecation-tests:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
      - name: Test deprecation handling
        run: npm run test:deprecation
```

**Complete Compatibility Test Suite**:

```javascript
// compatibility/complete-suite.js
const { BreakingChangeDetector } = require('./breaking-change-detector');
const { BackwardCompatibilityTests } = require('./backward-compatibility');
const { ForwardCompatibilityTests } = require('./forward-compatibility');
const { VersioningTests } = require('./versioning-tests');
const { DeprecationTests } = require('./deprecation-tests');

class CompatibilityTestSuite {
    constructor(options = {}) {
        this.options = {
            oldSpecPath: options.oldSpecPath || './openapi/previous.yaml',
            newSpecPath: options.newSpecPath || './openapi/current.yaml',
            baseUrl: options.baseUrl || 'https://api.example.com',
            ...options
        };
    }

    async run() {
        console.log('🔄 Running Complete Compatibility Test Suite');
        console.log('=============================================');

        const results = {
            breakingChanges: await this.detectBreakingChanges(),
            backwardCompat: await this.runBackwardCompatTests(),
            forwardCompat: await this.runForwardCompatTests(),
            versioning: await this.runVersioningTests(),
            deprecation: await this.runDeprecationTests(),
            summary: {}
        };

        results.summary = this.generateSummary(results);

        return results;
    }

    async detectBreakingChanges() {
        console.log('\n🔍 Detecting Breaking Changes...');
        const detector = new BreakingChangeDetector(
            this.options.oldSpecPath,
            this.options.newSpecPath
        );

        const result = await detector.detectBreakingChanges();

        if (result.breakingChanges.length > 0) {
            console.log(`❌ Found ${result.breakingChanges.length} breaking changes`);
            console.table(result.breakingChanges.slice(0, 5));
        } else {
            console.log('✅ No breaking changes detected');
        }

        return result;
    }

    async runBackwardCompatTests() {
        console.log('\n🔄 Running Backward Compatibility Tests...');
        const tests = new BackwardCompatibilityTests(this.options);
        return await tests.run();
    }

    async runForwardCompatTests() {
        console.log('\n🔮 Running Forward Compatibility Tests...');
        const tests = new ForwardCompatibilityTests(this.options);
        return await tests.run();
    }

    async runVersioningTests() {
        console.log('\n📦 Running Versioning Strategy Tests...');
        const tests = new VersioningTests(this.options);
        return await tests.run();
    }

    async runDeprecationTests() {
        console.log('\n⚠️ Running Deprecation Tests...');
        const tests = new DeprecationTests(this.options);
        return await tests.run();
    }

    generateSummary(results) {
        const passed = results.backwardCompat.passed &&
                      results.forwardCompat.passed &&
                      results.versioning.passed &&
                      results.deprecation.passed;

        return {
            passed,
            breakingChanges: results.breakingChanges.breakingChanges.length,
            backwardCompat: results.backwardCompat.passed,
            forwardCompat: results.forwardCompat.passed,
            versioning: results.versioning.passed,
            deprecation: results.deprecation.passed,
            recommendedVersion: this.recommendVersion(results),
            blocking: results.breakingChanges.breakingChanges.length > 0
        };
    }

    recommendVersion(results) {
        if (results.breakingChanges.breakingChanges.length > 0) {
            return 'major';
        }
        if (results.backwardCompat.newFeatures > 0) {
            return 'minor';
        }
        if (results.backwardCompat.bugFixes > 0) {
            return 'patch';
        }
        return 'none';
    }
}

// Run if called directly
if (require.main === module) {
    const suite = new CompatibilityTestSuite();
    suite.run().then(results => {
        console.log('\n📊 Compatibility Test Summary');
        console.log('==============================');
        console.log(JSON.stringify(results.summary, null, 2));

        if (!results.summary.passed) {
            process.exit(1);
        }
    });
}
```

**Compatibility Testing Checklist**:

✅ **Breaking Change Detection**
- [ ] Compare OpenAPI specs
- [ ] Check for removed endpoints/fields
- [ ] Validate type changes
- [ ] Verify enum modifications

✅ **Backward Compatibility**
- [ ] Old clients work with new API
- [ ] Old requests still valid
- [ ] Old responses still parseable
- [ ] Error handling unchanged

✅ **Forward Compatibility**
- [ ] New clients work with old API
- [ ] Unknown fields ignored
- [ ] Missing fields handled
- [ ] Enum extensibility

✅ **Versioning Strategy**
- [ ] Correct routing by version
- [ ] Invalid versions handled
- [ ] Version precedence clear
- [ ] Default version defined

✅ **SemVer Compliance**
- [ ] Major = breaking changes
- [ ] Minor = new features
- [ ] Patch = bug fixes
- [ ] Version numbers accurate

✅ **Deprecation**
- [ ] Deprecation headers present
- [ ] Sunset dates provided
- [ ] Migration paths documented
- [ ] Clear error messages

**Compatibility Testing Anti-Patterns**:

| Anti-Pattern | Why It's Bad | Solution |
|--------------|--------------|----------|
| **No automated checks** | Breaking changes slip through | Automate spec comparison |
| **Only testing latest** | Old clients forgotten | Test multiple client versions |
| **Ignoring deprecation** | Clients surprised by removal | Test deprecation headers |
| **Inconsistent versioning** | Confused clients | Enforce versioning policy |
| **No forward compatibility** | Can't roll back | Design for forward compatibility |

**Key Insight**: Compatibility testing is an investment in your API's future. Every hour spent on compatibility testing saves days of dealing with broken client integrations later.

Discoverability is about how easily developers can find endpoints, understand what they do, and learn how to use them without extensive documentation reading.

**Discoverability Heuristics**:

| Heuristic | Good Example | Bad Example |
|-----------|--------------|-------------|
| **Intuitive URLs** | `/users/123/orders` | `/getOrdersByUserId?uid=123` |
| **RESTful Conventions** | `POST /orders` to create | `/createNewOrder` |
| **Consistent Patterns** | All list endpoints support pagination | Some paginated, some not |
| **Self-descriptive** | `GET /products` returns array | `GET /products` returns weird structure |
| **HATEOAS Links** | Response includes related links | No navigation clues |

**Testing URL Intuitiveness**:

```javascript
// usability/discoverability-test.js
describe('API Discoverability Tests', () => {
    // These tests simulate a developer trying to guess endpoints

    const baseURL = 'https://api.example.com';

    it('developers can guess collection endpoints', async () => {
        // A developer might guess these common patterns
        const guessedEndpoints = [
            '/users',
