            endpoints.map(e => 
                request('https://api.example.com')
                    [e.method](e.path)
                    .send(e.data || {})
            )
        );

        responses.forEach(response => {
            if (response.status < 400) {
                // Either always wrapped or never wrapped
                const hasData = response.body.data !== undefined;
                const hasItems = response.body.items !== undefined;

                // Should be consistent across endpoints
                if (responses[0].body.data !== undefined) {
                    expect(hasData || hasItems).toBe(true);
                }
            }
        });
    });

    it('uses consistent ID field name', async () => {
        const responses = await Promise.all(
            endpoints.map(e => 
                request('https://api.example.com')
                    [e.method](e.path)
                    .send(e.data || {})
            )
        );

        responses.forEach(response => {
            if (response.status < 400 && response.body.id === undefined) {
                // If not 'id', should be consistent across resources
                const idFields = ['userId', 'productId', 'orderId'];
                const hasId = idFields.some(f => response.body[f] !== undefined);

                if (hasId) {
                    // Record what field is used for consistency check
                    const usedField = idFields.find(f => response.body[f] !== undefined);
                    console.log(`Resource uses ${usedField} instead of id`);
                }
            }
        });
    });
});
