describe('Response Intuitiveness Tests', () => {
    it('collection responses are clearly collections', async () => {
        const response = await request('https://api.example.com')
            .get('/users');

        const body = response.body;

        // Either returns array directly or has data wrapper
        const isArray = Array.isArray(body);
        const hasDataArray = body.data && Array.isArray(body.data);
        const hasItems = body.items && Array.isArray(body.items);

