// scalability-test.js
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const errorRate = new Rate('errors');

export const options = {
    stages: [
        // Test with 1x load
        { duration: '5m', target: 100 },

        // Scale up to 2x load
        { duration: '5m', target: 200 },

        // Scale up to 4x load
        { duration: '5m', target: 400 },

        // Scale up to 8x load
        { duration: '5m', target: 800 },

        // Scale up to 16x load
        { duration: '5m', target: 1600 },
    ],
    thresholds: {
        http_req_failed: ['rate<0.01'],
    },
};

export default function() {
    const response = http.get('https://api.example.com/users/123');

    check(response, {
        'status is 200': (r) => r.status === 200,
    });

    errorRate.add(response.status >= 400);

    sleep(1);
}

// Post-test analysis to determine scalability factor
export function handleSummary(data) {
    const points = [
        { users: 100, rps: data.metrics.http_reqs.values.rate },
        { users: 200, rps: data.metrics_200?.http_reqs?.values?.rate },
        { users: 400, rps: data.metrics_400?.http_reqs?.values?.rate },
        { users: 800, rps: data.metrics_800?.http_reqs?.values?.rate },
        { users: 1600, rps: data.metrics_1600?.http_reqs?.values?.rate },
    ].filter(p => p.rps);

    // Calculate scalability factor
    const scalability = [];
    for (let i = 1; i < points.length; i++) {
        const userIncrease = points[i].users / points[i-1].users;
        const rpsIncrease = points[i].rps / points[i-1].rps;
        const factor = rpsIncrease / userIncrease;

        scalability.push({
            stage: `${points[i-1].users} → ${points[i].users}`,
            factor: factor.toFixed(2),
            scaling: factor > 0.9 ? 'linear' : factor > 0.7 ? 'good' : factor > 0.5 ? 'fair' : 'poor',
        });
    }

    return {
        'scalability.json': JSON.stringify({
            points,
            scalability,
            averageFactor: scalability.reduce((sum, s) => sum + parseFloat(s.factor), 0) / scalability.length,
        }),
    };
}
