**Performance Baseline Comparison**:

```javascript
// compare-performance.js
const fs = require('fs');

class PerformanceComparator {
    constructor(baselinePath, currentPath) {
        this.baseline = JSON.parse(fs.readFileSync(baselinePath));
        this.current = JSON.parse(fs.readFileSync(currentPath));
    }

    compare() {
        const comparison = {
            timestamp: new Date().toISOString(),
            passed: true,
            metrics: {},
            regressions: [],
            improvements: [],
        };

        const metrics = ['http_req_duration', 'http_reqs', 'http_req_failed'];

        metrics.forEach(metric => {
            const baselineValue = this.baseline.metrics[metric]?.values;
            const currentValue = this.current.metrics[metric]?.values;

            if (!baselineValue || !currentValue) return;

            const change = this.calculateChange(baselineValue, currentValue);

            comparison.metrics[metric] = {
                baseline: baselineValue,
                current: currentValue,
                change: change.percent,
                status: change.status,
            };

            if (change.status === 'regression') {
                comparison.regressions.push({
                    metric,
                    baseline: baselineValue,
                    current: currentValue,
                    change: change.percent,
                });
                comparison.passed = false;
            } else if (change.status === 'improvement') {
                comparison.improvements.push({
                    metric,
                    baseline: baselineValue,
                    current: currentValue,
                    change: change.percent,
                });
            }
        });

        return comparison;
    }

    calculateChange(baseline, current) {
        // For response time, lower is better
        if (baseline.p95 && current.p95) {
            const change = ((current.p95 - baseline.p95) / baseline.p95) * 100;
            return {
                percent: change.toFixed(1),
                status: change > 10 ? 'regression' : change < -5 ? 'improvement' : 'acceptable',
            };
        }

        // For throughput, higher is better
        if (baseline.rate && current.rate) {
            const change = ((current.rate - baseline.rate) / baseline.rate) * 100;
            return {
                percent: change.toFixed(1),
                status: change < -10 ? 'regression' : change > 5 ? 'improvement' : 'acceptable',
            };
        }

        // For error rate, lower is better
        if (baseline.rate !== undefined && current.rate !== undefined) {
            const change = ((current.rate - baseline.rate) / (baseline.rate || 0.001)) * 100;
            return {
                percent: change.toFixed(1),
                status: change > 20 ? 'regression' : change < -10 ? 'improvement' : 'acceptable',
            };
        }

        return { percent: 0, status: 'unknown' };
    }

    generateMarkdownReport() {
        const comparison = this.compare();

        let report = '# Performance Test Results\n\n';

        if (comparison.passed) {
            report += '✅ **All performance tests passed**\n\n';
        } else {
            report += '❌ **Performance regressions detected**\n\n';
        }

        report += '## Summary\n\n';
        report += '| Metric | Baseline | Current | Change | Status |\n';
        report += '|--------|----------|---------|--------|--------|\n';

        Object.entries(comparison.metrics).forEach(([metric, data]) => {
            const baseline = data.baseline.p95 ? `${data.baseline.p95.toFixed(2)}ms` : 
                            data.baseline.rate ? `${data.baseline.rate.toFixed(2)}/s` : 
                            `${(data.baseline.rate * 100).toFixed(2)}%`;

            const current = data.current.p95 ? `${data.current.p95.toFixed(2)}ms` :
                           data.current.rate ? `${data.current.rate.toFixed(2)}/s` :
                           `${(data.current.rate * 100).toFixed(2)}%`;

            const statusIcon = data.status === 'regression' ? '🔴' :
                              data.status === 'improvement' ? '✅' : '⚪';

            report += `| ${metric} | ${baseline} | ${current} | ${data.change}% | ${statusIcon} |\n`;
        });

        if (comparison.regressions.length > 0) {
            report += '\n## 🔴 Regressions\n\n';
            comparison.regressions.forEach(r => {
                report += `- **${r.metric}**: ${r.change}% worse\n`;
            });
        }

        if (comparison.improvements.length > 0) {
            report += '\n## ✅ Improvements\n\n';
            comparison.improvements.forEach(i => {
                report += `- **${i.metric}**: ${i.change}% better\n`;
            });
        }

        return report;
    }
}

// Run if called directly
if (require.main === module) {
    const args = process.argv.slice(2);
    const baselinePath = args.find(a => a.startsWith('--baseline='))?.split('=')[1];
    const currentPath = args.find(a => a.startsWith('--current='))?.split('=')[1];

    if (!baselinePath || !currentPath) {
        console.error('Usage: node compare-performance.js --baseline=baseline.json --current=current.json');
        process.exit(1);
    }

    const comparator = new PerformanceComparator(baselinePath, currentPath);
    const report = comparator.generateMarkdownReport();

    fs.writeFileSync('report.md', report);
    console.log(report);

    // Exit with code based on result
    process.exit(comparator.compare().passed ? 0 : 1);
}
