                thresholds: this.config.thresholds.spike,
            });

            this.results.spike = {
                passed: true,
                duration: Date.now() - start,
                metrics: this.parseK6Output(result),
                recoveryTime: this.calculateRecoveryTime(result),
            };
            console.log('✅ Spike tests passed');
        } catch (error) {
            this.results.spike = {
                passed: false,
                error: error.message,
            };
            console.error('❌ Spike tests failed');
        }
    }

    async runSoakTests() {
        console.log('\n💧 Running Soak Tests (24 hours)...');
        const start = Date.now();

        // Soak tests run separately due to duration
        console.log('Starting background soak test...');
        this.spawnSoakTest();
    }

    async runK6Test(script, options) {
        return new Promise((resolve, reject) => {
            const cmd = `k6 run ${path.join(__dirname, 'scripts', script)} \
                --vus ${options.vus || ''} \
                --duration ${options.duration || ''} \
                --stage ${options.stages ? JSON.stringify(options.stages) : ''} \
                --out json=results.json`;

            exec(cmd, (error, stdout, stderr) => {
                if (error) {
                    reject(error);
                } else {
                    resolve(JSON.parse(fs.readFileSync('results.json')));
                }
            });
        });
    }

    generateReport() {
        const duration = (Date.now() - this.startTime) / 1000 / 60; // minutes

        return {
            timestamp: new Date().toISOString(),
            duration: `${duration.toFixed(1)} minutes`,
            environment: this.config.environment,
            results: this.results,
            summary: {
                passed: Object.values(this.results).every(r => r.passed !== false),
                totalTests: Object.keys(this.results).length,
                passedTests: Object.values(this.results).filter(r => r.passed).length,
                failedTests: Object.values(this.results).filter(r => !r.passed).length,
            },
            recommendations: this.generateRecommendations(),
        };
    }

    generateRecommendations() {
        const recs = [];

        if (!this.results.load?.passed) {
            recs.push('🔴 Load test failed - investigate performance under expected load');
        }

        if (this.results.stress?.breakingPoint) {
            recs.push(`⚠️ System breaks at ${this.results.stress.breakingPoint.users} users - plan capacity`);
        }

        if (this.results.spike?.recoveryTime > 60000) {
            recs.push('⏰ Spike recovery time > 1 minute - optimize auto-scaling');
        }

        return recs;
    }
}

// Run if called directly
if (require.main === module) {
    const suite = new PerformanceTestSuite({
        environment: process.env.TEST_ENV || 'staging',
        includeLongRunning: process.env.INCLUDE_LONG === 'true',
        thresholds: {
            load: {
                http_req_duration: ['p(95)<500', 'p(99)<1000'],
                http_req_failed: ['rate<0.01'],
            },
            stress: {
                http_req_duration: ['p(95)<2000'],
                http_req_failed: ['rate<0.10'],
            },
            spike: {
                http_req_failed: ['rate<0.05'],
            },
        },
    });

    suite.run().then(report => {
        console.log('\n📊 Performance Test Report');
        console.log('==========================');
        console.log(JSON.stringify(report, null, 2));

        if (!report.summary.passed) {
            process.exit(1);
        }
    });
}
```

**Performance Testing Checklist**:

✅ **Baseline**
- [ ] Single user response time
- [ ] Cold start performance
- [ ] Cached vs uncached

✅ **Load Testing**
- [ ] Expected peak load
- [ ] Response time SLAs
- [ ] Error rate under load

✅ **Stress Testing**
- [ ] Breaking point found
- [ ] Failure mode understood
- [ ] Graceful degradation

✅ **Spike Testing**
- [ ] Handles sudden surges
- [ ] Auto-scaling triggers
- [ ] Recovery time

✅ **Soak Testing**
- [ ] No memory leaks
- [ ] No performance degradation
- [ ] Connection pool stable

✅ **Scalability**
- [ ] Scales linearly
- [ ] Bottlenecks identified
- [ ] Capacity planned

✅ **CI/CD Integration**
