// chaos/kubernetes-client.js
const { KubeConfig, CoreV1Api } = require('@kubernetes/client-node');
const axios = require('axios');

class KubernetesChaos {
  constructor() {
    const kc = new KubeConfig();
    kc.loadFromDefault();
    this.k8sApi = kc.makeApiClient(CoreV1Api);
  }

  async deletePod(namespace, labelSelector) {
    const pods = await this.k8sApi.listNamespacedPod(
      namespace,
      undefined,
      undefined,
      undefined,
      undefined,
      labelSelector
    );

    if (pods.body.items.length === 0) return;

    const pod = pods.body.items[0];
    console.log(`Deleting pod: ${pod.metadata.name}`);

    await this.k8sApi.deleteNamespacedPod(pod.metadata.name, namespace);

    // Monitor recovery
    await this.monitorRecovery(namespace, labelSelector);
  }

  async monitorRecovery(namespace, labelSelector, timeout = 60000) {
    const start = Date.now();

    while (Date.now() - start < timeout) {
      const pods = await this.k8sApi.listNamespacedPod(
        namespace,
        undefined,
        undefined,
        undefined,
        undefined,
        labelSelector
      );

      const ready = pods.body.items.every(pod =>
        pod.status.conditions?.some(c => c.type === 'Ready' && c.status === 'True')
      );

      if (ready) {
        console.log(`✅ Pods recovered in ${Date.now() - start}ms`);
        return;
      }

      await new Promise(r => setTimeout(r, 1000));
    }

    throw new Error('Timeout waiting for pod recovery');
  }

  async testDuringChaos() {
    // Start chaos
    const chaosPromise = this.deletePod('production', 'app=api-service');

    // Test API during chaos
    const results = [];
    for (let i = 0; i < 20; i++) {
      try {
        const start = Date.now();
        await axios.get('http://api.example.com/health');
        results.push({
          success: true,
          duration: Date.now() - start
        });
      } catch (error) {
        results.push({
          success: false,
          error: error.message
        });
      }
      await new Promise(r => setTimeout(r, 1000));
    }

    await chaosPromise;

    // Analyze
    const successRate = results.filter(r => r.success).length / results.length;
    console.log(`Success rate during chaos: ${successRate * 100}%`);

    return results;
  }
}
