**Retry Logic Testing:**

```javascript
// resilience/retry-test.js
class RetryTester {
  constructor(apiUrl) {
    this.apiUrl = apiUrl;
    this.attempts = [];
  }

  async testRetryBehavior(failureCount) {
    this.attempts = [];

    // Mock endpoint that fails N times then succeeds
    const start = Date.now();

    try {
      const response = await axios.get(`${this.apiUrl}/api/unreliable`, {
        params: { failCount: failureCount },
        timeout: 5000
      });

      return {
        success: true,
        attempts: this.attempts,
        duration: Date.now() - start,
        response: response.data
      };
    } catch (error) {
      return {
        success: false,
        attempts: this.attempts,
        duration: Date.now() - start,
        error: error.message
      };
    }
  }

  async runTests() {
    const results = [];

    // Test different failure scenarios
    for (let fails = 0; fails <= 5; fails++) {
      console.log(`Testing with ${fails} failures before success`);
      const result = await this.testRetryBehavior(fails);
      results.push({ fails, ...result });

      // Wait between tests
      await new Promise(r => setTimeout(r, 1000));
    }

    return this.analyze(results);
  }

  analyze(results) {
    const analysis = {
      maxRetries: 0,
      backoffPattern: null,
      results
    };

    // Find where it stops retrying
    for (const r of results) {
      if (r.success && r.fails > analysis.maxRetries) {
        analysis.maxRetries = r.fails;
      }
    }

    // Check backoff pattern
    if (results[1]?.attempts.length > 1) {
      const intervals = [];
      for (let i = 1; i < results[1].attempts.length; i++) {
        intervals.push(
          results[1].attempts[i] - results[1].attempts[i - 1]
        );
      }

      // Check if exponential
      const isExponential = intervals.every((val, i) => 
        i === 0 || val > intervals[i - 1]
      );

      analysis.backoffPattern = isExponential ? 'exponential' : 'fixed';
    }

    return analysis;
  }
}

// Mock server for testing
app.get('/api/unreliable', (req, res) => {
  const failCount = parseInt(req.query.failCount) || 0;
  const attempt = (req.headers['x-attempt'] || 0);

  // Track attempt
  res.set('X-Attempt', attempt);

  if (attempt < failCount) {
    // Fail with 503
    res.status(503).json({ 
      error: 'Temporarily unavailable',
      attempt,
      nextAttempt: attempt + 1
    });
  } else {
    res.json({ 
      success: true,
      attempt,
      message: 'Finally succeeded!'
    });
  }
});
