    }

    // Find when circuit opened
    const firstOpen = results.findIndex(r => r.open);
    expect(firstOpen).toBeGreaterThan(0);
    expect(firstOpen).toBeLessThan(10); // Should open after 5 failures

    // All subsequent should be open
    const afterOpen = results.slice(firstOpen);
    expect(afterOpen.every(r => r.open)).toBe(true);
  });

  it('should reset circuit after recovery period', async () => {
    // Open the circuit
    for (let i = 0; i < 10; i++) {
      try {
        await axios.get('http://localhost:3000/api/circuit');
      } catch (e) {}
    }

    // Wait for reset period
    await new Promise(r => setTimeout(r, 30000)); // 30s

    // Next request should try again
    try {
      const response = await axios.get('http://localhost:3000/api/circuit');
      expect(response.status).toBe(200);
    } catch (error) {
      // If still failing, check if it's trying (not fast-fail)
      expect(error.response?.headers['x-circuit-open']).toBe('false');
    }
  });

  it('should have half-open state for testing', async () => {
    // This requires monitoring circuit state
    // Verify that after reset period, it allows limited requests
    // before fully closing or reopening
  });
});

// Circuit breaker implementation for testing
class CircuitBreaker {
  constructor(options = {}) {
    this.failureThreshold = options.failureThreshold || 5;
    this.resetTimeout = options.resetTimeout || 30000;
    this.failures = 0;
    this.state = 'CLOSED';
    this.nextAttempt = Date.now();
  }

  async call(fn) {
    if (this.state === 'OPEN') {
      if (Date.now() > this.nextAttempt) {
        this.state = 'HALF_OPEN';
      } else {
        throw new Error('Circuit is open');
      }
    }

    try {
      const result = await fn();
      this.onSuccess();
      return result;
    } catch (error) {
      this.onFailure();
      throw error;
    }
  }

  onSuccess() {
    this.failures = 0;
    this.state = 'CLOSED';
  }

  onFailure() {
    this.failures++;
    if (this.failures >= this.failureThreshold) {
      this.state = 'OPEN';
      this.nextAttempt = Date.now() + this.resetTimeout;
    }
  }
}
