```javascript
// chaos/toxiproxy-test.js
const toxiproxy = require('toxiproxy-node-client');

class ToxiproxyChaos {
  constructor() {
    this.toxic = new toxiproxy.Toxiproxy('http://localhost:8474');
  }

  async setupProxy(name, upstream, listen) {
    const proxy = await this.toxic.createProxy({
      name,
      upstream,
      listen
    });
    return proxy;
  }

  async injectLatency(proxy, latency = 1000, jitter = 100) {
    await proxy.addToxic({
      type: 'latency',
      attributes: {
        latency,
        jitter
      }
    });
    console.log(`Latency injected: ${latency}ms ±${jitter}ms`);
  }

  async injectPacketLoss(proxy, rate = 0.1) {
    await proxy.addToxic({
      type: 'bandwidth',
      attributes: {
        rate: 1024 // Limit bandwidth
      }
    });

    await proxy.addToxic({
      type: 'slow_close',
      attributes: {
        delay: 1000
      }
    });

    console.log(`Packet loss simulated: ${rate * 100}%`);
  }

  async injectTimeout(proxy) {
    await proxy.addToxic({
      type: 'timeout',
      attributes: {
        timeout: 0 // Immediate timeout
      }
    });
    console.log('Timeout injected');
  }

  async reset(proxy) {
    await proxy.removeToxics();
    console.log('Proxy reset');
  }

  async runExperiment() {
    const proxy = await this.setupProxy(
      'api-proxy',
      'localhost:3000',
      'localhost:3001'
    );

    try {
      // Baseline
      console.log('Testing baseline...');
      await this.testEndpoint('http://localhost:3001/api/health');

      // Latency
      await this.injectLatency(proxy, 2000);
      console.log('Testing with latency...');
      await this.testEndpoint('http://localhost:3001/api/health');

      // Packet loss
      await this.reset(proxy);
      await this.injectPacketLoss(proxy);
      console.log('Testing with packet loss...');
      await this.testEndpoint('http://localhost:3001/api/health');

      // Timeout
      await this.reset(proxy);
      await this.injectTimeout(proxy);
      console.log('Testing with timeout...');
      await this.testEndpoint('http://localhost:3001/api/health');

    } finally {
      await this.reset(proxy);
      await proxy.delete();
    }
  }

  async testEndpoint(url) {
    const results = [];
    for (let i = 0; i < 10; i++) {
      const start = Date.now();
      try {
        await axios.get(url, { timeout: 5000 });
        results.push({
          success: true,
          duration: Date.now() - start
        });
      } catch (error) {
        results.push({
          success: false,
          duration: Date.now() - start,
          error: error.message
        });
      }
    }

    const successRate = results.filter(r => r.success).length / results.length;
    const avgDuration = results.filter(r => r.success)
      .reduce((acc, r) => acc + r.duration, 0) / results.length;

    console.log(`Success rate: ${successRate * 100}%, Avg duration: ${avgDuration}ms`);
    return results;
  }
}
