**Active Reconnaissance Script:**

```javascript
// recon/active-recon.js
const axios = require('axios');

class ActiveRecon {
  constructor(baseURL) {
    this.baseURL = baseURL;
    this.findings = [];
    this.session = axios.create({
      baseURL,
      timeout: 5000,
      validateStatus: () => true // Accept any status
    });
  }

  async run() {
    console.log(`Starting active recon for ${this.baseURL}`);

    await this.enumerateEndpoints();
    await this.enumerateMethods();
    await this.analyzeAuthentication();
    await this.analyzeErrorHandling();
    await this.fingerprintTechnology();

    return this.findings;
  }

  async enumerateEndpoints() {
    const commonPaths = [
      '/', '/api', '/v1', '/v2', '/v3',
      '/docs', '/swagger', '/api-docs', '/openapi.json',
      '/graphql', '/graphiql', '/playground',
      '/health', '/healthcheck', '/ping', '/status',
      '/metrics', '/stats', '/debug', '/test',
      '/admin', '/administrator', '/console',
      '/.env', '/.git', '/.aws/credentials',
      '/users', '/user', '/profile', '/account',
      '/login', '/signin', '/auth',
      '/logout', '/signout',
      '/register', '/signup',
      '/password-reset', '/forgot-password',
      '/uploads', '/files', '/download',
      '/webhook', '/webhooks', '/callback'
    ];

    for (const path of commonPaths) {
      try {
        const response = await this.session.get(path);

        if (response.status !== 404) {
          this.findings.push({
            type: 'endpoint',
            path,
            status: response.status,
            contentLength: response.headers['content-length']
          });

          console.log(`Found: ${path} (${response.status})`);
        }
      } catch (error) {
        // Ignore connection errors
      }
    }
  }

  async enumerateMethods() {
    const methods = ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'HEAD', 'OPTIONS'];
    const discoveredEndpoints = this.findings
      .filter(f => f.type === 'endpoint')
      .map(f => f.path);

    for (const endpoint of discoveredEndpoints.slice(0, 10)) { // Limit for demo
      for (const method of methods) {
        try {
          const response = await this.session({
            method,
            url: endpoint,
            data: method === 'POST' || method === 'PUT' ? { test: true } : undefined
          });

          if (response.status !== 404 && response.status !== 405) {
            this.findings.push({
              type: 'method',
              endpoint,
              method,
              status: response.status,
              allowHeader: response.headers['allow']
            });

            console.log(`Method ${method} on ${endpoint} returned ${response.status}`);
          }
        } catch (error) {
          // Ignore
        }
      }
    }
  }

  async analyzeAuthentication() {
    // Test without auth
    const response = await this.session.get('/api/users');

    this.findings.push({
      type: 'auth',
      test: 'No authentication',
      status: response.status,
      requiresAuth: response.status === 401 || response.status === 403,
      authHeader: response.headers['www-authenticate']
    });

    // Test with invalid auth
    const invalidResponse = await this.session.get('/api/users', {
      headers: { 'Authorization': 'Bearer invalid-token' }
    });

    this.findings.push({
      type: 'auth',
      test: 'Invalid token',
      status: invalidResponse.status,
      message: invalidResponse.data
    });
  }

  async analyzeErrorHandling() {
    const testCases = [
      { path: '/api/users/999999999', description: 'Non-existent resource' },
      { path: '/api/users/abc', description: 'Invalid ID format' },
      { path: '/api/users?sort=invalid', description: 'Invalid parameter' },
      { path: '/api/users', method: 'POST', data: {}, description: 'Empty POST' },
      { path: '/api/users', method: 'POST', data: { invalid: true }, description: 'Invalid fields' }
    ];

    for (const test of testCases) {
      try {
        const response = await this.session({
          method: test.method || 'GET',
          url: test.path,
          data: test.data
        });

        if (response.status >= 500) {
          this.findings.push({
            type: 'error',
            severity: 'high',
            test: test.description,
            status: response.status,
            data: response.data,
            issue: 'Server error - possible information disclosure'
          });
        }

        // Check for stack traces
        const responseStr = JSON.stringify(response.data);
        if (responseStr.includes('at ') || responseStr.includes('Error:')) {
          this.findings.push({
            type: 'error',
            severity: 'medium',
            test: test.description,
            issue: 'Stack trace exposed in error response',
            data: response.data
          });
        }
      } catch (error) {
        // Ignore
      }
    }
  }

  async fingerprintTechnology() {
    const response = await this.session.get('/');
    const headers = response.headers;

    const tech = {
      server: headers['server'],
      poweredBy: headers['x-powered-by'],
      aspNet: headers['x-aspnet-version'],
      framework: headers['x-frame-options'] ? 'Has security headers' : null
    };

    this.findings.push({
      type: 'fingerprint',
      ...tech
    });

    // Check for version disclosure
    if (tech.server || tech.poweredBy) {
      this.findings.push({
        type: 'fingerprint',
        severity: 'low',
        issue: 'Server version disclosed',
        details: tech
      });
    }
  }
}

