  console.log('\n=== RECONNAISSANCE SUMMARY ===');

  const endpoints = findings.filter(f => f.type === 'endpoint');
  console.log(`\nDiscovered ${endpoints.length} endpoints:`);
  endpoints.forEach(e => console.log(`  ${e.path} (${e.status})`));

  const authIssues = findings.filter(f => f.type === 'auth');
  console.log(`\nAuth findings:`, authIssues);

  const errors = findings.filter(f => f.type === 'error');
  console.log(`\nError handling issues:`, errors);
});
