**OWASP ZAP API Scan Script:**

```javascript
// scanning/zap-scan.js
const ZapClient = require('zap-client');

class ZAPScanner {
  constructor(zapUrl, apiKey) {
    this.zap = new ZapClient({
      proxy: zapUrl,
      apiKey: apiKey
    });
    this.findings = [];
  }

  async scan(target) {
    console.log(`Starting ZAP scan for ${target}`);

    // Spider the target
    console.log('Spidering...');
    const spiderId = await this.zap.spider.scan(target);
    await this.waitForCompletion('spider', spiderId);

    // Active scan
    console.log('Starting active scan...');
    const scanId = await this.zap.ascan.scan(target);
    await this.waitForCompletion('ascan', scanId);

    // Get alerts
    const alerts = await this.zap.core.alerts({ baseurl: target });

    // Process alerts
    for (const alert of alerts) {
      this.findings.push({
        name: alert.name,
        risk: alert.risk,
        confidence: alert.confidence,
        description: alert.description,
        url: alert.url,
        parameter: alert.param,
        evidence: alert.evidence,
        solution: alert.solution
      });
    }

    return this.analyzeFindings();
  }

  async waitForCompletion(type, id) {
    let progress = 0;
    while (progress < 100) {
      await new Promise(r => setTimeout(r, 2000));
      if (type === 'spider') {
        progress = await this.zap.spider.status(id);
      } else {
        progress = await this.zap.ascan.status(id);
      }
      console.log(`${type} progress: ${progress}%`);
    }
  }

  analyzeFindings() {
    const byRisk = {
      high: this.findings.filter(f => f.risk === 'High'),
      medium: this.findings.filter(f => f.risk === 'Medium'),
      low: this.findings.filter(f => f.risk === 'Low'),
      info: this.findings.filter(f => f.risk === 'Informational')
    };

    return {
      total: this.findings.length,
      byRisk,
      findings: this.findings
    };
  }
}

// Usage
const scanner = new ZAPScanner('http://localhost:8080', 'api-key');
scanner.scan('https://api.example.com').then(results => {
  console.log(`Found ${results.total} alerts`);
  console.log(`High risk: ${results.byRisk.high.length}`);
  console.log(`Medium risk: ${results.byRisk.medium.length}`);
});
```

