**Manual Vulnerability Analysis Script:**

```javascript
// scanning/manual-analysis.js
class ManualVulnerabilityAnalysis {
  constructor(baseURL, token) {
    this.baseURL = baseURL;
    this.token = token;
    this.client = axios.create({
      baseURL,
      headers: { 'Authorization': `Bearer ${token}` },
      validateStatus: () => true
    });
    this.findings = [];
  }

  async runAllChecks() {
    console.log('Starting manual vulnerability analysis...');

    await this.checkAuthentication();
    await this.checkAuthorization();
    await this.checkInjection();
    await this.checkRateLimiting();
    await this.checkBusinessLogic();
    await this.checkConfiguration();

    return this.findings;
  }

  async checkAuthentication() {
    console.log('\n--- Authentication Checks ---');

    // Test password reset
    const resetResponse = await this.client.post('/api/password-reset/request', {
      email: 'user@example.com'
    });

    if (resetResponse.status === 200) {
      // Check if reset token is returned (should not be)
      if (resetResponse.data.token) {
        this.findings.push({
          type: 'authentication',
          severity: 'high',
          issue: 'Password reset token returned in response',
          evidence: resetResponse.data
        });
      }
    }

    // Test token expiration
    const oldToken = await this.getOldToken(); // Get expired token
    if (oldToken) {
      const response = await this.client.get('/api/user', {
        headers: { 'Authorization': `Bearer ${oldToken}` }
      });

      if (response.status === 200) {
        this.findings.push({
          type: 'authentication',
          severity: 'critical',
          issue: 'Expired token still accepted',
          evidence: `Token: ${oldToken}`
        });
      }
    }

    // Test concurrent sessions
    const sessions = [];
    for (let i = 0; i < 5; i++) {
      const login = await this.client.post('/api/login', {
        email: 'user@example.com',
        password: 'password'
      });
      if (login.data.token) {
        sessions.push(login.data.token);
      }
    }

    // Try all tokens
    const workingSessions = [];
    for (const token of sessions) {
      const response = await this.client.get('/api/user', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (response.status === 200) {
        workingSessions.push(token);
      }
    }

    if (workingSessions.length > 3) {
      this.findings.push({
        type: 'authentication',
        severity: 'medium',
        issue: 'No concurrent session limit',
        evidence: `${workingSessions.length} active sessions`
      });
    }
  }

  async checkAuthorization() {
    console.log('\n--- Authorization Checks ---');

    // Test horizontal privilege escalation
    const userAResponse = await this.client.get('/api/users/me');
    const myId = userAResponse.data.id;

    // Try to access user B's data
    const otherId = myId + 1; // Guess
    const response = await this.client.get(`/api/users/${otherId}`);

    if (response.status === 200) {
      this.findings.push({
        type: 'authorization',
        severity: 'critical',
        issue: 'Horizontal privilege escalation (BOLA)',
        evidence: `Accessed user ${otherId} data: ${JSON.stringify(response.data)}`
      });
    }

    // Test vertical privilege escalation
    const adminResponse = await this.client.get('/api/admin/users');
    if (adminResponse.status === 200) {
      this.findings.push({
        type: 'authorization',
        severity: 'critical',
        issue: 'Vertical privilege escalation - admin endpoint accessible',
        evidence: `Admin data: ${JSON.stringify(adminResponse.data)}`
      });
    }

    // Test mass assignment
    const massAssignResponse = await this.client.patch('/api/users/me', {
      role: 'admin',
      isVerified: true,
      balance: 1000000
    });

    if (massAssignResponse.status === 200) {
      const verifyResponse = await this.client.get('/api/users/me');
      if (verifyResponse.data.role === 'admin') {
        this.findings.push({
          type: 'authorization',
          severity: 'critical',
          issue: 'Mass assignment vulnerability - upgraded to admin',
          evidence: verifyResponse.data
        });
      }
    }
  }

  async checkInjection() {
    console.log('\n--- Injection Checks ---');

    const payloads = [
      { type: 'SQL', value: "' OR '1'='1" },
      { type: 'SQL', value: "'; DROP TABLE users --" },
      { type: 'NoSQL', value: '{"$ne": null}' },
      { type: 'NoSQL', value: '{"$where": "return true"}' },
      { type: 'Command', value: '; cat /etc/passwd' },
      { type: 'Command', value: '| dir' },
      { type: 'XSS', value: '<script>alert(1)</script>' },
      { type: 'Path Traversal', value: '../../../etc/passwd' },
      { type: 'LDAP', value: '*)(uid=*' }
    ];

    for (const payload of payloads) {
      // Test in query params
      const queryResponse = await this.client.get(`/api/search?q=${encodeURIComponent(payload.value)}`);

      if (queryResponse.status === 500) {
        this.findings.push({
          type: 'injection',
          severity: 'high',
          issue: `Possible ${payload.type} injection in query parameter`,
          evidence: `Payload: ${payload.value}, Response: ${JSON.stringify(queryResponse.data)}`
        });
      }

      // Test in body
      const bodyResponse = await this.client.post('/api/search', {
        query: payload.value
      });

      if (bodyResponse.status === 500) {
        this.findings.push({
          type: 'injection',
          severity: 'high',
          issue: `Possible ${payload.type} injection in request body`,
          evidence: `Payload: ${payload.value}, Response: ${JSON.stringify(bodyResponse.data)}`
        });
      }

      // Check for command output in response
      const responseStr = JSON.stringify(bodyResponse.data);
      if (responseStr.includes('root:') || responseStr.includes('bin/bash')) {
        this.findings.push({
          type: 'injection',
          severity: 'critical',
          issue: `Command injection successful - system file exposed`,
          evidence: responseStr.substring(0, 200)
        });
      }
    }
  }

  async checkRateLimiting() {
    console.log('\n--- Rate Limiting Checks ---');

    const requests = [];
    const start = Date.now();

    for (let i = 0; i < 100; i++) {
      requests.push(this.client.get('/api/public'));
    }

    const results = await Promise.all(requests);
    const rateLimited = results.filter(r => r.status === 429);
    const duration = Date.now() - start;

    if (rateLimited.length === 0) {
      this.findings.push({
        type: 'rate-limiting',
        severity: 'medium',
        issue: 'No rate limiting detected on public endpoint',
        evidence: `100 requests in ${duration}ms, all successful`
      });
    } else {
      console.log(`Rate limiting working: ${rateLimited.length} requests blocked`);
    }

    // Test auth endpoint rate limiting
    const authRequests = [];
    for (let i = 0; i < 100; i++) {
      authRequests.push(this.client.post('/api/login', {
        email: `user${i}@test.com`,
        password: 'wrong'
      }));
    }

    const authResults = await Promise.all(authRequests);
    const authRateLimited = authResults.filter(r => r.status === 429);

    if (authRateLimited.length === 0) {
      this.findings.push({
        type: 'rate-limiting',
        severity: 'high',
        issue: 'No rate limiting on authentication endpoint - brute force possible',
        evidence: '100 login attempts all processed'
      });
    }
  }

  async checkBusinessLogic() {
    console.log('\n--- Business Logic Checks ---');

    // Test negative quantities
    const negativeOrder = await this.client.post('/api/orders', {
      productId: 123,
      quantity: -5,
      price: 10
    });

    if (negativeOrder.status === 200 && negativeOrder.data.total < 0) {
      this.findings.push({
        type: 'business-logic',
        severity: 'high',
        issue: 'Negative quantities accepted - possible financial abuse',
        evidence: negativeOrder.data
      });
    }

    // Test price manipulation
    const priceManipulation = await this.client.post('/api/orders', {
      productId: 123,
      quantity: 1,
      price: 0.01 // Original price might be $10
    });

    if (priceManipulation.status === 200 && priceManipulation.data.total === 0.01) {
      this.findings.push({
        type: 'business-logic',
        severity: 'critical',
        issue: 'Client-side price accepted - user can set their own price',
        evidence: priceManipulation.data
      });
    }

    // Test quantity limits
    const largeOrder = await this.client.post('/api/orders', {
      productId: 123,
      quantity: 999999,
      price: 10
    });

    if (largeOrder.status === 200) {
      this.findings.push({
        type: 'business-logic',
        severity: 'medium',
        issue: 'No maximum quantity limit - inventory bypass possible',
        evidence: `Ordered 999999 items`
      });
    }

    // Test coupon abuse
    const couponResponses = [];
    for (let i = 0; i < 10; i++) {
      couponResponses.push(await this.client.post('/api/orders', {
        productId: 123,
        quantity: 1,
        coupon: 'SAVE20'
      }));
    }

    // Check if coupon worked multiple times
    const allSuccess = couponResponses.every(r => r.status === 200);
    if (allSuccess) {
      this.findings.push({
        type: 'business-logic',
        severity: 'medium',
        issue: 'Coupon can be used multiple times by same user',
        evidence: 'SAVE20 applied to 10 orders'
      });
    }

    // Test workflow bypass
    // Try to checkout without adding to cart
    const checkoutResponse = await this.client.post('/api/checkout', {
      paymentMethod: 'card'
    });

    if (checkoutResponse.status === 200) {
      this.findings.push({
        type: 'business-logic',
        severity: 'high',
        issue: 'Workflow bypass - checkout possible with empty cart',
        evidence: 'Checkout succeeded with no items'
      });
    }
  }

  async checkConfiguration() {
    console.log('\n--- Configuration Checks ---');

    // Check security headers
    const response = await this.client.get('/');
    const headers = response.headers;

    const requiredHeaders = [
      'strict-transport-security',
      'x-content-type-options',
      'x-frame-options',
      'x-xss-protection'
    ];

    for (const header of requiredHeaders) {
      if (!headers[header]) {
        this.findings.push({
          type: 'configuration',
          severity: 'low',
          issue: `Missing security header: ${header}`,
          evidence: 'Header not present in response'
        });
      }
    }

    // Check CORS
    const corsResponse = await this.client.get('/api/public', {
      headers: { 'Origin': 'https://evil.com' }
    });

    if (corsResponse.headers['access-control-allow-origin'] === '*') {
      this.findings.push({
        type: 'configuration',
        severity: 'medium',
        issue: 'CORS wildcard allowed',
        evidence: 'Access-Control-Allow-Origin: *'
      });
    }

    // Check HTTP methods
    const traceResponse = await this.client.request({
      method: 'TRACE',
      url: '/'
    });

    if (traceResponse.status !== 405) {
      this.findings.push({
        type: 'configuration',
        severity: 'low',
        issue: 'TRACE method enabled',
        evidence: `TRACE returned ${traceResponse.status}`
      });
    }

    // Check for server version disclosure
    if (headers['server'] || headers['x-powered-by']) {
      this.findings.push({
        type: 'configuration',
        severity: 'low',
        issue: 'Server version disclosed',
        evidence: { server: headers['server'], poweredBy: headers['x-powered-by'] }
      });
    }
  }
}

// Usage
const analyzer = new ManualVulnerabilityAnalysis(
  'https://api.example.com',
  'eyJhbGciOiJIUzI1NiIs...'
);

analyzer.runAllChecks().then(findings => {
  console.log('\n=== VULNERABILITY SUMMARY ===');

