  console.log(`High: ${high.length}`);
  console.log(`Medium: ${medium.length}`);
  console.log(`Low: ${low.length}`);

  if (critical.length > 0) {
    console.log('\n=== CRITICAL FINDINGS ===');
    critical.forEach(f => {
      console.log(`\n[${f.type}] ${f.issue}`);
