Privilege escalation is the art of gaining higher permissions than intended. This can be horizontal (accessing other users) or vertical (gaining admin access).

**Privilege Escalation Vectors:**

| Vector | Description | Example |
|--------|-------------|---------|
| **Parameter Manipulation** | Changing role/user IDs | `user_id=123` → `user_id=1` |
| **Token Tampering** | Modifying JWT claims | Changing `role: user` to `role: admin` |
| **Forced Browsing** | Accessing admin URLs | `/admin` instead of `/user` |
| **Method Manipulation** | Using unexpected HTTP methods | `PUT` instead of `GET` |
| **Header Injection** | Adding admin headers | `X-Admin: true` |

**Vertical Privilege Escalation Testing:**

```javascript
// exploitation/privilege-escalation.js
class PrivilegeEscalationTester {
  constructor(baseURL, userToken, adminToken) {
    this.baseURL = baseURL;
    this.userToken = userToken;
    this.adminToken = adminToken;
    this.client = axios.create({
      baseURL,
      validateStatus: () => true
    });
    this.findings = [];
  }

  async runTests() {
    console.log('Testing privilege escalation vectors...');

    await this.testParameterManipulation();
    await this.testTokenTampering();
    await this.testForcedBrowsing();
    await this.testMethodManipulation();
    await this.testHeaderInjection();
    await this.testRoleInference();

    return this.findings;
  }

  async testParameterManipulation() {
    console.log('\n--- Parameter Manipulation ---');

    const adminEndpoints = [
      '/api/admin/users',
      '/api/admin/settings',
      '/api/internal/users',
      '/api/administrator',
      '/api/v2/users?admin=true'
    ];

    for (const endpoint of adminEndpoints) {
      const response = await this.client.get(endpoint, {
        headers: { 'Authorization': `Bearer ${this.userToken}` }
      });

      if (response.status === 200) {
        this.findings.push({
          type: 'privilege-escalation',
          vector: 'forced-browsing',
          severity: 'critical',
          issue: `Admin endpoint accessible to regular user: ${endpoint}`,
          evidence: `Status: ${response.status}`
        });
      }
    }

    // Try adding admin parameters
    const paramTests = [
      '/api/users?admin=true',
      '/api/users?role=admin',
      '/api/users?isAdmin=true',
      '/api/users?userType=admin'
    ];

    for (const test of paramTests) {
      const response = await this.client.get(test, {
        headers: { 'Authorization': `Bearer ${this.userToken}` }
      });

      if (response.status === 200) {
        const data = response.data;
        // Check if response contains admin data
        if (JSON.stringify(data).includes('admin')) {
          this.findings.push({
            type: 'privilege-escalation',
            vector: 'parameter-manipulation',
            severity: 'high',
            issue: `Admin data accessible via parameter: ${test}`,
            evidence: 'Response contains admin-level data'
          });
        }
      }
    }
  }

  async testTokenTampering() {
    console.log('\n--- Token Tampering ---');

    if (!this.userToken || !this.userToken.includes('.')) return;

    // Decode JWT
    const parts = this.userToken.split('.');
    const payload = JSON.parse(Buffer.from(parts[1], 'base64').toString());

    console.log('Original token payload:', payload);

    // Try to escalate role
    const roleFields = ['role', 'userRole', 'type', 'userType', 'isAdmin', 'admin', 'permissions'];

    for (const field of roleFields) {
      const tamperedPayload = { ...payload };

      if (field.startsWith('is')) {
        tamperedPayload[field] = true;
      } else {
        tamperedPayload[field] = 'admin';
      }

      const tamperedToken = this.createTamperedToken(parts[0], tamperedPayload, parts[2]);

      const response = await this.client.get('/api/admin/users', {
        headers: { 'Authorization': `Bearer ${tamperedToken}` }
      });

      if (response.status === 200) {
        this.findings.push({
          type: 'privilege-escalation',
          vector: 'token-tampering',
          severity: 'critical',
          issue: `JWT claim '${field}' accepted without signature verification`,
          evidence: `Modified token granted admin access`
        });
      }
    }

    // Try to remove signature
    const noSigToken = `${parts[0]}.${parts[1]}.`;
    const noSigResponse = await this.client.get('/api/admin/users', {
      headers: { 'Authorization': `Bearer ${noSigToken}` }
    });

    if (noSigResponse.status === 200) {
      this.findings.push({
        type: 'privilege-escalation',
        vector: 'token-tampering',
        severity: 'critical',
        issue: 'JWT accepted without signature',
        evidence: 'Token with missing signature granted access'
      });
    }
  }

  createTamperedToken(header, payload, signature) {
    // This is a simplified version - real JWT requires proper signing
    const newPayload = Buffer.from(JSON.stringify(payload))
      .toString('base64').replace(/=/g, '');

    return `${header}.${newPayload}.${signature}`;
  }

  async testForcedBrowsing() {
    console.log('\n--- Forced Browsing ---');

    // Try common admin paths
    const adminPaths = [
      '/admin',
      '/administrator',
      '/api/admin',
      '/api/internal',
      '/console',
      '/debug',
      '/swagger',
      '/graphql',
      '/metrics',
      '/health',
      '/.git',
      '/.env',
      '/backup',
      '/backups',
      '/logs',
      '/log'
    ];

    for (const path of adminPaths) {
      const response = await this.client.get(path, {
        headers: { 'Authorization': `Bearer ${this.userToken}` }
      });

      if (response.status !== 404) {
        this.findings.push({
          type: 'privilege-escalation',
          vector: 'forced-browsing',
          severity: response.status === 200 ? 'high' : 'info',
          issue: `Admin path accessible: ${path}`,
          evidence: `Status: ${response.status}`
        });
      }
    }
  }

  async testMethodManipulation() {
    console.log('\n--- Method Manipulation ---');

    const methods = ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'HEAD', 'OPTIONS'];
    const adminEndpoints = ['/api/admin/users', '/api/admin/settings', '/api/users'];

    for (const endpoint of adminEndpoints) {
      for (const method of methods) {
        const response = await this.client({
          method,
          url: endpoint,
          headers: { 'Authorization': `Bearer ${this.userToken}` },
          data: method !== 'GET' ? { test: true } : undefined
        });

        if (response.status === 200 && method !== 'GET') {
          this.findings.push({
            type: 'privilege-escalation',
            vector: 'method-manipulation',
            severity: 'high',
            issue: `Admin operation possible with ${method} on ${endpoint}`,
            evidence: `Status: ${response.status}`
          });
        }
      }
    }
  }

  async testHeaderInjection() {
    console.log('\n--- Header Injection ---');

    const adminHeaders = [
      { 'X-Admin': 'true' },
      { 'X-Role': 'admin' },
      { 'X-User-Type': 'admin' },
      { 'X-Forwarded-For': '127.0.0.1' },
      { 'X-Original-URL': '/admin' },
      { 'X-Rewrite-URL': '/admin' },
      { 'X-Forwarded-Host': 'internal' }
    ];

    for (const headers of adminHeaders) {
      const response = await this.client.get('/api/users', {
        headers: {
          ...headers,
          'Authorization': `Bearer ${this.userToken}`
        }
      });

      if (response.status === 200) {
        const data = response.data;
        // Check if response contains admin data
        if (JSON.stringify(data).includes('admin') || 
            JSON.stringify(data).includes('password')) {
          this.findings.push({
            type: 'privilege-escalation',
            vector: 'header-injection',
            severity: 'high',
            issue: `Admin access via header: ${JSON.stringify(headers)}`,
            evidence: 'Response contains admin-level data'
          });
        }
      }
    }
  }

  async testRoleInference() {
    console.log('\n--- Role Inference ---');

    // Try to infer admin IDs
    const response = await this.client.get('/api/users', {
        headers: { 'Authorization': `Bearer ${this.adminToken}` }
      });

    if (response.status === 200) {
      const users = response.data.users || response.data;

      // Look for admin users
      const admins = users.filter(u => 
        u.role === 'admin' || 
        u.isAdmin === true || 
        u.userType === 'admin'
      );

      for (const admin of admins) {
        // Try to impersonate admin
        const impersonateResponse = await this.client.get(`/api/users/${admin.id}`, {
          headers: { 'Authorization': `Bearer ${this.userToken}` }
        });

        if (impersonateResponse.status === 200) {
          this.findings.push({
            type: 'privilege-escalation',
            vector: 'role-inference',
            severity: 'critical',
            issue: `Able to access admin user ${admin.id} data`,
            evidence: `Accessed admin profile`
          });
        }
      }
    }
  }
}
```

**Key Insight:** Privilege escalation is often the highest-impact finding. Test every possible way to gain higher permissions.

