Disaster recovery testing verifies that you can restore service after a catastrophic failure, such as losing an entire data center.

**DR Test Plan:**

```javascript
// reliability/disaster-recovery-test.js
class DisasterRecoveryTester {
  constructor(config) {
    this.primaryRegion = config.primaryRegion;
    this.drRegion = config.drRegion;
    this.rto = config.rto || 3600; // Recovery Time Objective (seconds)
    this.rpo = config.rpo || 300;   // Recovery Point Objective (seconds)
    this.backupTime = null;
    this.recoveryTime = null;
  }

  async runTest() {
    console.log('Starting disaster recovery test...');

    // 1. Create test data
    const testData = await this.createTestData();
    console.log('Test data created');

    // 2. Simulate disaster (shutdown primary)
    await this.simulateDisaster();

    // 3. Verify outage
    const primaryDown = await this.isPrimaryDown();
    console.log(`Primary down: ${primaryDown}`);

    // 4. Trigger DR failover
    const failoverStart = Date.now();
    await this.failoverToDR();
    this.recoveryTime = (Date.now() - failoverStart) / 1000;

    // 5. Verify DR region is serving
    const drUp = await this.isDROperational();
    console.log(`DR operational: ${drUp}`);

    // 6. Verify data consistency
    const dataConsistent = await this.verifyDataConsistency(testData);

    // 7. Calculate data loss
    const dataLoss = await this.calculateDataLoss(testData.timestamp);

    return {
      rto: this.recoveryTime,
      rtoPassed: this.recoveryTime <= this.rto,
      rpo: dataLoss,
      rpoPassed: dataLoss <= this.rpo,
      dataConsistent,
      drUp
    };
  }

  async createTestData() {
    const timestamp = Date.now();
    const response = await axios.post('https://api.example.com/test-data', {
      testId: `dr-test-${timestamp}`,
      data: 'recovery test data',
      timestamp
    });

    return { id: response.data.id, timestamp };
  }

  async simulateDisaster() {
    // In real test, this might:
    // - Terminate primary region instances
    // - Block all traffic to primary
    // - Simulate region outage
    console.log('Simulating region outage...');
    this.backupTime = Date.now();
  }

  async isPrimaryDown() {
    try {
      await axios.get(`https://${this.primaryRegion}.api.example.com/health`, {
        timeout: 2000
      });
      return false; // Still up - bad
    } catch {
      return true; // Down - good
    }
  }

  async failoverToDR() {
    // In real test, this might:
    // - Update DNS
    // - Activate DR load balancer
    // - Scale up DR instances
    console.log('Failing over to DR region...');
    // Simulate failover time
    await new Promise(r => setTimeout(r, 5000));
  }

  async isDROperational() {
    try {
      const response = await axios.get(`https://${this.drRegion}.api.example.com/health`);
      return response.status === 200;
    } catch {
      return false;
    }
  }

  async verifyDataConsistency(testData) {
    try {
      const response = await axios.get(`https://api.example.com/test-data/${testData.id}`);
      return response.data.data === 'recovery test data';
    } catch {
      return false;
    }
  }

  async calculateDataLoss(creationTimestamp) {
    // Calculate seconds of data lost
    if (!this.backupTime) return 0;
    return Math.max(0, (this.backupTime - creationTimestamp) / 1000);
  }
}

// Test
describe('Disaster Recovery', () => {
  it('should meet RTO and RPO objectives', async () => {
    const dr = new DisasterRecoveryTester({
      primaryRegion: 'us-east',
      drRegion: 'us-west',
      rto: 300,  // 5 minutes
      rpo: 60    // 1 minute
    });

    const results = await dr.runTest();

    expect(results.rtoPassed).toBe(true);
    expect(results.rpoPassed).toBe(true);
    expect(results.dataConsistent).toBe(true);
    expect(results.drUp).toBe(true);

    console.log(`RTO achieved: ${results.rto}s (target: ${dr.rto}s)`);
    console.log(`RPO achieved: ${results.rpo}s (target: ${dr.rpo}s)`);
  });
});
```

