**Key Insight:** Reliability testing is never "done". Run these tests continuously in CI/CD and in production to ensure your API stays reliable.

CRUD (Create, Read, Update, Delete) operations must maintain data integrity. Test each operation individually and in sequence.

**CRUD Integrity Tests:**

```javascript
// integrity/crud-test.js
const axios = require('axios');

describe('CRUD Operation Integrity', () => {
  let createdId;
  const baseURL = 'https://api.example.com/users';

  it('should create a resource with all fields', async () => {
    const userData = {
      name: 'John Doe',
      email: 'john@example.com',
      age: 30,
      preferences: {
        theme: 'dark',
        notifications: true
      }
    };

    const response = await axios.post(baseURL, userData);
    expect(response.status).toBe(201);
    expect(response.data.id).toBeDefined();

    // Verify all fields returned correctly
    expect(response.data.name).toBe(userData.name);
    expect(response.data.email).toBe(userData.email);
    expect(response.data.age).toBe(userData.age);
    expect(response.data.preferences.theme).toBe('dark');

    createdId = response.data.id;
  });

  it('should read the created resource correctly', async () => {
    const response = await axios.get(`${baseURL}/${createdId}`);

    expect(response.status).toBe(200);
    expect(response.data.id).toBe(createdId);
    expect(response.data.name).toBe('John Doe');
    expect(response.data.email).toBe('john@example.com');
  });

  it('should update resource partially (PATCH)', async () => {
    const response = await axios.patch(`${baseURL}/${createdId}`, {
      name: 'John Updated',
      age: 31
    });

    expect(response.status).toBe(200);
    expect(response.data.name).toBe('John Updated');
    expect(response.data.age).toBe(31);

    // Email should remain unchanged
    expect(response.data.email).toBe('john@example.com');
  });

  it('should replace resource fully (PUT)', async () => {
    const response = await axios.put(`${baseURL}/${createdId}`, {
      name: 'John Replaced',
      email: 'john.replaced@example.com',
      age: 32
    });

    expect(response.status).toBe(200);
    expect(response.data.name).toBe('John Replaced');
    expect(response.data.email).toBe('john.replaced@example.com');
    expect(response.data.age).toBe(32);
  });

  it('should delete the resource', async () => {
    const deleteResponse = await axios.delete(`${baseURL}/${createdId}`);
    expect(deleteResponse.status).toBe(204);

    // Verify it's gone
    try {
      await axios.get(`${baseURL}/${createdId}`);
      throw new Error('Should have failed');
    } catch (error) {
      expect(error.response.status).toBe(404);
    }
  });
});
```

**Bulk Operation Integrity:**

```javascript
// integrity/bulk-test.js
describe('Bulk Operations', () => {
  it('should create multiple resources atomically', async () => {
    const users = [
      { name: 'User 1', email: 'user1@test.com' },
      { name: 'User 2', email: 'user2@test.com' },
      { name: 'User 3', email: 'user3@test.com' }
    ];

    const response = await axios.post('https://api.example.com/users/bulk', users);
    expect(response.status).toBe(201);
    expect(response.data.created).toBe(3);
    expect(response.data.ids).toHaveLength(3);

    // Verify all were created
    for (const id of response.data.ids) {
      const user = await axios.get(`https://api.example.com/users/${id}`);
      expect(user.status).toBe(200);
    }
  });

  it('should rollback if any resource fails', async () => {
    const users = [
      { name: 'Valid 1', email: 'valid1@test.com' },
      { name: 'Valid 2', email: 'valid2@test.com' },
      { name: 'Invalid', email: 'not-an-email' } // Should fail
    ];

    try {
      await axios.post('https://api.example.com/users/bulk', users);
    } catch (error) {
      expect(error.response.status).toBe(400);

      // Verify no users were created
      const allUsers = await axios.get('https://api.example.com/users');
      const emails = allUsers.data.map(u => u.email);
      expect(emails).not.toContain('valid1@test.com');
      expect(emails).not.toContain('valid2@test.com');
    }
  });
});
