      await axios.post('https://api.example.com/transactions/start');
      await axios.post('https://api.example.com/accounts/123/withdraw', { amount: 100 });
      // Not committed yet
    })();

    // Try to read during transaction
    setTimeout(async () => {
      const balance = await axios.get('https://api.example.com/accounts/123/balance');
      // Should not see uncommitted change
      expect(balance.data.amount).toBe(originalBalance);
    }, 100);

    await transactionPromise;
  });
});
