**Data Integrity Audit:**

```javascript
// integrity/audit-test.js
class DataAuditor {
  constructor(apiUrl) {
    this.apiUrl = apiUrl;
    this.issues = [];
  }

  async auditTable(endpoint, validationFn) {
    console.log(`Auditing ${endpoint}...`);
    let page = 1;
    let hasMore = true;

    while (hasMore) {
      const response = await axios.get(`${this.apiUrl}${endpoint}`, {
        params: { page, limit: 100 }
      });

      const items = response.data.items || response.data;

      for (const item of items) {
        const validation = await validationFn(item);
        if (!validation.valid) {
          this.issues.push({
            endpoint,
            id: item.id,
            field: validation.field,
            expected: validation.expected,
            actual: validation.actual
          });
        }
      }

      hasMore = items.length === 100;
      page++;
    }
  }

  async runFullAudit() {
    await this.auditTable('/users', this.validateUser);
    await this.auditTable('/orders', this.validateOrder);
    await this.auditTable('/products', this.validateProduct);

    return {
      timestamp: new Date().toISOString(),
      totalIssues: this.issues.length,
      issues: this.issues
    };
  }

  validateUser(user) {
    // Check email format
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(user.email)) {
      return { valid: false, field: 'email', expected: 'valid email', actual: user.email };
    }

    // Check age range
    if (user.age && (user.age < 0 || user.age > 150)) {
      return { valid: false, field: 'age', expected: '0-150', actual: user.age };
    }

    return { valid: true };
  }

  validateOrder(order) {
    // Total should equal sum of items
    const calculatedTotal = order.items.reduce(
      (sum, item) => sum + (item.price * item.quantity), 0
    );

    if (Math.abs(calculatedTotal - order.total) > 0.01) {
      return {
        valid: false,
        field: 'total',
        expected: calculatedTotal,
        actual: order.total
      };
    }

    return { valid: true };
  }

  validateProduct(product) {
    // Price should be positive
    if (product.price <= 0) {
      return { valid: false, field: 'price', expected: '>0', actual: product.price };
    }

    // Stock should be non-negative integer
    if (!Number.isInteger(product.stock) || product.stock < 0) {
      return { valid: false, field: 'stock', expected: 'non-negative integer', actual: product.stock };
    }

    return { valid: true };
  }
}

// Usage
const auditor = new DataAuditor('https://api.example.com');
const auditResult = await auditor.runFullAudit();
console.log(`Found ${auditResult.totalIssues} data integrity issues`);
```

**Key Insight:** Data corruption is often silent. Regular audits and validation on every read/write can catch it early.

