Locking prevents concurrent access to shared resources. Test both pessimistic and optimistic locking implementations.

**Pessimistic Locking Test:**

```javascript
// concurrency/pessimistic-lock.js
describe('Pessimistic Locking', () => {
  it('should prevent concurrent access with locks', async () => {
    const startTime = Date.now();

    // First request acquires lock
    const request1 = axios.post('https://api.example.com/accounts/123/withdraw', {
      amount: 100
    });

    // Small delay to ensure first request gets lock first
    await new Promise(r => setTimeout(r, 100));

    // Second request should wait or fail
    const request2 = axios.post('https://api.example.com/accounts/123/withdraw', {
      amount: 100
    });

    const results = await Promise.allSettled([request1, request2]);
    const endTime = Date.now();

    // First should succeed
    expect(results[0].status).toBe('fulfilled');

    // Second either fails or succeeds after waiting
    if (results[1].status === 'fulfilled') {
      // If it succeeded, it should have taken longer
      const request2Time = results[1].value.headers['x-processing-time'];
      const request1Time = results[0].value.headers['x-processing-time'];
      expect(request2Time).toBeGreaterThan(request1Time);
    } else {
      // Or it fails with lock contention error
      expect(results[1].reason.response.status).toBe(409);
    }
  });

  it('should release locks after transaction completes', async () => {
    // First request - acquires and releases lock
    await axios.post('https://api.example.com/accounts/123/withdraw', {
      amount: 100
    });

    // Second request - should acquire lock immediately
    const start = Date.now();
    await axios.post('https://api.example.com/accounts/123/withdraw', {
      amount: 100
    });
    const duration = Date.now() - start;

    // Should be fast (no waiting)
    expect(duration).toBeLessThan(500);
  });
});
```

**Optimistic Locking with Version:**

```javascript
// concurrency/optimistic-lock.js
describe('Optimistic Locking', () => {
  let docId, version;

  beforeAll(async () => {
    const doc = await axios.post('https://api.example.com/documents', {
      title: 'Test',
      content: 'Version 1'
    });
    docId = doc.data.id;
    version = doc.data.version;
  });

  it('should allow update with correct version', async () => {
    const response = await axios.patch(`https://api.example.com/documents/${docId}`, {
      content: 'Version 2',
      version: version
    });

    expect(response.status).toBe(200);
    expect(response.data.version).toBe(version + 1);
  });

  it('should reject update with stale version', async () => {
    // Try to update with old version
    try {
      await axios.patch(`https://api.example.com/documents/${docId}`, {
        content: 'Should fail',
        version: version // Old version
      });
      throw new Error('Should have failed');
    } catch (error) {
      expect(error.response.status).toBe(409); // Conflict
      expect(error.response.data.error).toContain('stale version');
    }
  });

  it('should handle concurrent updates with version', async () => {
    // Get current version
    const doc = await axios.get(`https://api.example.com/documents/${docId}`);
    const currentVersion = doc.data.version;

    // Two concurrent updates with same version
    const update1 = axios.patch(`https://api.example.com/documents/${docId}`, {
      content: 'Update A',
      version: currentVersion
    });

    const update2 = axios.patch(`https://api.example.com/documents/${docId}`, {
      content: 'Update B',
      version: currentVersion
    });

    const results = await Promise.allSettled([update1, update2]);

    // Exactly one should succeed
    const successes = results.filter(r => r.status === 'fulfilled');
    expect(successes.length).toBe(1);

    // The other should fail with 409
    const failures = results.filter(r => r.status === 'rejected');
    expect(failures[0].reason.response.status).toBe(409);
  });

  it('should handle retry logic for optimistic locking', async () => {
    let attempts = 0;
    let success = false;

    while (!success && attempts < 5) {
      try {
        const doc = await axios.get(`https://api.example.com/documents/${docId}`);
        const response = await axios.patch(`https://api.example.com/documents/${docId}`, {
          content: `Retry attempt ${attempts + 1}`,
          version: doc.data.version
        });
        success = true;
        expect(response.status).toBe(200);
      } catch (error) {
        if (error.response?.status !== 409) throw error;
        attempts++;
        // Exponential backoff
        await new Promise(r => setTimeout(r, Math.pow(2, attempts) * 100));
      }
    }

    expect(success).toBe(true);
    expect(attempts).toBeLessThan(5);
  });
});
```

**Key Insight:** Pessimistic locking is safer but slower. Optimistic locking scales better but requires retry logic. Test both thoroughly.

Race conditions are hard to reproduce. Use specialized techniques to increase probability and detect them.

**Race Condition Detector:**

```javascript
// concurrency/race-detector.js
class RaceConditionDetector {
  constructor(apiUrl) {
    this.apiUrl = apiUrl;
    this.results = [];
  }

  async runTest(endpoint, method, data, iterations = 100) {
    console.log(`Running race detection with ${iterations} iterations`);

    const allResults = [];

    for (let i = 0; i < iterations; i++) {
      const result = await this.runSingleIteration(endpoint, method, data);
      allResults.push(result);

      // Small delay between iterations
      await new Promise(r => setTimeout(r, 100));
    }

    return this.analyze(allResults);
  }

  async runSingleIteration(endpoint, method, data) {
    // Reset to known state
    await axios.post(`${this.apiUrl}/test/reset`, { scenario: endpoint });

    const requests = [];
    for (let i = 0; i < 5; i++) {
      requests.push(
        axios({
          method,
          url: `${this.apiUrl}${endpoint}`,
          data,
          validateStatus: () => true
        })
      );
    }

    const responses = await Promise.all(requests);

    // Check final state
    const finalState = await axios.get(`${this.apiUrl}${endpoint}/state`);

    return {
      responses: responses.map(r => ({ status: r.status, data: r.data })),
      finalState: finalState.data
    };
  }

  analyze(results) {
    const anomalies = [];

    // Group by outcome pattern
    const patterns = {};
    results.forEach((result, i) => {
      const key = this.getPatternKey(result);
      if (!patterns[key]) patterns[key] = [];
      patterns[key].push(i);
    });

    // Multiple patterns indicate non-deterministic behavior
    if (Object.keys(patterns).length > 1) {
      anomalies.push({
        type: 'NON_DETERMINISTIC',
        patterns: Object.keys(patterns),
        counts: Object.values(patterns).map(p => p.length)
      });
    }

    // Check for invariant violations
    results.forEach(result => {
      const violations = this.checkInvariants(result);
      if (violations.length > 0) {
        anomalies.push({
          type: 'INVARIANT_VIOLATION',
          violations
        });
      }
    });

    return {
      totalRuns: results.length,
      uniqueOutcomes: Object.keys(patterns).length,
      anomalies,
      patterns
    };
  }

  getPatternKey(result) {
    // Create a string representing the outcome pattern
    const statuses = result.responses.map(r => r.status).sort().join(',');
    const finalStock = result.finalState.stock;
    return `${statuses}|${finalStock}`;
  }

  checkInvariants(result) {
    const violations = [];

    // Stock should never be negative
    if (result.finalState.stock < 0) {
      violations.push('Negative stock detected');
    }

    // Number of successes shouldn't exceed initial stock
    const successes = result.responses.filter(r => r.status === 200).length;
    if (successes > result.finalState.initialStock) {
      violations.push(`Oversold: ${successes} successes for ${result.finalState.initialStock} items`);
    }

    return violations;
  }
}

// Usage
describe('Race Condition Detection', () => {
  it('should find race conditions in purchase flow', async () => {
    const detector = new RaceConditionDetector('https://api.example.com');

    const results = await detector.runTest('/items/123/buy', 'POST', {}, 100);

    expect(results.anomalies.length).toBe(0);
    expect(results.uniqueOutcomes).toBe(1); // Should be deterministic
  }, 60000); // Long timeout
});
```

**Stress Testing for Races:**

```javascript
// concurrency/stress-test.js
class StressTester {
  constructor(baseURL) {
    this.baseURL = baseURL;
  }

  async stressTest(endpoint, options = {}) {
    const {
      concurrency = 50,
      duration = 10000,
      rampUp = true
    } = options;

    console.log(`Stress testing ${endpoint} with ${concurrency} concurrent users`);
    const startTime = Date.now();
    const requests = [];
    const results = [];

    while (Date.now() - startTime < duration) {
      // Create batch of concurrent requests
      const batch = [];
      let currentConcurrency = concurrency;

      if (rampUp) {
        // Gradually increase concurrency
        const progress = (Date.now() - startTime) / duration;
        currentConcurrency = Math.max(1, Math.floor(concurrency * progress));
      }

      for (let i = 0; i < currentConcurrency; i++) {
        batch.push(
          axios.get(`${this.baseURL}${endpoint}`)
            .then(r => ({ success: true, status: r.status }))
            .catch(e => ({ success: false, error: e.message }))
        );
      }

      const batchResults = await Promise.all(batch);
      results.push(...batchResults);

      // Small delay between batches
      await new Promise(r => setTimeout(r, 100));
    }

    return this.analyzeStressResults(results);
  }

  analyzeStressResults(results) {
    const total = results.length;
    const successes = results.filter(r => r.success).length;
    const errors = results.filter(r => !r.success).length;

    // Group errors by type
    const errorTypes = {};
    results.filter(r => !r.success).forEach(r => {
      const type = r.error.includes('timeout') ? 'timeout' :
                   r.error.includes('ECONNREFUSED') ? 'connection' :
                   'other';
      errorTypes[type] = (errorTypes[type] || 0) + 1;
    });

    return {
      total,
      successes,
      errors,
      errorRate: (errors / total) * 100,
      errorTypes
    };
  }
}

// Usage
const stress = new StressTester('https://api.example.com');
const results = await stress.stressTest('/products', {
  concurrency: 100,
  duration: 30000
});
console.log('Stress test results:', results);
```

**Key Insight:** Run tests hundreds of times. Race conditions are probabilistic—if you only run once, you might miss them.

Deadlocks occur when two or more operations wait for each other indefinitely. They can bring your API to a halt.

**Deadlock Test Examples:**

```javascript
// concurrency/deadlock-test.js
describe('Deadlock Detection', () => {
  it('should detect deadlock in circular dependency', async () => {
    // Create two accounts
    const account1 = await axios.post('https://api.example.com/accounts', { balance: 1000 });
    const account2 = await axios.post('https://api.example.com/accounts', { balance: 1000 });

    // Transfer from 1→2 and 2→1 simultaneously
    const transfer1 = axios.post('https://api.example.com/transfers', {
      from: account1.data.id,
      to: account2.data.id,
      amount: 100
    });

    const transfer2 = axios.post('https://api.example.com/transfers', {
      from: account2.data.id,
      to: account1.data.id,
      amount: 100
    });

    const start = Date.now();
    const results = await Promise.allSettled([transfer1, transfer2]);
    const duration = Date.now() - start;

    // Should complete within reasonable time
    expect(duration).toBeLessThan(5000);

    // Both should succeed or one should fail
    const successes = results.filter(r => r.status === 'fulfilled').length;
    expect(successes).toBeGreaterThan(0);

    // Final balances should be consistent
    const bal1 = await axios.get(`https://api.example.com/accounts/${account1.data.id}`);
    const bal2 = await axios.get(`https://api.example.com/accounts/${account2.data.id}`);

    expect(bal1.data.balance + bal2.data.balance).toBe(2000); // Total conserved
  });

  it('should have timeout for lock acquisition', async () => {
    // Acquire lock on account
    const lock1 = await axios.post('https://api.example.com/locks/acquire', {
      resource: 'account-123'
    });

    // Try to acquire same lock
    try {
      await axios.post('https://api.example.com/locks/acquire', {
        resource: 'account-123',
        timeout: 1000 // 1 second timeout
      });
      throw new Error('Should have timed out');
    } catch (error) {
      expect(error.response.status).toBe(408); // Timeout
    }

    // Release first lock
    await axios.post('https://api.example.com/locks/release', {
      lockId: lock1.data.id
    });
  });

  it('should detect and resolve deadlocks automatically', async () => {
    // Create multiple resources that could deadlock
    const resources = ['A', 'B', 'C', 'D'];
    const operations = [];

    // Create operations that acquire resources in different orders
    operations.push(
      axios.post('https://api.example.com/batch-operation', {
        operations: [
          { type: 'lock', resource: 'A' },
          { type: 'lock', resource: 'B' },
          { type: 'update', data: 'op1' },
          { type: 'unlock', resource: 'B' },
          { type: 'unlock', resource: 'A' }
        ]
      })
    );

    operations.push(
      axios.post('https://api.example.com/batch-operation', {
        operations: [
          { type: 'lock', resource: 'B' },
          { type: 'lock', resource: 'A' },
          { type: 'update', data: 'op2' },
          { type: 'unlock', resource: 'A' },
          { type: 'unlock', resource: 'B' }
        ]
      })
    );

    const results = await Promise.allSettled(operations);

    // At least one should succeed (deadlock detection should resolve)
    const successes = results.filter(r => r.status === 'fulfilled');
    expect(successes.length).toBeGreaterThan(0);

    // None should hang indefinitely
    const failures = results.filter(r => r.status === 'rejected');
    failures.forEach(f => {
      expect(f.reason.response?.status).not.toBe(504); // No timeout
    });
  });
});
```

**Lock Ordering Test:**

```javascript
// concurrency/lock-ordering.js
describe('Lock Ordering', () => {
  it('should enforce consistent lock ordering', async () => {
    const resources = [1, 2, 3, 4, 5];
    const operations = [];

    // Generate operations with random lock orders
    for (let i = 0; i < 10; i++) {
      const shuffled = [...resources].sort(() => Math.random() - 0.5);

      operations.push(
        axios.post('https://api.example.com/transaction', {
          locks: shuffled,
          operation: `op-${i}`
        })
      );
    }

    const results = await Promise.allSettled(operations);

    // Some may fail due to deadlock, but none should hang
    const timeouts = results.filter(r => 
      r.status === 'rejected' && r.reason.code === 'ECONNABORTED'
    );
    expect(timeouts.length).toBe(0);
  });
});
```

**Key Insight:** Deadlocks are easier to prevent than to detect. Test with consistent lock ordering and timeouts.

Database concurrency issues can corrupt data. Test different isolation levels and their effects.

**Isolation Level Tests:**

```javascript
// concurrency/isolation-test.js
describe('Transaction Isolation', () => {
  it('should prevent dirty reads at READ_COMMITTED', async () => {
    // Start transaction but don't commit
    const transaction = axios.post('https://api.example.com/transactions/start', {
      operations: [
        { type: 'update', table: 'accounts', id: 123, data: { balance: 500 } }
      ]
    });

    // Try to read during transaction
    setTimeout(async () => {
      const account = await axios.get('https://api.example.com/accounts/123');
      // Should not see uncommitted change
      expect(account.data.balance).toBe(1000); // Original balance
    }, 100);

    await transaction;
  });

  it('should prevent non-repeatable reads at REPEATABLE_READ', async () => {
    // First read
    const read1 = await axios.get('https://api.example.com/accounts/123');

    // Another transaction modifies
    await axios.post('https://api.example.com/transfers', {
      from: 123,
      to: 456,
      amount: 100
    });

    // Second read in same transaction should see same data
    const read2 = await axios.get('https://api.example.com/accounts/123', {
      headers: { 'X-Transaction-Id': read1.headers['x-transaction-id'] }
    });

    expect(read2.data.balance).toBe(read1.data.balance);
  });

  it('should prevent phantom reads at SERIALIZABLE', async () => {
    // First read
    const read1 = await axios.get('https://api.example.com/accounts', {
      params: { balance_gt: 500 }
    });

    // Another transaction inserts new matching record
    await axios.post('https://api.example.com/accounts', { balance: 600 });

    // Second read in same transaction should see same count
    const read2 = await axios.get('https://api.example.com/accounts', {
      params: { balance_gt: 500 },
      headers: { 'X-Transaction-Id': read1.headers['x-transaction-id'] }
    });

    expect(read2.data.length).toBe(read1.data.length);
  });
});
```

**Database Deadlock Test:**

```javascript
// concurrency/db-deadlock.js
describe('Database Deadlock Handling', () => {
  it('should retry on deadlock', async () => {
    let attempts = 0;
    let success = false;

    while (!success && attempts < 3) {
      try {
        await axios.post('https://api.example.com/complex-transfer', {
          from: 123,
          to: 456,
          amount: 50
        });
        success = true;
      } catch (error) {
        if (error.response?.status === 409 && 
            error.response.data.error.includes('deadlock')) {
          attempts++;
          await new Promise(r => setTimeout(r, 100 * Math.pow(2, attempts)));
        } else {
          throw error;
        }
      }
    }

    expect(success).toBe(true);
  });

  it('should log deadlock occurrences', async () => {
    // Trigger deadlock
    try {
      await triggerDeadlock();
    } catch (error) {
      // Check logs
      const logs = await axios.get('https://api.example.com/admin/logs', {
        params: { level: 'deadlock', limit: 10 }
      });

      expect(logs.data.length).toBeGreaterThan(0);
      expect(logs.data[0].message).toContain('deadlock');
    }
  });
});
```

**Key Insight:** Database concurrency is complex. Test at different isolation levels and verify that deadlocks are handled gracefully.

Distributed transactions span multiple services. Testing them requires coordinating across service boundaries.

**Saga Pattern Test:**

```javascript
// concurrency/saga-test.js
describe('Saga Pattern', () => {
  it('should complete distributed transaction successfully', async () => {
    const orderData = {
      userId: 123,
      items: [{ productId: 456, quantity: 1 }],
      payment: { method: 'card', amount: 100 }
    };

    const response = await axios.post('https://api.example.com/orders/saga', orderData);

    expect(response.status).toBe(201);
    const orderId = response.data.id;

    // Verify all services updated
    const order = await axios.get(`https://api.example.com/orders/${orderId}`);
    expect(order.data.status).toBe('COMPLETED');

    const inventory = await axios.get(`https://api.example.com/products/456`);
    expect(inventory.data.stock).toBe(originalStock - 1);

    const payment = await axios.get(`https://api.example.com/payments/${order.data.paymentId}`);
    expect(payment.data.status).toBe('SUCCESS');
  });

  it('should rollback all services on failure', async () => {
    const originalStock = await getProductStock(456);
    const originalBalance = await getUserBalance(123);

    const orderData = {
      userId: 123,
      items: [{ productId: 456, quantity: 1 }],
      payment: { method: 'card', amount: 1000000 } // Will fail
    };

    try {
      await axios.post('https://api.example.com/orders/saga', orderData);
    } catch (error) {
      expect(error.response.status).toBe(500);

      // Wait for rollback to complete
      await new Promise(r => setTimeout(r, 1000));

      // Verify all services rolled back
      const stock = await getProductStock(456);
      expect(stock).toBe(originalStock);

      const balance = await getUserBalance(123);
      expect(balance).toBe(originalBalance);

      // Verify compensating transactions logged
      const logs = await axios.get('https://api.example.com/admin/logs', {
        params: { type: 'compensation' }
      });
      expect(logs.data.length).toBeGreaterThan(0);
    }
  });

  it('should handle partial failures with compensation', async () => {
    // Simulate failure in third service
    await axios.post('https://api.example.com/test/inject-failure', {
      service: 'inventory',
      failAfter: 2 // Fail after 2 successful operations
    });

    const orderData = {
      userId: 123,
      items: [
        { productId: 456, quantity: 1 },
        { productId: 789, quantity: 2 }
      ],
      payment: { method: 'card', amount: 300 }
    };

    try {
      await axios.post('https://api.example.com/orders/saga', orderData);
    } catch (error) {
      // Wait for compensations
      await new Promise(r => setTimeout(r, 2000));

      // Verify all services compensated
      const product1 = await axios.get('https://api.example.com/products/456');
      const product2 = await axios.get('https://api.example.com/products/789');

      expect(product1.data.stock).toBe(originalStock1);
      expect(product2.data.stock).toBe(originalStock2);

      const payments = await axios.get('https://api.example.com/payments', {
        params: { userId: 123, limit: 1 }
      });
      expect(payments.data.length).toBe(0);
    }
  });
});
```

**Two-Phase Commit Test:**

```javascript
// concurrency/2pc-test.js
describe('Two-Phase Commit', () => {
  it('should commit when all participants agree', async () => {
    const transaction = await axios.post('https://api.example.com/transactions/begin', {
      participants: ['order-service', 'payment-service', 'inventory-service']
    });
    const txId = transaction.data.id;

    // Prepare phase - all should succeed
    const prepare = await axios.post(`https://api.example.com/transactions/${txId}/prepare`);
    expect(prepare.status).toBe(200);
    expect(prepare.data.participants.every(p => p.status === 'READY')).toBe(true);

    // Commit phase
    const commit = await axios.post(`https://api.example.com/transactions/${txId}/commit`);
    expect(commit.status).toBe(200);

    // Verify all committed
    const status = await axios.get(`https://api.example.com/transactions/${txId}`);
    expect(status.data.state).toBe('COMMITTED');
  });

  it('should rollback when any participant fails prepare', async () => {
    // Inject failure in one service
    await axios.post('https://api.example.com/test/inject-failure', {
      service: 'payment-service',
      failOn: 'prepare'
    });

    const transaction = await axios.post('https://api.example.com/transactions/begin', {
      participants: ['order-service', 'payment-service', 'inventory-service']
    });
    const txId = transaction.data.id;

    // Prepare phase - should fail
    try {
      await axios.post(`https://api.example.com/transactions/${txId}/prepare`);
    } catch (error) {
      expect(error.response.status).toBe(409);

      // Transaction should be rolled back
      const status = await axios.get(`https://api.example.com/transactions/${txId}`);
      expect(status.data.state).toBe('ABORTED');
    }
  });
});
```

**Key Insight:** Distributed transactions are complex. Test success paths, failure paths, and recovery paths thoroughly.

Atomic operations (compare-and-swap, increment) prevent race conditions at the database level.

**Atomic Operation Tests:**

```javascript
// concurrency/atomic-test.js
describe('Atomic Operations', () => {
  it('should handle atomic increments correctly', async () => {
    const requests = [];
    for (let i = 0; i < 100; i++) {
      requests.push(
        axios.post('https://api.example.com/counters/123/increment')
      );
    }

    await Promise.all(requests);

    const counter = await axios.get('https://api.example.com/counters/123');
    expect(counter.data.value).toBe(100);
  });

  it('should handle compare-and-swap operations', async () => {
    // Get current value
    const counter = await axios.get('https://api.example.com/counters/123');
    const currentValue = counter.data.value;
    const version = counter.data.version;

    // Update with CAS
    const update = await axios.post('https://api.example.com/counters/123/cas', {
      expected: currentValue,
      newValue: currentValue + 50,
      version: version
    });
    expect(update.status).toBe(200);

    // Try with wrong expected value
    try {
      await axios.post('https://api.example.com/counters/123/cas', {
        expected: currentValue, // Old value
        newValue: currentValue + 100,
        version: version
      });
      throw new Error('Should have failed');
    } catch (error) {
      expect(error.response.status).toBe(409);
    }
  });

  it('should handle concurrent CAS operations', async () => {
    // Reset counter
    await axios.post('https://api.example.com/counters/123/reset', { value: 0 });

    const operations = [];
    for (let i = 0; i < 10; i++) {
      operations.push(
        (async () => {
          let success = false;
          let attempts = 0;

          while (!success && attempts < 5) {
            try {
              const current = await axios.get('https://api.example.com/counters/123');
              await axios.post('https://api.example.com/counters/123/cas', {
                expected: current.data.value,
                newValue: current.data.value + 10,
                version: current.data.version
              });
              success = true;
            } catch (error) {
              if (error.response?.status === 409) {
                attempts++;
                await new Promise(r => setTimeout(r, 10));
              } else {
                throw error;
              }
            }
          }
          return success;
        })()
      );
    }

    const results = await Promise.all(operations);
    const successes = results.filter(r => r).length;

    const final = await axios.get('https://api.example.com/counters/123');
    expect(final.data.value).toBe(successes * 10);
  });
});
```

**Key Insight:** Atomic operations are the building blocks of thread-safe APIs. Test them under heavy concurrency.

