**Quick Concurrency Test Suite:**

```javascript
// concurrency/quick-test.js
const test = require('ava');
const axios = require('axios');

async function runParallel(endpoint, count = 10) {
  const requests = Array(count).fill().map(() => axios.post(endpoint));
  return Promise.allSettled(requests);
}

test('parallel purchases of last item', async t => {
  await axios.post('https://api.example.com/test/reset-stock/123', { stock: 1 });

  const results = await runParallel('https://api.example.com/items/123/buy', 5);

  const successes = results.filter(r => r.status === 'fulfilled').length;
  t.is(successes, 1);
});

test('concurrent account withdrawals', async t => {
  await axios.post('https://api.example.com/test/set-balance/123', { balance: 100 });

  const results = await runParallel('https://api.example.com/accounts/123/withdraw/20', 10);

  const successes = results.filter(r => r.status === 'fulfilled').length;
  t.is(successes, 5); // 100/20 = 5 max

  const account = await axios.get('https://api.example.com/accounts/123');
  t.is(account.data.balance, 0);
});

test('optimistic locking', async t => {
  const doc = await axios.post('https://api.example.com/documents', { content: 'test' });
  const version = doc.data.version;

  const updates = [
    axios.patch(`https://api.example.com/documents/${doc.data.id}`, { content: 'a', version }),
    axios.patch(`https://api.example.com/documents/${doc.data.id}`, { content: 'b', version })
  ];

  const results = await Promise.allSettled(updates);
  const successes = results.filter(r => r.status === 'fulfilled').length;
  t.is(successes, 1);
});

test('unique constraint under concurrency', async t => {
  const email = `test${Date.now()}@test.com`;
  const registrations = Array(5).fill().map(() => 
    axios.post('https://api.example.com/users', { email, name: 'Test' })
  );

  const results = await Promise.allSettled(registrations);
  const successes = results.filter(r => r.status === 'fulfilled').length;
  t.is(successes, 1);
});
```

**Key Insight:** Concurrency bugs are the most difficult to find and fix. Test early, test often, and test with production-like concurrency levels.

How you structure your tests determines how long they'll survive. Good test design makes tests readable, maintainable, and reliable.

**The Anatomy of a Good Test:**

Every test should follow the Arrange-Act-Assert pattern:

```javascript
test('should create a new user', async () => {
  // ARRANGE - Set up the test data
  const userData = {
    name: 'John Doe',
    email: 'john@example.com',
    age: 30
  };

  // ACT - Perform the operation
  const response = await api.post('/users', userData);

  // ASSERT - Verify the result
  expect(response.status).toBe(201);
  expect(response.data).toMatchObject({
    name: userData.name,
    email: userData.email,
    age: userData.age
  });
  expect(response.data.id).toBeDefined();
});
```

**The Request-Response Pattern for APIs:**

For API tests, a useful extension is to think in terms of requests and expected responses:

```javascript
const testCases = [
  {
    name: 'valid user creation',
    request: {
      method: 'POST',
      path: '/users',
      body: { name: 'John', email: 'john@test.com' }
    },
    expected: {
      status: 201,
      body: { id: expect.any(Number), name: 'John' }
    }
  },
  {
    name: 'invalid email',
    request: {
      method: 'POST',
      path: '/users',
      body: { name: 'John', email: 'invalid' }
    },
    expected: {
      status: 400,
      body: { error: 'Invalid email format' }
    }
  }
];

testCases.forEach(({ name, request, expected }) => {
  test(name, async () => {
    const response = await api(request);
    expect(response.status).toBe(expected.status);
    expect(response.data).toMatchObject(expected.body);
  });
});
```

**Client Abstraction Pattern:**

Don't call axios or fetch directly in your tests. Create a client abstraction:

```javascript
// api-client.js
class ApiClient {
  constructor(baseURL, token) {
    this.client = axios.create({
      baseURL,
      headers: { Authorization: `Bearer ${token}` }
    });
  }

  async getUsers(params = {}) {
    return this.client.get('/users', { params });
  }

  async getUser(id) {
    return this.client.get(`/users/${id}`);
  }

  async createUser(userData) {
    return this.client.post('/users', userData);
  }

  async updateUser(id, userData) {
    return this.client.patch(`/users/${id}`, userData);
  }

  async deleteUser(id) {
    return this.client.delete(`/users/${id}`);
  }
}

// In tests
const api = new ApiClient('https://api.example.com', 'test-token');
const response = await api.createUser({ name: 'John' });
```

**The Page Object Model, Adapted for APIs:**

UI testers use Page Objects to encapsulate page interactions. For APIs, we can use a similar pattern with endpoint objects:

```javascript
// endpoints/users.js
class UsersEndpoint {
  constructor(client) {
    this.client = client;
    this.basePath = '/users';
  }

  async list(query = {}) {
    return this.client.get(this.basePath, { params: query });
  }

  async get(id) {
    return this.client.get(`${this.basePath}/${id}`);
  }

  async create(data) {
    return this.client.post(this.basePath, data);
  }

  async update(id, data) {
    return this.client.patch(`${this.basePath}/${id}`, data);
  }

  async delete(id) {
    return this.client.delete(`${this.basePath}/${id}`);
  }

  // Business-specific operations
  async activate(id) {
    return this.client.post(`${this.basePath}/${id}/activate`);
  }

  async deactivate(id) {
    return this.client.post(`${this.basePath}/${id}/deactivate`);
  }
}

// endpoints/orders.js
class OrdersEndpoint {
  constructor(client) {
    this.client = client;
    this.basePath = '/orders';
  }

  async create(orderData) {
    return this.client.post(this.basePath, orderData);
  }

  async get(id) {
    return this.client.get(`${this.basePath}/${id}`);
  }

  async cancel(id) {
    return this.client.post(`${this.basePath}/${id}/cancel`);
  }
}

// Using the endpoints
const users = new UsersEndpoint(api);
const orders = new OrdersEndpoint(api);

const newUser = await users.create({ name: 'John' });
const userOrders = await orders.list({ userId: newUser.data.id });
```

**Helper Functions for Common Operations:**

Create helpers for repeated patterns:

```javascript
// helpers/auth.js
async function getAuthToken(credentials) {
  const response = await axios.post('https://api.example.com/login', credentials);
  return response.data.token;
}

async function withAdminPrivileges(testFn) {
  const adminToken = await getAuthToken({ username: 'admin', password: 'admin123' });
  const adminClient = new ApiClient('https://api.example.com', adminToken);
  return testFn(adminClient);
}

// helpers/cleanup.js
async function withTestUser(testFn) {
  const user = await createTestUser();
  try {
    await testFn(user);
  } finally {
    await deleteTestUser(user.id);
  }
}
```

**Key Insight:** The goal is to hide complexity. Your tests should read like specifications, not implementation details. If a non-technical person can understand your tests, you're doing it right.

Test data is often the hardest part of test automation. Tests need data to operate on, but that data can be fragile, shared, or hard to create.

**The Test Data Problem:**

Consider what happens when multiple tests run against the same system:

- Test A creates a user with email "test@example.com"
- Test B also tries to create a user with the same email → fails
- Test A deletes its user, but Test C needs that user → fails
- Tests run in different orders on different days → inconsistent results

This is the test data problem, and it needs a solution.

**Test Data Strategies:**

| Strategy | Description | Best For |
|----------|-------------|----------|
| **Fresh per test** | Create new data for each test | Tests that don't conflict |
| **Seeded database** | Pre-populate known state | Tests that need complex setup |
| **Isolated schemas** | Each test gets its own database | Parallel execution |
| **Transactional rollback** | Run in transaction, roll back | Database tests |
| **Mocking** | Don't use real database at all | Unit tests |
| **Test containers** | Docker containers per test | Integration tests |

**Fresh Data Per Test:**

This is the simplest approach—each test creates what it needs and cleans up after itself.

```javascript
test('should create and retrieve a user', async () => {
  // Create test data
  const email = `test-${Date.now()}@example.com`;

  // Run test
  const createRes = await api.post('/users', {
    name: 'Test User',
    email: email
  });

  const getRes = await api.get(`/users/${createRes.data.id}`);

  // Assert
  expect(getRes.data.email).toBe(email);

  // Cleanup
  await api.delete(`/users/${createRes.data.id}`);
});
```

**Factories for Test Data:**

Create factories to generate consistent test data:

```javascript
// factories/user-factory.js
import { faker } from '@faker-js/faker';

class UserFactory {
  static create(overrides = {}) {
    return {
      name: faker.person.fullName(),
      email: faker.internet.email(),
      age: faker.number.int({ min: 18, max: 100 }),
      preferences: {
        theme: faker.helpers.arrayElement(['light', 'dark']),
        notifications: faker.datatype.boolean()
      },
      ...overrides
    };
  }

  static createAdmin(overrides = {}) {
    return this.create({
      role: 'admin',
      permissions: ['read', 'write', 'delete'],
      ...overrides
    });
  }

  static createWithEmail(email, overrides = {}) {
    return this.create({ email, ...overrides });
  }

  static createMany(count, overrides = {}) {
    return Array.from({ length: count }, () => this.create(overrides));
  }
}

// In tests
const userData = UserFactory.create();
const adminData = UserFactory.createAdmin();
const specificUser = UserFactory.createWithEmail('fixed@example.com', { age: 25 });
```

**Setup and Teardown Patterns:**

Use your test framework's hooks to manage data:

```javascript
describe('User API', () => {
  let testUser;

  beforeAll(async () => {
    // Run once before all tests
    await resetDatabase();
  });

  beforeEach(async () => {
    // Run before each test
    testUser = await createTestUser();
  });

  afterEach(async () => {
    // Run after each test
    await deleteTestUser(testUser.id);
  });

  test('should get user by id', async () => {
    const response = await api.get(`/users/${testUser.id}`);
    expect(response.status).toBe(200);
  });

  test('should update user', async () => {
    const response = await api.patch(`/users/${testUser.id}`, {
      name: 'Updated Name'
    });
    expect(response.data.name).toBe('Updated Name');
  });
});
```

**Test Data Builders (Advanced Pattern):**

For complex objects, builders provide more flexibility than factories:

```javascript
// builders/order-builder.js
class OrderBuilder {
  constructor() {
    this.order = {
      userId: null,
      items: [],
      shippingAddress: {},
      paymentMethod: 'card',
      status: 'pending'
    };
  }

  forUser(userId) {
    this.order.userId = userId;
    return this;
  }

  addItem(productId, quantity = 1) {
    this.order.items.push({ productId, quantity });
    return this;
  }

  withShipping(address) {
    this.order.shippingAddress = address;
    return this;
  }

  withPayment(method) {
    this.order.paymentMethod = method;
    return this;
  }

  withStatus(status) {
    this.order.status = status;
    return this;
  }

  build() {
    if (!this.order.userId) throw new Error('User ID is required');
    if (this.order.items.length === 0) throw new Error('At least one item required');

    return { ...this.order };
  }
}

// Usage
const order = new OrderBuilder()
  .forUser(123)
  .addItem(456, 2)
  .addItem(789, 1)
  .withShipping({ street: '123 Main St', city: 'Boston' })
  .withPayment('paypal')
  .build();
```

**Database Seeding for Complex Scenarios:**

Sometimes you need complex data relationships. Seed your database with known states:

```javascript
// seeds/ecommerce-seed.js
async function seedEcommerceDatabase() {
  // Create categories
  const electronics = await db.categories.create({ name: 'Electronics' });
  const books = await db.categories.create({ name: 'Books' });

  // Create products
  const laptop = await db.products.create({
    name: 'Laptop',
    price: 999.99,
    categoryId: electronics.id,
    stock: 10
  });

  const phone = await db.products.create({
    name: 'Phone',
    price: 499.99,
    categoryId: electronics.id,
    stock: 20
  });

  const book = await db.products.create({
    name: 'Testing Book',
    price: 29.99,
    categoryId: books.id,
    stock: 100
  });

  // Create users with orders
  const user1 = await db.users.create({
    name: 'Test User 1',
    email: 'user1@test.com'
  });

  const order1 = await db.orders.create({
    userId: user1.id,
    total: 1029.98,
    status: 'completed'
  });

  await db.orderItems.create({
    orderId: order1.id,
    productId: laptop.id,
    quantity: 1,
    price: laptop.price
  });

  await db.orderItems.create({
    orderId: order1.id,
    productId: book.id,
    quantity: 1,
    price: book.price
  });

  return {
    users: [user1],
    products: [laptop, phone, book],
    orders: [order1]
  };
}

// In tests
beforeAll(async () => {
  testData = await seedEcommerceDatabase();
});

test('should get user order history', async () => {
  const response = await api.get(`/users/${testData.users[0].id}/orders`);
  expect(response.data.length).toBe(1);
  expect(response.data[0].total).toBe(1029.98);
});
```

**Key Insight:** Your test data strategy determines how reliable your tests are. Invest time in getting it right, and your tests will thank you with years of reliable service.

Authentication adds complexity to API tests. You need to handle tokens, sessions, and different user roles without making tests brittle or slow.

**The Authentication Challenge:**

Most APIs require authentication. This means your tests need to:
- Obtain valid tokens before running
- Handle token expiration
- Test with different user roles
- Sometimes test unauthenticated scenarios

**Centralized Auth Management:**

The key is to centralize authentication logic so tests don't have to worry about it:

```javascript
// auth-manager.js
class AuthManager {
  constructor() {
    this.tokens = new Map();
    this.tokenExpiry = new Map();
  }

  async getToken(role = 'user') {
    // Return cached token if still valid
    if (this.tokens.has(role)) {
      const expiry = this.tokenExpiry.get(role);
      if (expiry > Date.now()) {
        return this.tokens.get(role);
      }
    }

    // Get new token
    const credentials = this.getCredentials(role);
    const token = await this.fetchToken(credentials);

    // Cache it
    this.tokens.set(role, token);
    this.tokenExpiry.set(role, Date.now() + 55 * 60 * 1000); // 55 minutes

    return token;
  }

  getCredentials(role) {
    const credentials = {
      admin: { username: 'admin@test.com', password: 'admin123' },
      user: { username: 'user@test.com', password: 'user123' },
      readonly: { username: 'readonly@test.com', password: 'read123' }
    };
    return credentials[role];
  }

  async fetchToken(credentials) {
    const response = await axios.post('https://api.example.com/login', credentials);
    return response.data.token;
  }
}

// Create authenticated client
async function createClient(role = 'user') {
  const token = await authManager.getToken(role);
  return axios.create({
    baseURL: 'https://api.example.com',
    headers: { Authorization: `Bearer ${token}` }
  });
}
```

**Test Fixtures with Authentication:**

Use fixtures to provide authenticated clients to your tests:

```javascript
// fixtures.js
const authManager = new AuthManager();

beforeAll(async () => {
  // Pre-warm tokens
  await Promise.all([
    authManager.getToken('admin'),
    authManager.getToken('user'),
    authManager.getToken('readonly')
  ]);
});

async function withUser(role, testFn) {
  const client = await createClient(role);
  return testFn(client);
}

// In tests
test('admin can delete users', async () => {
  await withUser('admin', async (adminClient) => {
    const user = await createTestUser();
    const response = await adminClient.delete(`/users/${user.id}`);
    expect(response.status).toBe(204);
  });
});

test('regular user cannot delete users', async () => {
  await withUser('user', async (userClient) => {
    const user = await createTestUser();
    try {
      await userClient.delete(`/users/${user.id}`);
      throw new Error('Should have failed');
    } catch (error) {
      expect(error.response.status).toBe(403);
    }
  });
});
```

**Testing Unauthenticated Scenarios:**

Some endpoints should work without authentication. Test those too:

```javascript
test('public endpoint returns 200 without auth', async () => {
  const response = await axios.get('https://api.example.com/public/health');
  expect(response.status).toBe(200);
});

test('protected endpoint returns 401 without auth', async () => {
  try {
    await axios.get('https://api.example.com/users/me');
    throw new Error('Should have failed');
  } catch (error) {
    expect(error.response.status).toBe(401);
  }
});
```

**Handling Token Expiration:**

Long test suites may encounter token expiration. Handle it gracefully:

```javascript
class ResilientClient {
  constructor(baseURL, authManager, role) {
    this.baseURL = baseURL;
    this.authManager = authManager;
    this.role = role;
  }

  async request(config) {
    try {
      const token = await this.authManager.getToken(this.role);
      const response = await axios({
        ...config,
        baseURL: this.baseURL,
        headers: { ...config.headers, Authorization: `Bearer ${token}` }
      });
      return response;
    } catch (error) {
      // If token expired, refresh and retry once
      if (error.response?.status === 401) {
        this.authManager.tokens.delete(this.role); // Force refresh
        const token = await this.authManager.getToken(this.role);
        return axios({
          ...config,
          baseURL: this.baseURL,
          headers: { ...config.headers, Authorization: `Bearer ${token}` }
        });
      }
      throw error;
    }
  }
}
```

**Key Insight:** Centralize authentication logic. Your tests should focus on what they're testing, not on how to get a token.

Assertions are where your test proves or disproves correctness. Good assertions make tests reliable and failures easy to diagnose.

**The Art of the Assertion:**

A good assertion:
- Checks one thing (or a logical group)
- Has a clear failure message
- Is specific enough to catch bugs
- Is flexible enough to avoid flakiness

**Types of Assertions:**

```javascript
// Exact equality - for values that shouldn't change
expect(response.status).toBe(200);
expect(response.data.id).toBe(123);

// Partial matching - ignore fields you don't care about
expect(response.data).toMatchObject({
  name: 'John',
  email: 'john@example.com'
});
// id, timestamps, etc. can be anything

// Pattern matching - for dynamic data
expect(response.data.email).toMatch(/^[^@]+@[^@]+\.[^@]+$/);
expect(response.data.createdAt).toMatch(/^\d{4}-\d{2}-\d{2}T/);

// Type checking
expect(typeof response.data.id).toBe('number');
expect(Array.isArray(response.data.items)).toBe(true);

// Length/size assertions
expect(response.data.items.length).toBeGreaterThan(0);
expect(response.data.items.length).toBeLessThanOrEqual(100);

// Presence/absence
expect(response.data).toHaveProperty('id');
expect(response.data).not.toHaveProperty('password');

// Nested properties
expect(response.data.user.preferences.theme).toBe('dark');
```

**Custom Matchers for APIs:**

Create custom matchers for common API patterns:

```javascript
// custom-matchers.js
expect.extend({
  toBeValidUser(received) {
    const pass = (
      received.id &&
      typeof received.id === 'number' &&
      received.name &&
      typeof received.name === 'string' &&
      received.email &&
      received.email.includes('@')
    );

    return {
      pass,
      message: () => pass
        ? 'Expected user not to be valid'
        : 'Expected user to have id, name, and valid email'
    };
  },

  toBeValidOrder(received) {
    const pass = (
      received.id &&
      received.total &&
      typeof received.total === 'number' &&
      received.total > 0 &&
      Array.isArray(received.items)
    );

    return {
      pass,
      message: () => pass
        ? 'Expected order not to be valid'
        : 'Expected order to have id, positive total, and items array'
    };
  },

  toHaveError(received, expectedCode) {
    const pass = (
      received.error &&
      received.code === expectedCode
    );

    return {
      pass,
      message: () => pass
        ? `Expected not to have error ${expectedCode}`
        : `Expected error code ${expectedCode}, got ${received.code}`
    };
  }
});

// Usage
expect(user).toBeValidUser();
expect(order).toBeValidOrder();
expect(errorResponse).toHaveError('USER_NOT_FOUND');
```

**Soft Assertions for Multiple Checks:**

Sometimes you want to check multiple things and see all failures at once:

```javascript
// Using a soft assertions library or custom implementation
class SoftAssert {
  constructor() {
    this.errors = [];
  }

  check(condition, message) {
    if (!condition) {
      this.errors.push(message);
    }
  }

  assertAll() {
    if (this.errors.length > 0) {
      throw new Error('Soft assertions failed:\n' + this.errors.join('\n'));
    }
  }
}

// Usage
test('user object has all required fields', () => {
  const soft = new SoftAssert();

  soft.check(user.id, 'id is missing');
  soft.check(user.name, 'name is missing');
  soft.check(user.email, 'email is missing');
  soft.check(user.email.includes('@'), 'email is invalid');
  soft.check(user.age >= 18, 'age must be at least 18');

  soft.assertAll();
});
```

**Assertions for Error Responses:**

Error responses deserve special attention:

```javascript
test('should return validation errors', async () => {
  try {
    await api.post('/users', {});
    throw new Error('Should have failed');
  } catch (error) {
    expect(error.response.status).toBe(400);
    expect(error.response.data).toMatchObject({
      error: 'Validation failed',
      details: {
        name: expect.stringContaining('required'),
        email: expect.stringContaining('required')
      }
    });
  }
});
```

**Avoiding Common Assertion Pitfalls:**

1. **Don't test exact timestamps** - They'll never match
2. **Don't test auto-generated IDs** - They change every run
3. **Don't test order unless it matters** - Arrays might come back in any order
4. **Don't test everything** - Focus on what matters for the test
5. **Do test error messages** - They're part of your API contract

```javascript
// Bad - brittle
expect(response.data.createdAt).toBe('2025-01-01T00:00:00Z');

// Good - pattern matching
expect(response.data.createdAt).toMatch(/^\d{4}-\d{2}-\d{2}T/);

// Bad - order dependent
expect(response.data.items[0].id).toBe(1);

// Good - order independent
expect(response.data.items.map(i => i.id)).toContain(1);
```

**Key Insight:** Assertions are the voice of your tests. Make them speak clearly about what matters and what doesn't.

How you organize and name your tests determines how easy they are to maintain, debug, and understand.

**The Importance of Test Names:**

A test name should tell a story. When a test fails, the name should give you a good idea of what's broken before you even look at the code.

```javascript
// Bad - what does this test?
test('users', () => { ... });
test('test1', () => { ... });
test('should work', () => { ... });

// Better - describes the scenario
test('should create a new user with valid data', () => { ... });
test('should return 400 when email is invalid', () => { ... });
test('should prevent duplicate email registration', () => { ... });

// Best - follows a pattern
test('POST /users - with valid data - creates user and returns 201', () => { ... });
test('POST /users - with missing name - returns 400 validation error', () => { ... });
test('POST /users - with existing email - returns 409 conflict', () => { ... });
```

**Organizing by Endpoint:**

A common and effective pattern is to organize tests by endpoint:

```
tests/
├── users.test.js           # All tests for /users
├── products.test.js        # All tests for /products
├── orders.test.js          # All tests for /orders
└── auth.test.js            # All tests for authentication
```

Within each file, group related tests:

```javascript
describe('Users API', () => {
  describe('GET /users', () => {
    test('returns list of users', () => { ... });
    test('supports pagination', () => { ... });
    test('filters by role', () => { ... });
  });

  describe('GET /users/:id', () => {
    test('returns user by id', () => { ... });
    test('returns 404 for non-existent user', () => { ... });
  });

  describe('POST /users', () => {
    test('creates user with valid data', () => { ... });
    test('returns 400 with invalid email', () => { ... });
    test('returns 409 for duplicate email', () => { ... });
  });
});
```

**Organizing by Feature:**

For larger APIs, organizing by feature can be more maintainable:

```
tests/
├── user-management/
│   ├── registration.test.js
│   ├── profile.test.js
│   ├── authentication.test.js
│   └── password-reset.test.js
├── catalog/
│   ├── products.test.js
│   ├── categories.test.js
│   └── search.test.js
└── checkout/
    ├── cart.test.js
    ├── orders.test.js
    └── payments.test.js
```

**Tagging Tests for Selective Runs:**

Use tags to run subsets of tests:

```javascript
// Run only smoke tests before deployment
test('health check endpoint', () => { ... }).tags('smoke');
test('database connectivity', () => { ... }).tags('smoke');

// Run regression tests nightly
test('complex order flow', () => { ... }).tags('regression');
test('payment processing', () => { ... }).tags('regression', 'slow');

// Run security tests separately
test('SQL injection prevention', () => { ... }).tags('security');
test('JWT validation', () => { ... }).tags('security');

// In CI
# Run smoke tests on every PR
npm test -- --tags=smoke

# Run full suite nightly
npm test
```

**Test Data Organization:**

Keep test data organized and reusable:

```
tests/
├── fixtures/
│   ├── users.json          # Static user data
│   ├── products.json       # Static product data
│   └── error-responses.json # Expected error formats
├── factories/
│   ├── user-factory.js     # Dynamic user generation
│   └── order-factory.js    # Dynamic order generation
└── seeds/
    ├── basic-seed.js       # Basic database seed
    └── complex-seed.js     # Complex scenario seed
```

**The README File:**

Every test suite needs a README explaining:

- How to install dependencies
- How to run tests (all, by tag, by file)
- How to interpret results
- How to add new tests
- What the test data strategy is
- Who to contact for help

**Key Insight:** Organization is communication. Your test structure should tell new team members how the system works and where to add new tests.

Tests that aren't automated aren't really tests—they're just scripts. True automation means tests run automatically as part of your development pipeline.

**The CI/CD Pipeline:**

```
┌──────────┐    ┌──────────┐    ┌──────────┐    ┌──────────┐
│  Commit  │───▶│   Build  │───▶│   Test   │───▶│  Deploy  │
└──────────┘    └──────────┘    └──────────┘    └──────────┘
                                      │
                                      ▼
                               ┌──────────┐
                               │  Report  │
                               └──────────┘
```

**What to Run When:**

Different tests have different costs and should run at different times:

| Stage | Tests | Frequency |
|-------|-------|-----------|
| **Pre-commit** | Linting, syntax, fast unit tests | Every commit |
| **PR** | All unit tests, critical API tests | Every PR |
| **Merge to main** | Full API test suite | Every merge |
| **Nightly** | Long-running tests, performance | Daily |
| **Pre-release** | Full regression, security | Before release |

**GitHub Actions Example:**

```yaml
# .github/workflows/api-tests.yml
name: API Tests

on:
  push:
    branches: [ main, develop ]
  pull_request:
    branches: [ main ]
  schedule:
    - cron: '0 2 * * *'  # Run at 2 AM daily

jobs:
  test:
    runs-on: ubuntu-latest

    services:
      # Start dependent services
      postgres:
        image: postgres:14
        env:
          POSTGRES_PASSWORD: testpass
        ports:
          - 5432:5432
