public class AuthSpecs {

    public static RequestSpecification withBasicAuth() {
        return new RequestSpecBuilder()
            .setAuth(basic(Config.getUser(), Config.getPassword()))
            .build();
    }

    public static RequestSpecification withOAuth2() {
