    public static RequestSpecification withJwt() {
        return new RequestSpecBuilder()
            .addHeader("Authorization", "Bearer " + JwtManager.generateToken())
            .build();
    }

    // Dynamic based on role
    public static RequestSpecification forRole(UserRole role) {
        switch(role) {
            case ADMIN:
                return new RequestSpecBuilder()
                    .setAuth(oauth2(TokenManager.getAdminToken()))
                    .build();
            case USER:
                return new RequestSpecBuilder()
                    .setAuth(oauth2(TokenManager.getUserToken()))
                    .build();
            case GUEST:
                return new RequestSpecBuilder().build(); // No auth
            default:
                throw new IllegalArgumentException("Unknown role: " + role);
        }
    }
}
