```java
public class OAuth2Flows {

    // Client Credentials Flow
    @Test
    public void clientCredentialsFlow() {
        // 1. Get token
        TokenResponse token = given()
            .auth().preemptive().basic("client-id", "client-secret")
            .contentType(ContentType.URLENC)
            .formParam("grant_type", "client_credentials")
            .formParam("scope", "read write")
        .when()
            .post("https://auth.example.com/token")
        .then()
            .statusCode(200)
            .extract()
            .as(TokenResponse.class);

        // 2. Use token for API call
        given()
            .auth().oauth2(token.getAccessToken())
        .when()
            .get("https://api.example.com/resource")
        .then()
            .statusCode(200);
    }

    // Password Flow
    @Test
    public void passwordFlow() {
        TokenResponse token = given()
            .auth().preemptive().basic("client-id", "client-secret")
            .contentType(ContentType.URLENC)
            .formParam("grant_type", "password")
            .formParam("username", "user@example.com")
            .formParam("password", "password123")
        .when()
            .post("https://auth.example.com/token")
        .then()
            .statusCode(200)
            .extract()
            .as(TokenResponse.class);

        // Use token...
    }

    // Refresh Token Flow
    @Test
    public void refreshTokenFlow() {
        TokenResponse token = given()
            .auth().preemptive().basic("client-id", "client-secret")
            .contentType(ContentType.URLENC)
            .formParam("grant_type", "refresh_token")
            .formParam("refresh_token", storedRefreshToken)
        .when()
            .post("https://auth.example.com/token")
        .then()
            .statusCode(200)
            .extract()
            .as(TokenResponse.class);
    }
}
