**2. Base API Client (utils/api_client.py):**

```python
import requests
import logging
import time
from typing import Optional, Dict, Any, Union
from requests.exceptions import RequestException, Timeout, ConnectionError
from config.settings import settings

logger = logging.getLogger(__name__)

class APIError(Exception):
    """Custom API exception"""
    def __init__(self, message: str, response: Optional[requests.Response] = None):
        self.message = message
        self.response = response
        self.status_code = response.status_code if response else None
        super().__init__(self.message)

class APIClient:
    """Base API client with retry logic and error handling"""

    def __init__(self, base_url: str = settings.BASE_URL, api_key: Optional[str] = None):
        self.base_url = base_url.rstrip('/')
        self.session = requests.Session()

        # Configure retry adapter
        self.session.mount('https://', requests.adapters.HTTPAdapter(
            max_retries=settings.MAX_RETRIES,
            pool_connections=20,
            pool_maxsize=20
        ))

        # Default headers
        self.session.headers.update({
            'User-Agent': 'APITestFramework/1.0',
            'Accept': 'application/json',
            'Content-Type': 'application/json'
        })

        if api_key:
            self.session.headers.update({'X-API-Key': api_key})

        self.auth_token = None

    def set_auth_token(self, token: str):
        """Set Bearer token for authentication"""
        self.auth_token = token
        self.session.headers.update({'Authorization': f'Bearer {token}'})

    def _request(self, method: str, endpoint: str, **kwargs) -> requests.Response:
        """Internal request method with logging and error handling"""
        url = f"{self.base_url}/{endpoint.lstrip('/')}"

        # Set default timeout if not provided
        if 'timeout' not in kwargs:
            kwargs['timeout'] = (settings.CONNECTION_TIMEOUT, settings.READ_TIMEOUT)

        # Log request
        logger.info(f"{method} {url}")
        if 'json' in kwargs:
            logger.debug(f"Request body: {kwargs['json']}")

        start_time = time.time()

        try:
            response = self.session.request(method, url, **kwargs)
            elapsed = time.time() - start_time

            # Log response
            logger.info(f"Response: {response.status_code} ({elapsed:.2f}s)")

            # Try to log response body for debugging
            if response.content:
                try:
                    logger.debug(f"Response body: {response.json()}")
                except:
                    logger.debug(f"Response body (text): {response.text[:200]}")

            return response

        except Timeout as e:
            logger.error(f"Timeout after {time.time() - start_time:.2f}s")
            raise APIError(f"Request timeout: {str(e)}")
        except ConnectionError as e:
            logger.error(f"Connection error: {str(e)}")
            raise APIError(f"Connection error: {str(e)}")
        except RequestException as e:
            logger.error(f"Request failed: {str(e)}")
            raise APIError(f"Request failed: {str(e)}")

    def get(self, endpoint: str, **kwargs) -> requests.Response:
        """GET request"""
        return self._request('GET', endpoint, **kwargs)

    def post(self, endpoint: str, **kwargs) -> requests.Response:
        """POST request"""
        return self._request('POST', endpoint, **kwargs)

    def put(self, endpoint: str, **kwargs) -> requests.Response:
        """PUT request"""
        return self._request('PUT', endpoint, **kwargs)

    def patch(self, endpoint: str, **kwargs) -> requests.Response:
        """PATCH request"""
        return self._request('PATCH', endpoint, **kwargs)

    def delete(self, endpoint: str, **kwargs) -> requests.Response:
        """DELETE request"""
        return self._request('DELETE', endpoint, **kwargs)

    def head(self, endpoint: str, **kwargs) -> requests.Response:
        """HEAD request"""
        return self._request('HEAD', endpoint, **kwargs)

    def options(self, endpoint: str, **kwargs) -> requests.Response:
        """OPTIONS request"""
        return self._request('OPTIONS', endpoint, **kwargs)
```

**3. Custom Assertions (utils/assertions.py):**

```python
import json
import jsonschema
from jsonschema import validate, ValidationError
import pytest
from typing import Dict, Any, List, Optional
import re

class Assertions:
    """Custom assertion methods for API testing"""

    @staticmethod
    def assert_status_code(response, expected_status: int, message: str = ""):
        """Assert response status code"""
        assert response.status_code == expected_status, (
            f"{message} Expected {expected_status}, got {response.status_code}. "
            f"Response: {response.text[:200]}"
        )

    @staticmethod
    def assert_json_response(response):
        """Assert response is valid JSON"""
        try:
            data = response.json()
            assert isinstance(data, (dict, list))
            return data
        except (ValueError, json.JSONDecodeError) as e:
            pytest.fail(f"Response is not valid JSON: {e}\nResponse: {response.text[:200]}")

    @staticmethod
    def assert_schema(data: Any, schema: Dict):
        """Validate data against JSON schema"""
        try:
            validate(instance=data, schema=schema)
        except ValidationError as e:
            pytest.fail(f"Schema validation failed: {e.message}\nPath: {'/'.join(str(p) for p in e.path)}")

    @staticmethod
    def assert_required_fields(data: Dict, required_fields: List[str]):
        """Assert that all required fields are present"""
        missing = [field for field in required_fields if field not in data]
        assert not missing, f"Missing required fields: {missing}"

    @staticmethod
    def assert_field_type(data: Dict, field: str, expected_type):
        """Assert field has expected type"""
        assert field in data, f"Field '{field}' not found in response"
        assert isinstance(data[field], expected_type), (
            f"Field '{field}' should be {expected_type.__name__}, "
            f"got {type(data[field]).__name__}"
        )

    @staticmethod
    def assert_field_value(data: Dict, field: str, expected_value):
        """Assert field equals expected value"""
        assert field in data, f"Field '{field}' not found in response"
        assert data[field] == expected_value, (
            f"Field '{field}' expected {expected_value}, got {data[field]}"
        )

    @staticmethod
    def assert_field_not_empty(data: Dict, field: str):
        """Assert field is not empty"""
        assert field in data, f"Field '{field}' not found in response"
        value = data[field]
        assert value is not None and value != "", f"Field '{field}' is empty"

    @staticmethod
    def assert_time_less_than(response, max_ms: int):
        """Assert response time is less than threshold"""
        elapsed_ms = response.elapsed.total_seconds() * 1000
        assert elapsed_ms < max_ms, (
            f"Response time {elapsed_ms:.0f}ms exceeds {max_ms}ms"
        )

    @staticmethod
    def assert_header_exists(response, header_name: str):
        """Assert header exists in response"""
        assert header_name in response.headers, f"Header '{header_name}' not found in response"

    @staticmethod
    def assert_header_value(response, header_name: str, expected_value: str):
        """Assert header has expected value"""
        assert header_name in response.headers, f"Header '{header_name}' not found"
        assert response.headers[header_name] == expected_value, (
            f"Header '{header_name}' expected '{expected_value}', "
            f"got '{response.headers[header_name]}'"
        )

    @staticmethod
    def assert_content_type(response, expected_content_type: str):
        """Assert Content-Type header"""
        content_type = response.headers.get('Content-Type', '')
        assert expected_content_type in content_type, (
            f"Content-Type expected '{expected_content_type}', got '{content_type}'"
        )

    @staticmethod
    def assert_uuid_format(uuid_string: str):
        """Assert string is valid UUID"""
        pattern = r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        assert re.match(pattern, uuid_string, re.I), f"Invalid UUID format: {uuid_string}"

    @staticmethod
    def assert_email_format(email: str):
        """Assert string is valid email"""
        pattern = r'^[^@]+@[^@]+\.[^@]+$'
        assert re.match(pattern, email), f"Invalid email format: {email}"

    @staticmethod
    def assert_datetime_format(dt_string: str, format: str = "iso"):
        """Assert string is valid datetime"""
        from datetime import datetime
        try:
            if format == "iso":
                # Handle ISO format with possible Z
                dt_string = dt_string.replace('Z', '+00:00')
                datetime.fromisoformat(dt_string)
            else:
                datetime.strptime(dt_string, format)
        except ValueError as e:
            pytest.fail(f"Invalid datetime format '{dt_string}': {e}")

    @staticmethod
    def assert_array_length(data: List, expected_length: int):
        """Assert array has expected length"""
        assert isinstance(data, list), "Expected array/list"
        assert len(data) == expected_length, (
            f"Expected array length {expected_length}, got {len(data)}"
        )

    @staticmethod
    def assert_min_array_length(data: List, min_length: int):
        """Assert array has at least min_length items"""
        assert isinstance(data, list), "Expected array/list"
        assert len(data) >= min_length, (
            f"Expected at least {min_length} items, got {len(data)}"
        )

    @staticmethod
    def assert_all_items_match_schema(data: List, schema: Dict):
        """Assert all items in list match schema"""
        assert isinstance(data, list), "Expected array/list"
        for i, item in enumerate(data):
            try:
                validate(instance=item, schema=schema)
            except ValidationError as e:
                pytest.fail(f"Item at index {i} failed validation: {e.message}")

# Create a singleton instance for easy import
assert_that = Assertions()
