            "email": fake.email(),
            "body": fake.paragraph(nb_sentences=2)
        }
        data.update(kwargs)
        return data

    @staticmethod
    def todo_data(user_id: Optional[int] = None, **kwargs) -> Dict[str, Any]:
        """Generate random todo data"""
        data = {
            "userId": user_id or random.randint(1, 10),
            "title": fake.sentence(nb_words=4),
            "completed": random.choice([True, False])
        }
        data.update(kwargs)
        return data

    @staticmethod
    def bulk_users(count: int) -> List[Dict[str, Any]]:
        """Generate multiple users"""
        return [TestDataGenerator.user_data() for _ in range(count)]

    @staticmethod
    def bulk_posts(user_id: int, count: int) -> List[Dict[str, Any]]:
        """Generate multiple posts for a user"""
        return [TestDataGenerator.post_data(user_id) for _ in range(count)]

