@Test
void testParallelWithOptions() {
    Results results = Runner.path("classpath:features")
        .tags("@regression", "~@slow")
        .karateEnv("staging")
        .configDir("classpath:custom-config")
        .outputHtmlReport(true)
        .outputJunitXml(true)
        .parallel(10);

    // Detailed results
    System.out.println("Total scenarios: " + results.getScenarioCount());
    System.out.println("Passed: " + results.getPassCount());
    System.out.println("Failed: " + results.getFailCount());
    System.out.println("Time taken: " + results.getTimeTakenMillis() + "ms");

    // Optionally fail the build if any tests failed
    assertTrue(results.getFailCount() == 0, 
        "Tests failed: " + results.getErrorMessages());
}
