**Dynamic Responses with Inject**

```javascript
// Complex logic using JavaScript injection
{
  "port": 3000,
  "protocol": "http",
  "stubs": [{
    "predicates": [{ "equals": { "path": "/api/data" } }],
    "responses": [{
      "inject": """
        function (request) {
          // Parse query parameters
          const url = new URL(request.url, 'http://localhost');
          const page = parseInt(url.searchParams.get('page') || '1');
          const limit = parseInt(url.searchParams.get('limit') || '10');

          // Generate paginated response
          const start = (page - 1) * limit;
          const items = [];
          for (let i = 0; i < limit; i++) {
            items.push({ 
              id: start + i + 1, 
              name: `Item ${start + i + 1}`,
              random: Math.random()
            });
          }

          // Simulate authentication check
          const auth = request.headers['authorization'];
          if (!auth || !auth.startsWith('Bearer ')) {
            return {
              statusCode: 401,
              body: { error: 'Unauthorized' }
            };
          }

          return {
            statusCode: 200,
            headers: { 
              'Content-Type': 'application/json',
              'X-Page': page,
              'X-Total-Count': 1000
            },
            body: {
              page: page,
              limit: limit,
              items: items,
              total: 1000
            }
          };
        }
      """
    }]
  }]
}
```

**Stateful Behavior**

```javascript
// Stateful mock with counters
{
  "port": 3000,
  "protocol": "http",
  "stubs": [{
    "responses": [{
      "inject": """
        function (request) {
          // Maintain state in closure
          if (!this.counter) this.counter = 0;
          this.counter++;

          const path = request.path;

          if (path === '/increment') {
            return {
              statusCode: 200,
              body: { count: this.counter }
            };
          }
          else if (path === '/decrement') {
            this.counter--;
            return {
              statusCode: 200,
              body: { count: this.counter }
            };
          }
          else {
            return {
              statusCode: 404,
              body: { error: 'Not found' }
            };
          }
        }
      """
    }]
  }]
}
