**Performance Testing Strategy**

```java
public class PerformanceTestStrategy {

    @Test
    public void performanceTestWithMocks() {
        // Use fast mocks to isolate our code's performance
        stubFor(get("/database")
            .willReturn(ok().withFixedDelay(50)));

        long start = System.currentTimeMillis();
        for (int i = 0; i < 1000; i++) {
            myService.process();
        }
        long duration = System.currentTimeMillis() - start;

        // This measures our code + mock delay
        // Subtract mock delay to get our code's performance
        long ourCodeTime = duration - (1000 * 50);
        assertTrue(ourCodeTime < 500, "Our code too slow");
    }

    @Test
    @EnabledInEnvironment("PERF")
    public void endToEndPerformanceTest() {
        // Use real services to measure actual performance
        // Run fewer iterations, monitor carefully
        PerformanceResult result = performanceTestRunner
            .withThreads(10)
            .withDuration(Duration.ofMinutes(5))
            .withRealServices(true)
            .run();

        assertTrue(result.getP95ResponseTime() < 1000);
    }
}
