```java
public class MockMonitor {

    private static final Map<String, Integer> usageCount = new ConcurrentHashMap<>();

    public static void trackUsage(String mockName) {
        usageCount.merge(mockName, 1, Integer::sum);
    }

    @Scheduled(cron = "0 0 * * *")
    public void reportUsage() {
        usageCount.forEach((mock, count) -> {
            if (count == 0) {
                logger.warn("Mock {} was never used", mock);
            } else if (count > 1000) {
                logger.info("Mock {} used {} times", mock, count);
            }
        });

        // Identify unused mocks for cleanup
        usageCount.clear();
    }
}
