**Sample Mocha/Chai/Supertest Test**

```javascript
const request = require('supertest');
const { expect } = require('chai');
const app = require('../app'); // Your Express app

describe('User API', function() {
  let authToken;

  before(async function() {
    // Setup - runs once before all tests
    const loginRes = await request(app)
      .post('/auth/login')
      .send({ username: 'test', password: 'test' });
    authToken = loginRes.body.token;
  });

  describe('GET /users/:id', function() {
    it('should return user with valid id', async function() {
      const res = await request(app)
        .get('/users/1')
        .set('Authorization', `Bearer ${authToken}`);

      expect(res.status).to.equal(200);
      expect(res.body).to.be.an('object');
      expect(res.body).to.have.property('id', 1);
      expect(res.body).to.have.property('name').that.is.a('string');
      expect(res.body.email).to.match(/^[^@]+@[^@]+\.[^@]+$/);
    });

    it('should return 404 for non-existent user', async function() {
      const res = await request(app)
        .get('/users/999999')
        .set('Authorization', `Bearer ${authToken}`);

      expect(res.status).to.equal(404);
    });
  });

  describe('POST /users', function() {
    it('should create a new user', async function() {
      const newUser = {
        name: 'John Doe',
        email: 'john@example.com',
        password: 'Password123'
      };

      const res = await request(app)
        .post('/users')
        .set('Authorization', `Bearer ${authToken}`)
        .send(newUser);

      expect(res.status).to.equal(201);
      expect(res.body).to.have.property('id');
      expect(res.body.name).to.equal(newUser.name);

      // Verify user was created
      const getRes = await request(app)
        .get(`/users/${res.body.id}`)
        .set('Authorization', `Bearer ${authToken}`);
      expect(getRes.status).to.equal(200);
    });

    it('should validate required fields', async function() {
      const res = await request(app)
        .post('/users')
        .set('Authorization', `Bearer ${authToken}`)
        .send({ name: 'Incomplete' });

      expect(res.status).to.equal(400);
      expect(res.body).to.have.property('errors');
    });
  });
});
```

**Advanced Mocha/Chai Patterns**

```javascript
