const chaiJsonSchema = require('chai-json-schema');
chai.use(chaiJsonSchema);
const { expect } = chai;

const userSchema = {
  type: 'object',
  required: ['id', 'name', 'email'],
  properties: {
    id: { type: 'number' },
    name: { type: 'string' },
    email: { type: 'string', pattern: '^[^@]+@[^@]+\\.[^@]+$' }
  }
};

it('should match schema', async function() {
  const res = await request(app).get('/users/1');
  expect(res.body).to.be.jsonSchema(userSchema);
});

// Parameterized tests
const testCases = [
  { id: 1, expectedName: 'John' },
  { id: 2, expectedName: 'Jane' },
  { id: 3, expectedName: 'Bob' }
];

testCases.forEach(({ id, expectedName }) => {
  it(`should return correct name for user ${id}`, async function() {
    const res = await request(app).get(`/users/${id}`);
    expect(res.body.name).to.equal(expectedName);
  });
});

// Async/await with timeouts
it('should respond within time limit', async function() {
  this.timeout(1000); // Set timeout for this test

  const start = Date.now();
  await request(app).get('/users/1');
  const duration = Date.now() - start;

  expect(duration).to.be.below(500);
});
