Jenkins is the most widely used open-source automation server. Its pipeline-as-code approach (Jenkinsfile) provides powerful, flexible CI/CD capabilities.

**Declarative Pipeline**

```groovy
// Jenkinsfile
pipeline {
    agent any

    tools {
        python 'python3.11'
    }

    environment {
        API_URL = 'http://localhost:5000'
        DATABASE_URL = 'postgresql://test:test@localhost:5432/testdb'
    }

    stages {
        stage('Checkout') {
            steps {
                checkout scm
            }
        }

        stage('Setup') {
            steps {
                sh 'python -m venv venv'
                sh '. venv/bin/activate && pip install -r requirements.txt'
                sh '. venv/bin/activate && pip install -r requirements-dev.txt'
            }
        }

        stage('Unit Tests') {
            steps {
                sh '. venv/bin/activate && pytest tests/unit --junitxml=reports/unit.xml'
            }
            post {
                always {
                    junit 'reports/unit.xml'
                }
            }
        }

        stage('Start Services') {
            steps {
                sh 'docker-compose -f docker-compose.test.yml up -d'
                sh 'sleep 10'  // Wait for services
            }
        }

        stage('API Tests') {
            steps {
                sh '. venv/bin/activate && pytest tests/api --junitxml=reports/api.xml'
            }
            post {
                always {
                    junit 'reports/api.xml'
                }
            }
        }

        stage('Deploy to Staging') {
            when {
                branch 'main'
            }
            steps {
                sh './deploy-staging.sh'
            }
        }

        stage('Smoke Tests') {
            when {
                branch 'main'
            }
            steps {
                sh 'pytest tests/smoke --url https://staging.example.com'
            }
        }
    }

    post {
        always {
            sh 'docker-compose -f docker-compose.test.yml down'
            cleanWs()
        }

        success {
            emailext (
                to: 'team@example.com',
                subject: "Pipeline succeeded: ${env.JOB_NAME} - ${env.BUILD_NUMBER}",
                body: "The pipeline completed successfully. Check ${env.BUILD_URL} for details."
            )
        }

        failure {
            emailext (
                to: 'team@example.com',
                subject: "Pipeline failed: ${env.JOB_NAME} - ${env.BUILD_NUMBER}",
                body: "The pipeline failed. Check ${env.BUILD_URL} for details."
            )
        }
    }
}
```

**Scripted Pipeline (More Flexible)**

```groovy
// Jenkinsfile (Scripted)
node {
    stage('Checkout') {
        checkout scm
    }

    stage('Setup') {
        sh 'python -m venv venv'
        sh '. venv/bin/activate && pip install -r requirements.txt'
    }

    // Parallel execution
    stage('Parallel Tests') {
        parallel(
            unit: {
                stage('Unit Tests') {
                    sh '. venv/bin/activate && pytest tests/unit'
                }
            },
            lint: {
                stage('Linting') {
                    sh '. venv/bin/activate && flake8'
                }
            }
        )
    }

    stage('Integration Tests') {
        // Run with Docker Compose
        sh 'docker-compose -f docker-compose.test.yml up -d'

        try {
            sh '. venv/bin/activate && pytest tests/integration'
        } finally {
            sh 'docker-compose -f docker-compose.test.yml down'
        }
    }

    stage('Deploy') {
        if (env.BRANCH_NAME == 'main') {
            sh './deploy.sh'
        }
    }
}
```

**Shared Libraries for Reusability**

```groovy
// vars/apiTestPipeline.groovy
def call(Map config = [:]) {
    pipeline {
        agent any

        environment {
            API_URL = config.apiUrl ?: 'http://localhost:5000'
            TEST_LEVEL = config.testLevel ?: 'full'
        }

        stages {
            stage('Checkout') {
                steps {
                    checkout scm
                }
            }

            stage('Setup') {
                steps {
                    sh 'pip install -r requirements.txt'
                }
            }

            stage('Unit Tests') {
                when {
                    expression { config.runUnit != false }
                }
                steps {
                    sh 'pytest tests/unit'
                }
            }

            stage('API Tests') {
                when {
                    expression { TEST_LEVEL == 'full' }
                }
                steps {
                    sh 'pytest tests/api'
                }
            }
        }

        post {
            always {
                junit 'reports/*.xml'
            }
        }
    }
}

// Usage in Jenkinsfile
@Library('my-shared-library') _

apiTestPipeline(
    apiUrl: 'https://staging.example.com',
    testLevel: 'smoke',
    runUnit: false
)
