**Complete Newman Pipeline**

```groovy
pipeline {
    agent any

    parameters {
        choice(
            name: 'ENVIRONMENT',
            choices: ['dev', 'staging', 'production'],
            description: 'Environment to test'
        )
        string(
            name: 'COLLECTION_URL',
            defaultValue: 'https://api.postman.com/collections/123456',
            description: 'Postman collection URL'
        )
    }

    environment {
        // Load environment-specific variables
        POSTMAN_API_KEY = credentials('postman-api-key')
    }

    stages {
        stage('Checkout') {
            steps {
                checkout scm
                // Or download collection if not in repo
                sh "curl -H 'X-Api-Key: ${POSTMAN_API_KEY}' -o collection.json ${params.COLLECTION_URL}"
            }
        }

        stage('Setup Newman') {
            steps {
                sh 'npm install -g newman newman-reporter-html newman-reporter-junit'
            }
        }

        stage('Run API Tests') {
            steps {
                sh """
                    newman run collection.json \
                      --environment environments/${params.ENVIRONMENT}.json \
                      --globals globals.json \
                      --reporters cli,json,junit \
                      --reporter-json-export reports/results.json \
                      --reporter-junit-export reports/junit.xml \
                      --reporter-html-export reports/report.html \
                      --bail
                """
            }
        }

        stage('Analyze Results') {
            steps {
                script {
                    def results = readJSON file: 'reports/results.json'
                    def total = results.run.stats.tests.total
                    def failed = results.run.stats.tests.failed

                    echo "Total tests: ${total}"
                    echo "Failed tests: ${failed}"

                    if (failed > 0) {
                        unstable("${failed} tests failed")
                    }
                }
            }
        }
    }

    post {
        always {
            // Publish JUnit results
            junit 'reports/junit.xml'

            // Publish HTML report
            publishHTML([
                reportDir: 'reports',
                reportFiles: 'report.html',
                reportName: 'Postman Test Report',
                keepAll: true
            ])

            // Archive raw results
            archiveArtifacts artifacts: 'reports/*.json', fingerprint: true
        }
    }
}
```

