**Dynamic Parallel Stages**

```groovy
stage('Dynamic Parallel Tests') {
    steps {
        script {
            // Get list of test directories
            def suites = findFiles(glob: 'tests/*/')
            def parallelStages = [:]

            suites.each { suite ->
                def suiteName = suite.path.replace('tests/', '').replace('/', '')
                parallelStages[suiteName] = {
                    stage(suiteName) {
                        sh "pytest ${suite.path} --junitxml=reports/${suiteName}.xml"
                    }
                }
            }

            parallel parallelStages
        }
    }
    post {
        always {
            junit 'reports/*.xml'
        }
    }
}
```

**Load-Balanced Parallel Execution**

```groovy
stage('Load-Balanced Tests') {
    steps {
        script {
            // Get all test files with their historical durations
            def testTimes = readJSON file: 'test-times.json'
            def totalTests = testTimes.size()
            def numWorkers = 4
            def workerLoad = [0, 0, 0, 0]
            def workerTests = [[], [], [], []]

            // Sort tests by duration (longest first)
            def sortedTests = testTimes.sort { -it.value }

            // Assign tests to workers (greedy algorithm)
            sortedTests.each { test ->
                def minWorker = workerLoad.indexOf(workerLoad.min())
                workerTests[minWorker].add(test.key)
                workerLoad[minWorker] += test.value
            }

            // Create parallel stages
            def parallelStages = [:]
            (0..<numWorkers).each { i ->
                def workerId = i
                parallelStages["Worker ${workerId+1}"] = {
                    stage("Worker ${workerId+1}") {
                        writeFile file: "tests-worker-${workerId}.txt", text: workerTests[workerId].join('\n')
                        sh "pytest @tests-worker-${workerId}.txt --junitxml=reports/worker-${workerId}.xml"
                    }
                }
            }

            parallel parallelStages
        }
    }
}
```

