Moving from working pipelines to production-ready ones requires attention to security, maintainability, and reliability.

**Pipeline Structure Best Practices**

```groovy
// Jenkinsfile - Well-structured pipeline
pipeline {
    // 1. Agent definition
    agent { docker { image 'python:3.11' } }

    // 2. Tools configuration
    tools {
        maven 'Maven 3.8'
    }

    // 3. Environment variables
    environment {
        // Credentials
        API_KEY = credentials('api-key')

        // Configuration
        TEST_ENV = 'staging'

        // Computed values
        BUILD_TIMESTAMP = sh(script: 'date +%Y%m%d-%H%M%S', returnStdout: true).trim()
    }

    // 4. Pipeline options
    options {
        timestamps()  // Add timestamps to console
        timeout(time: 1, unit: 'HOURS')
        buildDiscarder(logRotator(numToKeepStr: '20'))
        ansiColor('xterm')
        disableConcurrentBuilds()
    }

    // 5. Parameters for manual builds
    parameters {
        string(name: 'BRANCH', defaultValue: 'main', description: 'Branch to test')
        choice(name: 'ENVIRONMENT', choices: ['dev', 'staging', 'prod'], description: 'Test environment')
    }

    // 6. Triggers
    triggers {
        pollSCM('H/5 * * * *')
        cron('H 2 * * *')  // Nightly build
    }

    // 7. Stages
    stages {
        stage('Checkout') {
            steps {
                checkout scm
            }
        }

        stage('Build') {
            when {
                expression { params.ENVIRONMENT != 'prod' }
            }
            steps {
                sh 'make build'
            }
        }

        stage('Test') {
            parallel {
                stage('Unit') {
                    steps { sh 'make test-unit' }
                }
                stage('Integration') {
                    steps { sh 'make test-integration' }
                }
            }
        }
    }

    // 8. Post-build actions
    post {
        always {
            junit 'reports/*.xml'
            cleanWs()
        }
        success {
            slackSend(color: 'good', message: "Pipeline succeeded: ${env.JOB_NAME} - ${env.BUILD_NUMBER}")
        }
        failure {
            slackSend(color: 'danger', message: "Pipeline failed: ${env.JOB_NAME} - ${env.BUILD_NUMBER}")
        }
        unstable {
            slackSend(color: 'warning', message: "Pipeline unstable: ${env.JOB_NAME} - ${env.BUILD_NUMBER}")
        }
    }
}
```

