**Error Handling Patterns**

```groovy
// Pattern 1: Try-catch in scripted blocks
stage('Unreliable Tests') {
    steps {
        script {
            try {
                sh 'pytest tests/flaky/'
            } catch (Exception e) {
                echo "Flaky tests failed, but continuing: ${e.message}"
                currentBuild.result = 'UNSTABLE'
            }
        }
    }
}

// Pattern 2: catchError step
stage('Tests with catchError') {
    steps {
        catchError(buildResult: 'UNSTABLE', stageResult: 'FAILURE') {
            sh 'pytest tests/'
        }
    }
}

// Pattern 3: Retry flaky tests
stage('Retry Flaky Tests') {
    steps {
        retry(3) {
            sh 'pytest tests/flaky/'
        }
    }
}

// Pattern 4: Timeout for hanging tests
stage('Timeout Protection') {
    steps {
        timeout(time: 10, unit: 'MINUTES') {
            sh 'pytest tests/performance/'
        }
    }
}
