      user3: createUser(input: {name: "User3", email: "user3@test.com", password: "pass"}) {
        id
      }
    }
  `;

  const result = await graphql(schema, mutation, null, context);

  // GraphQL returns data for successful operations and errors for failures
  expect(result.data.user1).toBeDefined();
  expect(result.data.user2).toBeNull();
  expect(result.data.user3).toBeDefined();
  expect(result.errors).toBeDefined();
  expect(result.errors.length).toBe(1);
  expect(result.errors[0].path).toEqual(['user2']);
});
