Strategies for testing subscription-based functionality in GraphQL APIs.

**Subscription Test Setup**

```javascript
// subscription.test.js
const { execute, subscribe } = require('graphql');
const { schema } = require('./schema');
const { createTestContext } = require('./test-utils');
const { PubSub } = require('graphql-subscriptions');

// Use in-memory PubSub for testing
const pubsub = new PubSub();

describe('GraphQL Subscriptions', () => {
  let context;

  beforeEach(() => {
    context = createTestContext();
    context.pubsub = pubsub;
  });

  afterEach(() => {
    // Clean up all subscriptions
    pubsub.publish('TEST_CLEANUP', {});
  });

  test('should receive subscription events', (done) => {
    const subscription = `
      subscription OnPostCreated {
        postCreated {
          id
          title
          author {
            name
          }
        }
      }
    `;

    // Set up subscription
    subscribe(schema, subscription, null, context)
      .then(async (iterator) => {
        // Expect to receive one event
        const { value, done: iteratorDone } = await iterator.next();

        expect(iteratorDone).toBe(false);
        expect(value.data.postCreated).toBeDefined();
        expect(value.data.postCreated.title).toBe('Test Post');

        done();
      })
      .catch(done);

    // Trigger the event
    setTimeout(() => {
      pubsub.publish('POST_CREATED', {
        postCreated: {
          id: '1',
          title: 'Test Post',
          author: { name: 'Test Author' }
        }
      });
    }, 100);
  });

  test('should handle multiple subscribers', async () => {
    const subscription = `
      subscription OnPostCreated {
        postCreated {
          id
          title
        }
      }
    `;

    // Create multiple subscribers
    const subscriber1 = await subscribe(schema, subscription, null, context);
    const subscriber2 = await subscribe(schema, subscription, null, context);
    const subscriber3 = await subscribe(schema, subscription, null, context);

    // Trigger event
    pubsub.publish('POST_CREATED', {
      postCreated: {
        id: '1',
        title: 'Test Post'
      }
    });

    // Each subscriber should receive the event
    const results = await Promise.all([
      subscriber1.next(),
      subscriber2.next(),
      subscriber3.next()
    ]);

    results.forEach(result => {
      expect(result.value.data.postCreated.title).toBe('Test Post');
    });
  });

  test('should filter subscriptions by arguments', (done) => {
    const subscription = `
      subscription OnPostCreated($authorId: ID!) {
        postCreated(authorId: $authorId) {
          id
          title
          authorId
        }
      }
    `;

    // Subscribe for specific author
    subscribe(schema, subscription, null, context, { authorId: '123' })
      .then(async (iterator) => {
        const { value } = await iterator.next();
        expect(value.data.postCreated.authorId).toBe('123');
        done();
      })
      .catch(done);

    // Trigger events
    setTimeout(() => {
      // This one should be filtered out
      pubsub.publish('POST_CREATED', {
        postCreated: {
          id: '1',
          title: 'Wrong Author',
          authorId: '456'
        }
      });

      // This one should be received
      setTimeout(() => {
        pubsub.publish('POST_CREATED', {
          postCreated: {
            id: '2',
            title: 'Correct Author',
            authorId: '123'
          }
        });
      }, 50);
    }, 50);
  });

  test('should handle subscription errors', async () => {
    const subscription = `
      subscription OnPostCreated {
        postCreated {
          id
          nonExistentField
        }
      }
    `;

    try {
      await subscribe(schema, subscription, null, context);
      fail('Should have thrown an error');
    } catch (error) {
      expect(error.message).toContain('nonExistentField');
    }
  });

  test('should close subscriptions gracefully', async () => {
    const subscription = `
      subscription OnPostCreated {
        postCreated {
          id
        }
      }
    `;

    const iterator = await subscribe(schema, subscription, null, context);

    // Trigger event
    pubsub.publish('POST_CREATED', { postCreated: { id: '1' } });

    // Receive event
    const first = await iterator.next();
    expect(first.value.data.postCreated.id).toBe('1');

    // Return to close (simulate client disconnecting)
    await iterator.return();

    // Trigger another event
    pubsub.publish('POST_CREATED', { postCreated: { id: '2' } });

    // Should not receive (iterator is closed)
    const second = await iterator.next();
    expect(second.done).toBe(true);
  });
});
```

