# test_serialization.py
import unittest
import datetime
from google.protobuf.timestamp_pb2 import Timestamp
from generated import user_pb2

class TestUserMessage(unittest.TestCase):
    def setUp(self):
        self.user = user_pb2.User()
        self.user.id = "123"
        self.user.name = "Test User"
        self.user.email = "test@example.com"
        self.user.age = 30
        self.user.tags.extend(["premium", "vip"])

        # Set timestamp
        self.user.created_at.GetCurrentTime()
        self.user.status = user_pb2.User.ACTIVE

    def test_serialize_deserialize(self):
        # Serialize to binary
        binary_data = self.user.SerializeToString()

        # Deserialize back
        new_user = user_pb2.User()
        new_user.ParseFromString(binary_data)

        # Verify all fields match
        self.assertEqual(new_user.id, "123")
        self.assertEqual(new_user.name, "Test User")
        self.assertEqual(new_user.email, "test@example.com")
        self.assertEqual(new_user.age, 30)
        self.assertEqual(list(new_user.tags), ["premium", "vip"])
        self.assertEqual(new_user.status, user_pb2.User.ACTIVE)

    def test_json_conversion(self):
        from google.protobuf import json_format

        # Convert to JSON
        json_str = json_format.MessageToJson(self.user)

        # Parse back
        new_user = user_pb2.User()
        json_format.Parse(json_str, new_user)

        self.assertEqual(new_user.id, "123")

    def test_required_fields(self):
        # Test that required fields are present
        required_fields = ['id', 'name', 'email']
        for field in required_fields:
            self.assertTrue(self.user.HasField(field))

    def test_field_validations(self):
        # Test email format (custom validation)
        self.assertIn('@', self.user.email)

        # Test age range
        self.assertGreaterEqual(self.user.age, 0)
        self.assertLessEqual(self.user.age, 150)

        # Test enum values
        self.assertIn(self.user.status, 
                      [user_pb2.User.UNKNOWN,
                       user_pb2.User.ACTIVE,
                       user_pb2.User.INACTIVE,
                       user_pb2.User.DELETED])

class TestMessageDefaults(unittest.TestCase):
    def test_default_values(self):
        user = user_pb2.User()

        # Default values should be zero/empty
        self.assertEqual(user.id, "")
        self.assertEqual(user.name,"")
        self.assertEqual(user.email, "")
        self.assertEqual(user.age, 0)
        self.assertEqual(list(user.tags), [])
        self.assertEqual(user.status, user_pb2.User.UNKNOWN)

        # created_at is optional, should not be set
        self.assertFalse(user.HasField('created_at'))
