  validWs.on('open', () => {
    expect(validWs.readyState).toBe(WebSocket.OPEN);
    validWs.close();

    // Invalid token
    const invalidWs = new WebSocket(`ws://localhost:${port}`, {
      headers: {
        'Authorization': 'Bearer invalid-token'
      }
    });

    invalidWs.on('open', () => {
      done(new Error('Should not open with invalid token'));
    });

    invalidWs.on('close', (code, reason) => {
      expect(code).toBe(1008); // Policy violation
      done();
    });
  });
});

