**Custom Test Framework**

```javascript
// websocket-test-framework.js
class WebSocketTestFramework {
  constructor(url) {
    this.url = url;
    this.clients = [];
    this.messageLogs = [];
  }

  async createClient(options = {}) {
    return new Promise((resolve, reject) => {
      const ws = new WebSocket(this.url, options.protocols);

      if (options.headers) {
        // Headers only work in Node.js 'ws' library
        // Browser WebSocket doesn't support custom headers
      }

      ws.onopen = () => {
        ws.id = Math.random().toString(36).substring(7);
        this.clients.push(ws);
        resolve(ws);
      };

      ws.onerror = (err) => reject(err);

      ws.onmessage = (event) => {
        this.messageLogs.push({
          clientId: ws.id,
          time: Date.now(),
          data: event.data
        });

        if (ws.messageHandler) {
          ws.messageHandler(event.data);
        }
      };
    });
  }

  setMessageHandler(client, handler) {
    client.messageHandler = handler;
  }

  async send(client, message) {
    return new Promise((resolve, reject) => {
      client.send(message);
      resolve();
    });
  }

  async broadcast(message) {
    await Promise.all(
      this.clients.map(client => this.send(client, message))
    );
  }

  async waitForMessage(client, predicate, timeout = 5000) {
    return new Promise((resolve, reject) => {
      const startTime = Date.now();
      const checkLog = () => {
        const message = this.messageLogs
          .filter(log => log.clientId === client.id)
          .find(log => predicate(JSON.parse(log.data)));

        if (message) {
          resolve(JSON.parse(message.data));
        } else if (Date.now() - startTime > timeout) {
          reject(new Error('Timeout waiting for message'));
        } else {
          setTimeout(checkLog, 100);
        }
      };

      checkLog();
    });
  }

  async closeClient(client) {
    return new Promise((resolve) => {
      client.onclose = () => {
        this.clients = this.clients.filter(c => c !== client);
        resolve();
      };
      client.close();
    });
  }

  async closeAll() {
    await Promise.all(this.clients.map(c => this.closeClient(c)));
    this.clients = [];
    this.messageLogs = [];
  }
}

// Usage
const framework = new WebSocketTestFramework('ws://localhost:8080');

test('should broadcast messages', async () => {
  const client1 = await framework.createClient();
  const client2 = await framework.createClient();
  const client3 = await framework.createClient();

  let received = [];

  [client1, client2, client3].forEach(client => {
    framework.setMessageHandler(client, (data) => {
      received.push(JSON.parse(data));
    });
  });

  await framework.send(client1, JSON.stringify({
    type: 'broadcast',
    text: 'Hello all'
  }));

  // Wait for messages
  await new Promise(resolve => setTimeout(resolve, 500));

  expect(received.length).toBe(3);
  await framework.closeAll();
});
```

