// message-throughput.js
async function testMessageThroughput(url, numConnections, messagesPerSecond, duration) {
  const connections = [];
  const received = new Array(numConnections).fill(0);
  const startTime = Date.now();

  console.log(`Testing message throughput...`);
  console.log(`Connections: ${numConnections}`);
  console.log(`Messages per second: ${messagesPerSecond}`);
  console.log(`Duration: ${duration}s`);

  // Create connections
  for (let i = 0; i < numConnections; i++) {
    const ws = new WebSocket(url);

    ws.on('open', () => {
      // Connection ready
    });

    ws.on('message', () => {
      received[i]++;
    });

    connections.push(ws);
  }

  // Wait for all connections to establish
  await new Promise(resolve => setTimeout(resolve, 2000));

  // Start sending messages
  const messagesSent = 0;
  const sendInterval = setInterval(() => {
    const message = JSON.stringify({
      type: 'test',
      time: Date.now(),
      data: 'x'.repeat(100) // 100-byte payload
    });

    connections.forEach(ws => {
      if (ws.readyState === WebSocket.OPEN) {
        ws.send(message);
        messagesSent++;
      }
    });
  }, 1000 / messagesPerSecond);

  await new Promise(resolve => setTimeout(resolve, duration * 1000));
  clearInterval(sendInterval);

  // Collect stats
  const totalReceived = received.reduce((a, b) => a + b, 0);
  const avgPerConnection = totalReceived / numConnections;

  console.log(`\nResults:`);
  console.log(`  Total received: ${totalReceived}`);
  console.log(`  Avg per connection: ${avgPerConnection.toFixed(1)}`);
  console.log(`  Throughput: ${(totalReceived/duration).toFixed(1)} msg/s`);

  connections.forEach(ws => ws.close());
}

