```javascript
// rate-limit.test.js
describe('Rate Limiting', () => {
  test('should limit message rate per connection', (done) => {
    const ws = new WebSocket(`ws://localhost:${port}`);
    let messagesSent = 0;
    let limited = false;

    ws.on('open', () => {
      // Send messages as fast as possible
      const interval = setInterval(() => {
        ws.send(JSON.stringify({ type: 'ping' }));
        messagesSent++;
      }, 1);

      // Stop after 1 second
      setTimeout(() => {
        clearInterval(interval);
      }, 1000);
    });

    ws.on('message', (data) => {
      const response = JSON.parse(data.toString());
      if (response.type === 'error' && response.message.includes('rate limit')) {
        limited = true;
      }
    });

    ws.on('close', () => {
      expect(limited).toBe(true);
      expect(messagesSent).toBeGreaterThan(100); // Rate limit should trigger
      done();
    });
  });

  test('should have per-connection rate limits', (done) => {
    const ws1 = new WebSocket(`ws://localhost:${port}`);
    const ws2 = new WebSocket(`ws://localhost:${port}`);

    let ws1Limited = false;
    let ws2Limited = false;

    function sendRapidly(ws) {
      for (let i = 0; i < 1000; i++) {
        ws.send(JSON.stringify({ type: 'ping' }));
      }
    }

    ws1.on('open', () => sendRapidly(ws1));
    ws2.on('open', () => sendRapidly(ws2));

    ws1.on('message', (data) => {
      const response = JSON.parse(data.toString());
      if (response.type === 'error' && response.message.includes('rate limit')) {
        ws1Limited = true;
      }
    });

    ws2.on('message', (data) => {
      const response = JSON.parse(data.toString());
      if (response.type === 'error' && response.message.includes('rate limit')) {
        ws2Limited = true;
      }
    });

    setTimeout(() => {
      expect(ws1Limited).toBe(true);
      expect(ws2Limited).toBe(true);
      ws1.close();
      ws2.close();
      done();
    }, 2000);
  });
});
