@Test
void testMessageOrdering() throws Exception {
    String topic = "ordered-topic";

    // Send messages with same key (goes to same partition)
    for (int i = 0; i < 10; i++) {
        producer.send(new ProducerRecord<>(topic, "same-key", "message-" + i)).get();
    }

    // Consume and verify order
    consumer.subscribe(Collections.singletonList(topic));
    ConsumerRecords<String, String> records = consumer.poll(Duration.ofSeconds(5));

    int expected = 0;
    for (ConsumerRecord<String, String> record : records) {
        assertEquals("message-" + expected, record.value());
        expected++;
    }
}
