name: Check for Breaking Changes

on:
  pull_request:
    paths:
      - 'openapi.yaml'

jobs:
  check-breaking:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
        with:
          fetch-depth: 2

      - name: Get previous version from main branch
        run: |
          git fetch origin main
          git show origin/main:openapi.yaml > openapi-previous.yaml

      - name: Install oas-diff
        run: npm install -g oas-diff

      - name: Compare versions
        id: compare
        run: |
          oas-diff openapi-previous.yaml openapi.yaml --json > diff.json
          BREAKING=$(jq '.breaking | length' diff.json)
          NON_BREAKING=$(jq '.non_breaking | length' diff.json)
          DEPRECATIONS=$(jq '.deprecations | length' diff.json)

          echo "breaking=$BREAKING" >> $GITHUB_OUTPUT
          echo "non_breaking=$NON_BREAKING" >> $GITHUB_OUTPUT
          echo "deprecations=$DEPRECATIONS" >> $GITHUB_OUTPUT

          if [ "$BREAKING" -gt 0 ]; then
            echo "❌ Found $BREAKING breaking changes"
            jq '.breaking' diff.json
            exit 1
          fi
          echo "✅ No breaking changes"

      - name: Comment PR
        uses: actions/github-script@v6
        if: always()
        with:
          script: |
            const fs = require('fs');
            const diff = JSON.parse(fs.readFileSync('diff.json'));

            let comment = '## 🔍 OpenAPI Change Report\n\n';

            if (diff.breaking.length > 0) {
              comment += '### ❌ Breaking Changes\n';
              diff.breaking.forEach(change => {
                comment += `- ${change}\n`;
              });
              comment += '\n';
            } else {
              comment += '### ✅ No Breaking Changes\n\n';
            }

            if (diff.non_breaking.length > 0) {
              comment += '### 🟢 Non-breaking Additions\n';
              diff.non_breaking.forEach(change => {
                comment += `- ${change}\n`;
              });
              comment += '\n';
            }

            if (diff.deprecations.length > 0) {
              comment += '### ⚠️ Deprecations\n';
              diff.deprecations.forEach(change => {
                comment += `- ${change}\n`;
              });
              comment += '\n';
            }

            github.rest.issues.createComment({
              issue_number: context.issue.number,
              owner: context.repo.owner,
              repo: context.repo.repo,
              body: comment
            });

