    def test_concurrent_duplicate_requests(self):
        """Concurrent requests with same idempotency key - only one succeeds"""
        idempotency_key = str(uuid.uuid4())

        payment_data = {
            "amount": 5000,  # $50.00
            "currency": "USD",
            "paymentMethod": {
                "type": "card",
                "card": {
                    "number": "4111111111111111",
                    "expiryMonth": 12,
                    "expiryYear": 2026,
                    "cvv": "123"
                }
            },
            "idempotencyKey": idempotency_key
        }

        def send_request():
            return requests.post(
                f"{self.BASE_URL}/payments",
                json=payment_data,
                headers={"X-API-Key": self.API_KEY}
            )

        # Send 5 concurrent requests
        with ThreadPoolExecutor(max_workers=5) as executor:
            futures = [executor.submit(send_request) for _ in range(5)]
            responses = [f.result() for f in futures]

        # Count successes
        successes = [r for r in responses if r.status_code == 200]
        conflicts = [r for r in responses if r.status_code == 409]

        # Exactly one should succeed, others should get 409 Conflict
        assert len(successes) == 1
        assert len(conflicts) == 4

        # All successes should have same payment ID
        payment_id = successes[0].json()['id']
        for conflict in conflicts:
            data = conflict.json()
            assert data['code'] == 'IDEMPOTENCY_CONFLICT'
            assert data['existing_payment_id'] == payment_id

