    def test_idempotency_key_with_failed_payments(self):
        """Even failed payments should be idempotent"""
        idempotency_key = str(uuid.uuid4())

        # Request with insufficient funds
        payment_data = {
            "amount": 999999,  # Very large amount
            "currency": "USD",
            "paymentMethod": {
                "type": "card",
