        # Configure webhook endpoint to fail first time
        call_count = 0

        def webhook_handler(request):
            nonlocal call_count
            call_count += 1
            if call_count == 1:
                return (500, {}, {'error': 'Internal error'})
            return (200, {}, {'status': 'ok'})

        wiremock_server.stub_with_function(
            method='POST',
            url='/webhooks/endpoint',
            response_func=webhook_handler
        )

        # Simulate external service sending webhook
        # The external service should retry on failure
        # This test verifies our webhook receiver can handle retries

        # First attempt (fails)
        response = requests.post(
            wiremock_server.url + '/webhooks/endpoint',
            json={'event': 'test'}
        )
        assert response.status_code == 500

        # Wait for retry (simulated)
