                    f"{BASE_URL}/webhooks/slow",
                    json={'event': 'test'},
                    timeout=3
                )
            except requests.exceptions.Timeout:
                # Expected - webhook should timeout
                pass

            duration = time.time() - start
            assert duration < 4

    def test_webhook_event_type_handling(self):
        """Test that different webhook event types are handled correctly"""
        events = [
            ('payment.succeeded', 200),
            ('payment.failed', 200),
            ('payment.refunded', 200),
            ('customer.created', 200),
            ('unknown.event', 400)  # Unknown event should be rejected
        ]

        for event_type, expected_status in events:
            payload = {
                'id': f'evt_{uuid.uuid4()}',
                'type': event_type,
                'data': {}
            }
            headers = {'X-Signature': create_webhook_signature(payload)}

            response = requests.post(
                f"{BASE_URL}/webhooks/stripe",
                json=payload,
