import hashlib
import random
import re
from faker import Faker

fake = Faker()

class DataMasker:
    """Mask sensitive data for test environments"""

    def __init__(self, seed=None):
        """Initialize with optional seed for reproducible masking"""
        if seed:
            random.seed(seed)
            Faker.seed(seed)

    def mask_email(self, email):
        """Mask email address while preserving format"""
        if not email or '@' not in email:
            return email

        local_part, domain = email.split('@')
        # Generate fake email with same domain
        fake_local = fake.user_name()
        return f"{fake_local}@{domain}"

    def mask_name(self, name):
        """Replace real name with fake name"""
        if not name:
            return name
        return fake.name()

    def mask_phone(self, phone):
        """Mask phone number while preserving format"""
        if not phone:
            return phone

        # Extract digits
        digits = re.sub(r'\D', '', phone)
        if not digits:
            return phone

        # Generate fake phone with same number of digits
        fake_digits = ''.join([str(random.randint(0, 9)) for _ in range(len(digits))])

        # Preserve original formatting
        result = phone
        for d in fake_digits:
            result = result.replace('?', d, 1) if '?' in result else result.replace(digits[0], d, 1)
            digits = digits[1:]

        return result

    def mask_address(self, address):
        """Mask address with fake address"""
        if not address:
            return address

        return {
            "street": fake.street_address(),
            "city": fake.city(),
            "state": fake.state_abbr(),
            "zip": fake.zipcode(),
            "country": address.get("country", fake.country_code())
        }

    def mask_credit_card(self, card_number):
        """Mask credit card number (preserve last 4 digits)"""
        if not card_number or len(card_number) < 4:
            return card_number

        # Keep last 4 digits, replace rest with X
        visible = card_number[-4:]
        masked = 'X' * (len(card_number) - 4) + visible

        # Preserve formatting (spaces, dashes)
        result = ''
        digit_count = 0
        for char in card_number:
            if char.isdigit():
                result += masked[digit_count]
                digit_count += 1
            else:
                result += char

        return result

    def mask_ssn(self, ssn):
        """Mask Social Security Number"""
        if not ssn:
            return ssn

        # Keep last 4, mask rest
        digits = re.sub(r'\D', '', ssn)
        if len(digits) != 9:
            return ssn

        masked = f"XXX-XX-{digits[-4:]}"
        return masked

    def mask_with_token(self, value, namespace='default'):
        """Create deterministic token from value"""
        if not value:
            return value

        # Create consistent hash
        hash_input = f"{namespace}:{value}".encode('utf-8')
        token = hashlib.sha256(hash_input).hexdigest()[:16]
        return f"tok_{token}"

    def mask_record(self, record, rules):
        """Apply multiple masking rules to a record"""
        masked = record.copy()

        for field, rule in rules.items():
            if field in masked:
                if rule == 'email':
                    masked[field] = self.mask_email(masked[field])
                elif rule == 'name':
                    masked[field] = self.mask_name(masked[field])
                elif rule == 'phone':
                    masked[field] = self.mask_phone(masked[field])
                elif rule == 'address':
                    masked[field] = self.mask_address(masked[field])
                elif rule == 'credit_card':
                    masked[field] = self.mask_credit_card(masked[field])
                elif rule == 'ssn':
                    masked[field] = self.mask_ssn(masked[field])
                elif rule == 'token':
                    masked[field] = self.mask_with_token(masked[field], field)

        return masked


