import pytest
from dataclasses import dataclass
from typing import Optional, List, Dict, Any


@dataclass
class User:
    """User entity for testing"""
    id: Optional[str] = None
    username: Optional[str] = None
    email: Optional[str] = None
    first_name: Optional[str] = None
    last_name: Optional[str] = None
    is_active: bool = True
    role: str = "user"

    def to_dict(self):
        """Convert to dictionary for API requests"""
        return {k: v for k, v in self.__dict__.items() if v is not None}


class UserFactory:
    """Factory for creating test users"""

    _counter = 0

    @classmethod
    def _next_id(cls):
        cls._counter += 1
        return f"user_{cls._counter}"

    @classmethod
    def create(cls, **kwargs) -> User:
        """Create a user with default values overridden by kwargs"""
        defaults = {
            "id": cls._next_id(),
            "username": f"testuser_{cls._counter}",
            "email": f"test{cls._counter}@example.com",
            "first_name": "Test",
            "last_name": f"User{cls._counter}",
            "is_active": True,
            "role": "user"
        }
        defaults.update(kwargs)
        return User(**defaults)

    @classmethod
    def create_batch(cls, count: int, **kwargs) -> List[User]:
        """Create multiple users"""
        return [cls.create(**kwargs) for _ in range(count)]

    @classmethod
    def admin(cls, **kwargs) -> User:
        """Create an admin user"""
        defaults = {"role": "admin"}
        defaults.update(kwargs)
        return cls.create(**defaults)

    @classmethod
    def inactive(cls, **kwargs) -> User:
