class OrderFactory:
    """Factory for creating test orders"""

    _counter = 0

    @classmethod
    def _next_id(cls):
        cls._counter += 1
        return f"order_{cls._counter}"

    @classmethod
    def create(cls, user=None, products=None, **kwargs) -> Order:
        """Create an order with optional user and products"""
        if user is None:
            user = UserFactory.create()

        if products is None:
            products = [ProductFactory.create() for _ in range(random.randint(1, 3))]

        items = []
        total = 0
        for product in products:
            quantity = random.randint(1, 2)
            items.append({
                "product_id": product.id,
                "quantity": quantity,
                "price": product.price,
                "subtotal": product.price * quantity
            })
            total += product.price * quantity

        defaults = {
            "id": cls._next_id(),
            "user_id": user.id,
            "items": items,
            "total": round(total, 2),
            "status": "pending"
        }
        defaults.update(kwargs)
        return Order(**defaults)

    @classmethod
    def paid(cls, **kwargs) -> Order:
        defaults = {"status": "paid"}
        defaults.update(kwargs)
        return cls.create(**defaults)

    @classmethod
    def shipped(cls, **kwargs) -> Order:
        defaults = {"status": "shipped"}
        defaults.update(kwargs)
        return cls.create(**defaults)


