import os
import json
from enum import Enum

class TestEnvironment(Enum):
    LOCAL = "local"
    CI = "ci"
    STAGING = "staging"
    PRODUCTION = "production"


class EnvironmentDataManager:
    """Manage test data based on environment"""

    def __init__(self):
        self.env = self.detect_environment()
        self.data = self.load_environment_data()

    def detect_environment(self):
        """Detect current test environment"""
        if os.getenv('CI'):
            return TestEnvironment.CI
        elif os.getenv('STAGING'):
            return TestEnvironment.STAGING
        elif os.getenv('PRODUCTION'):
            return TestEnvironment.PRODUCTION
        else:
            return TestEnvironment.LOCAL

    def load_environment_data(self):
        """Load data specific to current environment"""
        base_data = self.load_json('test_data/base.json')

        try:
            env_data = self.load_json(f'test_data/{self.env.value}.json')
            base_data.update(env_data)
        except FileNotFoundError:
            pass

        return base_data

    def load_json(self, path):
        """Load JSON file"""
        with open(path, 'r') as f:
            return json.load(f)

    def get_test_user(self):
        """Get test user appropriate for environment"""
        if self.env == TestEnvironment.PRODUCTION:
            # In production, use synthetic data only
            return self.data['synthetic_users'][0]
        elif self.env == TestEnvironment.STAGING:
            # In staging, use anonymized production users
            return self.data['staging_users'][0]
        else:
            # Local/CI: use simple test users
            return self.data['test_users'][0]

    def get_api_credentials(self):
        """Get API credentials for current environment"""
        return self.data['credentials'].get(self.env.value, {})

    def get_database_config(self):
        """Get database config for current environment"""
        return self.data['databases'].get(self.env.value, {})


