class EnvironmentAwareTest:
    """Base class for environment-aware tests"""

    @classmethod
    def setup_class(cls):
        cls.data_manager = EnvironmentDataManager()

    def skip_if_production(self):
        """Skip test in production environment"""
        if self.data_manager.env == TestEnvironment.PRODUCTION:
            pytest.skip("This test should not run in production")

    def skip_if_not_local(self):
        """Skip test if not in local environment"""
        if self.data_manager.env != TestEnvironment.LOCAL:
            pytest.skip("This test only runs locally")


