import json
import yaml
import requests
from openapi_core import create_spec
from openapi_core.validation.request.datatypes import RequestParameters
import jsonschema_faker

class OpenAPIPayloadGenerator:
    """Generate test payloads from OpenAPI specifications"""

    def __init__(self, spec_path):
        """Load OpenAPI specification"""
        with open(spec_path, 'r') as f:
            if spec_path.endswith('.yaml') or spec_path.endswith('.yml'):
                spec_dict = yaml.safe_load(f)
            else:
                spec_dict = json.load(f)

        self.spec = spec_dict

    def get_request_body_schema(self, path, method):
        """Extract request body schema for an endpoint"""
        try:
            operation = self.spec['paths'][path][method]
            if 'requestBody' in operation:
                content = operation['requestBody']['content']
                # Prefer application/json
                if 'application/json' in content:
                    schema = content['application/json']['schema']
                    return schema
        except KeyError:
            return None

    def get_response_schema(self, path, method, status_code='200'):
        """Extract response schema for an endpoint"""
        try:
            operation = self.spec['paths'][path][method]
            responses = operation['responses']
            if status_code in responses:
                content = responses[status_code].get('content', {})
                if 'application/json' in content:
                    return content['application/json']['schema']
        except KeyError:
            return None

    def generate_request_payload(self, path, method):
        """Generate a valid request payload for an endpoint"""
        schema = self.get_request_body_schema(path, method)
        if schema:
            return jsonschema_faker.generate(schema)
        return None

    def generate_response_payload(self, path, method, status_code='200'):
        """Generate a valid response payload for an endpoint"""
        schema = self.get_response_schema(path, method, status_code)
        if schema:
            return jsonschema_faker.generate(schema)
        return None

    def generate_path_parameters(self, path):
        """Generate path parameters based on path template"""
        import re
        params = {}
        # Find all {param} in path
        placeholders = re.findall(r'\{(.*?)\}', path)

        for param in placeholders:
            # Try to find parameter schema in spec
            param_schema = self.find_parameter_schema(path, param)
            if param_schema:
                params[param] = jsonschema_faker.generate(param_schema)
            else:
                # Default generation
                params[param] = jsonschema_faker.generate({
                    "type": "string",
                    "faker": "uuid4"
                })

        return params

    def find_parameter_schema(self, path, param_name):
        """Find schema for a path parameter"""
        try:
            path_item = self.spec['paths'][path]
            # Parameters can be at path level or operation level
            params = path_item.get('parameters', [])
            for param in params:
                if param.get('name') == param_name and param.get('in') == 'path':
                    return param.get('schema')
        except KeyError:
            pass
        return None

    def generate_test_cases(self, path, method, count=10):
        """Generate multiple test cases for an endpoint"""
        test_cases = []
        for i in range(count):
            test_case = {
                "path_parameters": self.generate_path_parameters(path),
                "query_parameters": self.generate_query_parameters(path, method),
                "request_body": self.generate_request_payload(path, method)
            }
            test_cases.append(test_case)
        return test_cases


