class ProductionDataAnonymizer:
    """Anonymize production data for test environments"""

    def __init__(self, rules: Dict[str, str]):
        self.anonymizer = DataAnonymizer(seed=42)
        self.rules = rules
        self.token_mappings = {}

    def anonymize_user(self, user: Dict) -> Dict:
        """Anonymize a user record"""
        anonymized = {}

        for key, value in user.items():
            if key in self.rules:
                rule = self.rules[key]

                if rule == 'tokenize':
                    # Use consistent tokenization across records
                    if value not in self.token_mappings:
                        self.token_mappings[value] = self.anonymizer.tokenize(value, key)
                    anonymized[key] = self.token_mappings[value]
                elif rule == 'substitute_name':
                    # For names, we want consistency per user but not across users
                    # This is simplified - in practice you'd want consistent substitutions
                    anonymized[key] = self.anonymizer.substitute_name()
                else:
                    # Apply the rule
                    method = getattr(self.anonymizer, rule)
                    anonymized[key] = method(value)
            else:
                # Keep non-sensitive fields as-is
                anonymized[key] = value

        return anonymized

    def anonymize_database_export(self, input_file: str, output_file: str):
        """Anonymize an entire database export"""
        with open(input_file, 'r') as f:
            data = json.load(f)

        anonymized = {
            'metadata': {
                'original_file': input_file,
                'anonymized_at': datetime.now().isoformat(),
                'rules_applied': self.rules
            },
            'users': [self.anonymize_user(user) for user in data.get('users', [])]
        }

        with open(output_file, 'w') as f:
            json.dump(anonymized, f, indent=2)

        print(f"Anonymized {len(anonymized['users'])} users")
        print(f"Output saved to {output_file}")


