from cryptography.fernet import Fernet
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2
import logging
from typing import Dict, Any, Optional


class SecureTestDataStorage:
    """Securely store test data with encryption"""

    def __init__(self, key_file: Optional[str] = None):
        self.key_file = key_file or os.path.expanduser('~/.test_data_key')
        self.key = self._load_or_create_key()
        self.cipher = Fernet(self.key)
        self.logger = logging.getLogger(__name__)

    def _load_or_create_key(self) -> bytes:
        """Load existing key or create new one"""
        if os.path.exists(self.key_file):
            with open(self.key_file, 'rb') as f:
                return f.read()
        else:
            # Generate new key
            key = Fernet.generate_key()
            # Save with restricted permissions
            with open(self.key_file, 'wb') as f:
                f.write(key)
            os.chmod(self.key_file, 0o600)  # Read/write for owner only
            return key

    def encrypt_data(self, data: Any) -> str:
        """Encrypt test data"""
        json_str = json.dumps(data)
        encrypted = self.cipher.encrypt(json_str.encode())
        return base64.urlsafe_b64encode(encrypted).decode()

    def decrypt_data(self, encrypted_data: str) -> Any:
        """Decrypt test data"""
        try:
            encrypted = base64.urlsafe_b64decode(encrypted_data.encode())
            decrypted = self.cipher.decrypt(encrypted)
            return json.loads(decrypted.decode())
        except Exception as e:
            self.logger.error(f"Failed to decrypt data: {e}")
            raise

    def save_encrypted_file(self, data: Any, filename: str):
        """Save encrypted data to file"""
        encrypted = self.encrypt_data(data)
        with open(filename, 'w') as f:
            f.write(encrypted)
        os.chmod(filename, 0o600)  # Restrict permissions
        self.logger.info(f"Encrypted data saved to {filename}")

    def load_encrypted_file(self, filename: str) -> Any:
        """Load and decrypt data from file"""
        with open(filename, 'r') as f:
            encrypted = f.read()
        return self.decrypt_data(encrypted)


class SecureCredentialManager:
    """Manage test credentials securely"""

    def __init__(self):
        self.storage = SecureTestDataStorage()
        self.credentials = {}
        self._load_credentials()

    def _load_credentials(self):
        """Load credentials from secure storage"""
        cred_file = os.path.expanduser('~/.test_credentials.enc')
        if os.path.exists(cred_file):
            try:
                self.credentials = self.storage.load_encrypted_file(cred_file)
            except Exception as e:
                self.logger.error(f"Failed to load credentials: {e}")

    def _save_credentials(self):
        """Save credentials to secure storage"""
        cred_file = os.path.expanduser('~/.test_credentials.enc')
        self.storage.save_encrypted_file(self.credentials, cred_file)

    def add_credential(self, key: str, value: str, environment: str = 'default'):
        """Add a credential for an environment"""
        if environment not in self.credentials:
            self.credentials[environment] = {}
        self.credentials[environment][key] = value
        self._save_credentials()

    def get_credential(self, key: str, environment: str = 'default') -> Optional[str]:
        """Get a credential for an environment"""
        return self.credentials.get(environment, {}).get(key)

    def list_environments(self) -> list:
        """List available environments"""
        return list(self.credentials.keys())


class TestDataVault:
    """Vault for storing test datasets securely"""

    def __init__(self, vault_dir: str = './vault'):
        self.vault_dir = vault_dir
        self.storage = SecureTestDataStorage()
        os.makedirs(vault_dir, exist_ok=True)

    def _get_dataset_path(self, dataset_name: str) -> str:
        """Get path for dataset"""
        return os.path.join(self.vault_dir, f"{dataset_name}.enc")

    def store_dataset(self, dataset_name: str, data: Any, metadata: Dict = None):
        """Store a dataset in the vault"""
        # Add metadata
        if metadata is None:
            metadata = {}

        package = {
            'data': data,
            'metadata': {
                'created_at': datetime.now().isoformat(),
                'name': dataset_name,
                **metadata
            }
        }

        path = self._get_dataset_path(dataset_name)
        self.storage.save_encrypted_file(package, path)
        print(f"Dataset '{dataset_name}' stored in vault")

    def load_dataset(self, dataset_name: str) -> Any:
        """Load a dataset from the vault"""
        path = self._get_dataset_path(dataset_name)
        if not os.path.exists(path):
            raise FileNotFoundError(f"Dataset '{dataset_name}' not found")

        package = self.storage.load_encrypted_file(path)
        return package['data']

    def list_datasets(self) -> List[Dict]:
        """List all datasets in vault"""
        datasets = []
        for filename in os.listdir(self.vault_dir):
            if filename.endswith('.enc'):
                path = os.path.join(self.vault_dir, filename)
                try:
                    package = self.storage.load_encrypted_file(path)
                    datasets.append({
                        'name': filename[:-4],
                        'metadata': package.get('metadata', {}),
                        'size': os.path.getsize(path)
                    })
                except Exception as e:
                    print(f"Error reading {filename}: {e}")
        return datasets

    def delete_dataset(self, dataset_name: str):
        """Delete a dataset from vault"""
        path = self._get_dataset_path(dataset_name)
        if os.path.exists(path):
            os.remove(path)
            print(f"Dataset '{dataset_name}' deleted from vault")


