                'can_delete': False
            },
            'admin': {
                'can_read': ['dev', 'test', 'staging', 'prod'],
                'can_write': ['dev', 'test', 'staging'],
                'can_delete': True
            },
            'auditor': {
                'can_read': ['all'],
                'can_write': False,
                'can_delete': False
            }
        }
        self.access_log = []

    def check_access(self, user: str, environment: str, action: str) -> bool:
        """Check if user has access to environment"""
        # Get user role (in practice, from auth system)
        role = self.get_user_role(user)

        if role not in self.roles:
            return False

        role_config = self.roles[role]

        if action == 'read':
            allowed = 'all' in role_config['can_read'] or environment in role_config['can_read']
        elif action == 'write':
            allowed = environment in role_config['can_write']
        elif action == 'delete':
            allowed = role_config['can_delete']
        else:
            allowed = False

        # Log access attempt
        self.log_access(user, environment, action, allowed)

        return allowed

    def get_user_role(self, user: str) -> str:
        """Get role for user (simplified)"""
        # In practice, this would query an auth system
        roles = {
            'alice': 'admin',
            'bob': 'developer',
            'charlie': 'tester',
            'diana': 'auditor'
        }
        return roles.get(user, 'developer')

    def log_access(self, user: str, environment: str, action: str, allowed: bool):
        """Log access attempt for audit"""
        log_entry = {
            'timestamp': datetime.now().isoformat(),
            'user': user,
            'environment': environment,
            'action': action,
            'allowed': allowed
        }
        self.access_log.append(log_entry)

        if not allowed:
            logging.warning(f"DENIED: {user} attempted {action} on {environment}")


