    loaded = storage.load_encrypted_file('sensitive_data.enc')

    assert loaded == sensitive_test_data
    print("Secure storage test passed")

    # Clean up
    os.remove('sensitive_data.enc')


if __name__ == "__main__":
    test_secure_storage()

