                <td>${data.total}</td>
                <td class='pass'>${data.pass}</td>
                <td class='fail'>${data.fail}</td>
                <td>${(data.pass/data.total*100).toFixed(1)}%</td>
            </tr>
        `).join('');
    }

    setupFilters() {
