           ZoneId.of("Asia/Tokyo"),
           ZoneId.of("Europe/London")
       );

       String token = generateToken(expiresInMinutes(60));

       for (ZoneId zone : timezones) {
           Clock clock = Clock.system(zone);
           boolean valid = authService.validateToken(token, clock);
           assertTrue(valid, "Token should be valid in " + zone);
       }
   }
